class GoldenDUT:

    def __init__(self):
        # Define one-hot encoded states as binary values
        self.A = 0b000001
        self.B = 0b000010
        self.C = 0b000100
        self.D = 0b001000
        self.E = 0b010000
        self.F = 0b100000

    def _expected_Y1_Y3(self, y, w):
        # Output initialization
        Y1 = 0
        Y3 = 0

        # State transition logic based on the state diagram
        if y == self.A:
            if w == 1:
                Y1 = 1 # Transition to B
        elif y == self.B:
            if w == 0:
                Y3 = 1 # Transition to D
        elif y == self.C:
            if w == 0:
                Y3 = 1 # Transition to D
        elif y == self.D:
            pass # No Y1 or Y3 needed for transitions from D
        elif y == self.E:
            if w == 0:
                Y3 = 1 # Transition to D
        elif y == self.F:
            if w == 0:
                Y3 = 1 # Transition to D

        return Y1, Y3

    def load(self, signal_vector):
        y = signal_vector['y']
        w = signal_vector['w']
        # Compute the expected output values
        expected_Y1, expected_Y3 = self._expected_Y1_Y3(y, w)
        return expected_Y1, expected_Y3

    def check(self, signal_vector):
        # Load signal vector and get expected output
        expected_Y1, expected_Y3 = self.load(signal_vector)

        # Get DUT output
        Y1_DUT = signal_vector['Y1']
        Y3_DUT = signal_vector['Y3']

        # Compare expected outputs with DUT outputs
        return expected_Y1 == Y1_DUT and expected_Y3 == Y3_DUT

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
