class GoldenDUT:
    # State definitions
    STATE_A = 0
    STATE_B = 1
    STATE_C = 2
    STATE_D = 3

    def __init__(self):
        # Initialize state and output registers
        self.state_reg = self.STATE_A
        self.g_reg = [0, 0, 0]  # Output grants

    def load(self, signal_vector):
        # Load input signals
        resetn = signal_vector['resetn']
        r = [signal_vector['r'] & 0x1, (signal_vector['r'] >> 1) & 0x1, (signal_vector['r'] >> 2) & 0x1]

        # Reset functionality
        if resetn == 0:
            self.state_reg = self.STATE_A
            self.g_reg = [0, 0, 0]
        else:
            self.state_reg, self.g_reg = self.fsm_transition(r)

    def fsm_transition(self, r):
        # Determine next state and output based on current state and input r
        next_state = self.state_reg
        g = [0, 0, 0]

        if self.state_reg == self.STATE_A:
            if r[0] == 1:  # r1 has the highest priority
                next_state = self.STATE_B
                g[0] = 1
            elif r[1] == 1:  # r2 has second priority
                next_state = self.STATE_C
                g[1] = 1
            elif r[2] == 1:  # r3 has lowest priority
                next_state = self.STATE_D
                g[2] = 1

        elif self.state_reg == self.STATE_B:
            if r[0] == 1:
                next_state = self.STATE_B
                g[0] = 1
            else:
                next_state = self.STATE_A

        elif self.state_reg == self.STATE_C:
            if r[1] == 1:
                next_state = self.STATE_C
                g[1] = 1
            else:
                next_state = self.STATE_A

        elif self.state_reg == self.STATE_D:
            if r[2] == 1:
                next_state = self.STATE_D
                g[2] = 1
            else:
                next_state = self.STATE_A

        return next_state, g

    def check(self, signal_vector):
        if signal_vector['check_en']:
            g_observed = [signal_vector['g'] & 0x1, (signal_vector['g'] >> 1) & 0x1, (signal_vector['g'] >> 2) & 0x1]
            is_correct = self.g_reg == g_observed

            if not is_correct:
                print(f"Scenario: {signal_vector['scenario']}, expected: g={self.g_reg}, observed: g={g_observed}")

            return is_correct
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

