class GoldenDUT:
    def __init__(self):
        self.STATE_A = 0
        self.STATE_B = 1
        self.STATE_C = 2
        self.STATE_D = 3
        self.STATE_E = 4

        self.state_reg = self.STATE_A
        self.x_reg = 0
        self.y_reg = 0
        self.f_reg = 0
        self.g_reg = 0
        self.g_permanent_reg = False
        self.cycle_counter_reg = 0
        self.x_prev2 = 0  # Initialize x_prev2
        self.x_prev = 0   # Initialize x_prev

    def load(self, signal_vector):
        self.x_reg = signal_vector['x']
        self.y_reg = signal_vector['y']

        if not signal_vector['resetn']:
            self.state_reg = self.STATE_A
            self.g_permanent_reg = False
            self.f_reg = 0
            self.g_reg = 0
            self.cycle_counter_reg = 0  # Reset cycle counter
        else:
            if self.state_reg == self.STATE_A:
                self.f_reg = 0  # Ensure f is reset
                self.state_reg = self.STATE_B

            elif self.state_reg == self.STATE_B:
                self.f_reg = 1
                self.state_reg = self.STATE_C

            elif self.state_reg == self.STATE_C:
                self.f_reg = 0
                if self.x_reg == 1 and self.x_prev2 == 1 and self.x_prev == 0:
                    self.g_reg = 1
                    self.state_reg = self.STATE_D
                else:
                    self.g_reg = 0

            elif self.state_reg == self.STATE_D:
                self.g_reg = 1
                self.cycle_counter_reg = 0
                self.state_reg = self.STATE_E

            elif self.state_reg == self.STATE_E:
                if not self.g_permanent_reg:
                    if self.y_reg == 1:
                        self.g_reg = 1
                        self.g_permanent_reg = True
                    else:
                        self.cycle_counter_reg += 1
                        if self.cycle_counter_reg >= 2:
                            self.g_reg = 0
                            self.state_reg = self.STATE_C
                else:
                    self.g_reg = 1

        self.x_prev2 = self.x_prev
        self.x_prev = self.x_reg

    def check(self, signal_vector):
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']

        if self.f_reg != f_observed or self.g_reg != g_observed:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: f={self.f_reg}, g={self.g_reg}, "
                  f"observed: f={f_observed}, g={g_observed}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
