class GoldenDUT:
    def __init__(self):
        # Initialize states and outputs
        self.STATE_A = 0
        self.STATE_B = 1
        self.STATE_C = 2
        self.STATE_D = 3

        self.state_reg = self.STATE_A
        self.f_reg = 0
        self.g_reg = 0

        # Initialize sequence counters and flags
        self.x_sequence_count_reg = 0
        self.y_monitor_cycle_reg = 0
        self.monitor_y_reg = False

    def load(self, signal_vector):
        # Process the load for a new clock cycle with the given signal vector
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        # FSM behavior simulation on load (new clock cycle)
        if resetn == 0:
            self.reset_fsm()
        else:
            self.fsm_cycle(x, y)

    def check(self, signal_vector):
        # Determine expected outputs based on internal state
        expected_f = self.f_reg
        expected_g = self.g_reg

        # Compare with DUT outputs
        observed_f = signal_vector['f']
        observed_g = signal_vector['g']

        if observed_f != expected_f or observed_g != expected_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, g={expected_g}, "
                  f"observed: f={observed_f}, g={observed_g}")
            return False
        return True

    def reset_fsm(self):
        # Reset the FSM to the initial state
        self.state_reg = self.STATE_A
        self.f_reg = 0
        self.g_reg = 0
        self.x_sequence_count_reg = 0
        self.y_monitor_cycle_reg = 0
        self.monitor_y_reg = False

    def fsm_cycle(self, x, y):
        # Transition the FSM based on current state and inputs
        if self.state_reg == self.STATE_A:
            self.f_reg = 1
            self.state_reg = self.STATE_B
        elif self.state_reg == self.STATE_B:
            self.f_reg = 0
            if x == 1 and self.x_sequence_count_reg == 0:
                self.x_sequence_count_reg = 1
            elif x == 0 and self.x_sequence_count_reg == 1:
                self.x_sequence_count_reg = 2
            elif x == 1 and self.x_sequence_count_reg == 2:
                self.g_reg = 1
                self.x_sequence_count_reg = 0
                self.monitor_y_reg = True
                self.y_monitor_cycle_reg = 0
                self.state_reg = self.STATE_C
            else:
                self.x_sequence_count_reg = 0
        elif self.state_reg == self.STATE_C:
            if self.monitor_y_reg:
                if y == 1:
                    self.g_reg = 1
                    self.monitor_y_reg = False
                else:
                    self.y_monitor_cycle_reg += 1
                    if self.y_monitor_cycle_reg >= 2:
                        self.g_reg = 0
                        self.monitor_y_reg = False

