class GoldenDUT:
    def __init__(self):
        self.state_reg = 'A'
        self.f_reg = 0
        self.g_reg = 0
        self.x_sequence = []
        self.y_countdown = 0

    def load(self, signal_vector):
        if signal_vector['resetn'] == 0:
            # Reset is asserted, return to initial state
            self.state_reg = 'A'
            self.f_reg = 0
            self.g_reg = 0
            self.x_sequence = []
            self.y_countdown = 0
        else:
            # State transitions based on current state and signals
            if self.state_reg == 'A' and self.f_reg == 0:
                self.f_reg = 1
            elif self.state_reg == 'A' and self.f_reg == 1:
                self.f_reg = 0
                self.state_reg = 'B'

            if self.state_reg == 'B':
                self.x_sequence.append(signal_vector['x'])
                if len(self.x_sequence) > 3:
                    self.x_sequence.pop(0)  # Maintain latest 3 values

                if self.x_sequence == [1, 0, 1]:
                    self.state_reg = 'C'
                    self.g_reg = 1
                    self.y_countdown = 2  # Start countdown for input y detection

            if self.state_reg == 'C':
                if self.y_countdown > 0:
                    if signal_vector['y'] == 1:
                        self.y_countdown = -1  # Maintain g = 1 indefinitely
                    else:
                        self.y_countdown -= 1

                if self.y_countdown == 0:
                    self.g_reg = 0  # Set g=0 if y=1 not detected in time

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_f = self.f_reg
            expected_g = self.g_reg
            observed_f = signal_vector['f']
            observed_g = signal_vector['g']

            correct_f = (expected_f == observed_f)
            correct_g = (expected_g == observed_g)

            if not (correct_f and correct_g):
                print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, g={expected_g}, observed: f={observed_f}, g={observed_g}")
            return correct_f and correct_g
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

