class GoldenDUT:
    def __init__(self):
        # Initialize internal state variables
        self.y_reg = 0b000
        self.z_reg = 0
        self.Y0_reg = 0

    def load(self, signal_vector):
        # Load inputs
        x = signal_vector['x']
        y = signal_vector['y']

        # Determine next state and output z based on current state y and input x
        if y == 0b000:
            if x == 0b0:
                self.y_reg = 0b000
                self.z_reg = 0b0
            elif x == 0b1:
                self.y_reg = 0b001
                self.z_reg = 0b0
        elif y == 0b001:
            if x == 0b0:
                self.y_reg = 0b001
                self.z_reg = 0b0
            elif x == 0b1:
                self.y_reg = 0b100
                self.z_reg = 0b0
        elif y == 0b010:
            if x == 0b0:
                self.y_reg = 0b010
                self.z_reg = 0b0
            elif x == 0b1:
                self.y_reg = 0b001
                self.z_reg = 0b0
        elif y == 0b011:
            if x == 0b0:
                self.y_reg = 0b001
                self.z_reg = 0b1
            elif x == 0b1:
                self.y_reg = 0b010
                self.z_reg = 0b1
        elif y == 0b100:
            if x == 0b0:
                self.y_reg = 0b011
                self.z_reg = 0b1
            elif x == 0b1:
                self.y_reg = 0b100
                self.z_reg = 0b1

        # Assign Y0 based on the LSB of y_reg
        self.Y0_reg = self.y_reg & 0b001

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        expected_Y0 = self.Y0_reg
        expected_z = self.z_reg
        observed_Y0 = signal_vector['Y0']
        observed_z = signal_vector['z']

        result_Y0 = (expected_Y0 == observed_Y0)
        result_z = (expected_z == observed_z)

        if not result_Y0 or not result_z:
            print(f"Scenario: {signal_vector['scenario']}, expected: Y0={expected_Y0}, z={expected_z}, observed: Y0={observed_Y0}, z={observed_z}")

        return result_Y0 and result_z

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

