class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        # Using -1 to indicate undefined for clarity in logic (since input values are 0 or 1)
        self.state_reg = 0  # Assuming initial state as 0
        self.q_reg = 0      # Initial output q is 0
        self.prev_state_reg = 0  # Track previous state for state transition

    def load(self, signal_vector):
        # Load input signals and update internal states
        self.a = signal_vector['a']
        self.b = signal_vector['b']

        # Determine the next state and output based on the inputs
        self.state_reg, self.q_reg = self.ideal_dut_rule(self.a, self.b, self.prev_state_reg)

        # Update the previous state register (only done on rising edge, implied by method call)
