            state = prev_state
            q = 1 if prev_state == 1 else 0
        elif a == 0 and b == 1:
            state = 0
            q = 1
        elif a == 1 and b == 1:
            state = prev_state
            q = 1 if prev_state == 1 else 0
        elif a == 1 and b == 0:
            state = 1
            q = 0
        else:
