class GoldenDUT:
    def __init__(self):
        # Initialize the internal registers with 'x', which will be replaced by 0 during the first proper signal load
        self.p_reg = 'x'
        self.q_reg = 'x'
        self.previous_clock = 0  # Use to track previous state of `check_en`
        self.initialized = False  # A flag to handle initial states more cautiously

    def load(self, signal_vector):
        # Load the input signal 'a' and process the signals
        # A rising edge is detected when previous_clock is 0 and current check_en is True
        if not self.previous_clock and signal_vector['check_en']:
            # Initialization on the first rising edge
            if not self.initialized:
                self.q_reg = 0
                self.initialized = True

            # Update the internal p_reg based on the input 'a'
            self.p_reg = signal_vector['a']

        # A falling edge is detected when previous_clock is 1 and current check_en is False
        if self.previous_clock and not signal_vector['check_en']:
            # Capture the p_reg value into q_reg
            self.q_reg = self.p_reg

        # Update the previous clock state
        self.previous_clock = signal_vector['check_en']

    def check(self, signal_vector):
        # Check against the expected outputs
        p_observed = signal_vector['p']
        q_observed = signal_vector['q']

        if self.p_reg != p_observed or self.q_reg != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: p={self.p_reg}, q={self.q_reg}, "
                  f"observed: p={p_observed}, q={q_observed}")
            return False
        return True

    # A new utility function if needed
    def debug_print(self, msg):
        # Custom debug function to trace internal states
        print(msg, f"p_reg: {self.p_reg}, q_reg: {self.q_reg}, previous_clock: {self.previous_clock}")

