class GoldenDUT:
    def __init__(self):
        self.q_reg = 0x4  # Initial value is set as 4 based on provided waveform behavior
        self.a_reg = 1  # Initialize with a default value to prevent undefined behavior
        self.cycle = [4, 5, 6, 0, 1]  # Cycle for q when a == 0

    def load(self, signal_vector):
        if 'a' in signal_vector:
            self.a_reg = signal_vector['a']

        # Update q_reg based on the updated input signals
        self.update_q()

    def update_q(self):
        if self.a_reg == 1:
            self.q_reg = 0b100  # Binary for 4
        else:
            if self.q_reg not in self.cycle:
                self.q_reg = self.cycle[0]
            index = self.cycle.index(self.q_reg)
            new_index = (index + 1) % len(self.cycle)
            self.q_reg = self.cycle[new_index]

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        if self.q_reg != q_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg}, observed q={q_observed}")
            return False
        return True
