import numpy as np

class GoldenDUT:
    def __init__(self):
        self.q_reg = 0  # Initial values set to 0, represents the grid as a 256-bit vector

    def load(self, signal_vector):
        if signal_vector['load']:
            self.q_reg = signal_vector['data']  # Load the initial grid state

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_q = self.expected_output(self.q_reg)
            if expected_q != signal_vector['q']:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={signal_vector['q']}")
                return False
        return True

    def expected_output(self, q_reg):
        initial_grid = self.vector_to_grid(q_reg)
        evolved_grid = self.game_of_life_rule(initial_grid)
        return self.grid_to_vector(evolved_grid)

    def count_neighbors(self, grid, row, col, size=16):
        """Corrects counting of alive neighbors wrapped in a toroidal manner."""
        count = 0
        for i in [-1, 0, 1]:
            for j in [-1, 0, 1]:
                if not (i == 0 and j == 0):
                    count += grid[(row + i) % size, (col + j) % size]
        return count

    def game_of_life_rule(self, grid):
        """Applies the Game of Life rules to evolve the grid once."""
        size = grid.shape[0]
        new_grid = np.zeros((size, size), dtype=int)

        for row in range(size):
            for col in range(size):
                num_neighbors = self.count_neighbors(grid, row, col, size)
                # Apply the Game of Life rules
                if num_neighbors < 2 or num_neighbors > 3:
                    new_grid[row, col] = 0
                elif num_neighbors == 3:
                    new_grid[row, col] = 1
                elif num_neighbors == 2:
                    new_grid[row, col] = grid[row, col]

        return new_grid

    def grid_to_vector(self, grid):
        """Converts a 2D grid to a 256-bit binary vector."""
        return int(''.join(''.join(str(cell) for cell in row) for row in grid), 2)

    def vector_to_grid(self, vector):
        """Converts a 256-bit binary vector to a 2D 16x16 grid."""
        binary_str = f"{vector:0256b}"
        return np.array([[int(binary_str[i * 16 + j]) for j in range(16)] for i in range(16)])
