def binary_to_bcd(value):
    """Convert a binary integer value to a two-digit BCD representation."""
    assert 0 <= value <= 99, "Value out of BCD range (00-99)."
    units = value % 10
    tens = value // 10
    return (tens << 4) | units

class GoldenDUT:
    def __init__(self):
        self.reset_clock()

    def reset_clock(self):
        self.hh_reg = binary_to_bcd(12)  # '12' in BCD
        self.mm_reg = binary_to_bcd(0)   # '00' in BCD
        self.ss_reg = binary_to_bcd(0)   # '00' in BCD
        self.pm_reg = 0  # AM

    def increment_seconds(self):
        # Increment seconds and handle minutes rollover
        ss_binary = ((self.ss_reg >> 4) * 10) + (self.ss_reg & 0x0F)
        ss_binary += 1
        if ss_binary == 60:
            self.ss_reg = binary_to_bcd(0)
            self.increment_minutes()
        else:
            self.ss_reg = binary_to_bcd(ss_binary)

    def increment_minutes(self):
        # Increment minutes and handle hours rollover
        mm_binary = ((self.mm_reg >> 4) * 10) + (self.mm_reg & 0x0F)
        mm_binary += 1
        if mm_binary == 60:
            self.mm_reg = binary_to_bcd(0)
            self.increment_hours()
        else:
            self.mm_reg = binary_to_bcd(mm_binary)

    def increment_hours(self):
        # Increment hours and handle 12-hour format and AM/PM toggle
        hh_binary = ((self.hh_reg >> 4) * 10) + (self.hh_reg & 0x0F)
        hh_binary += 1
        if hh_binary == 13:
            self.hh_reg = binary_to_bcd(1)
            self.pm_reg = 1 - self.pm_reg
        else:
            self.hh_reg = binary_to_bcd(hh_binary)

    def load(self, signal_vector):
        reset = signal_vector.get('reset')
        ena = signal_vector.get('ena')

        if reset:
            self.reset_clock()
        elif ena:
            self.increment_seconds()

    def check(self, signal_vector):
        if signal_vector['check_en']:
            hh_observed = signal_vector['hh']
            mm_observed = signal_vector['mm']
            ss_observed = signal_vector['ss']
            pm_observed = signal_vector['pm']

            correct = (self.hh_reg == hh_observed and
                       self.mm_reg == mm_observed and
                       self.ss_reg == ss_observed and
                       self.pm_reg == pm_observed)

            if not correct:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, "
                      f"observed: hh={hh_observed}, mm={mm_observed}, ss={ss_observed}, pm={pm_observed}")

            return correct
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
