class GoldenDUT:
    def __init__(self):
        # Properly initialize the internal state of the DUT to zeros
        self.q0_reg = 0
        self.q1_reg = 0
        self.q2_reg = 0

    def load(self, signal_vector):
        # Load inputs and update internal states
        x = signal_vector['x']

        # Calculate inputs to the D flip-flops with corrected logic
        d0 = x ^ self.q0_reg
        d1 = x & (~self.q1_reg & 1)  # Use and maintain the mask logic with complemented state
        d2 = x | (self.q2_reg ^ 1)   # Correct the logic here to ensure the OR operation behaves correctly

        # Update flip-flop outputs (Registers) with bit-width constraint
        self.q0_reg = d0 & 1
        self.q1_reg = d1 & 1
        self.q2_reg = d2 & 1

    def check(self, signal_vector):
        # Determine the expected output z
        expected_z = ~(self.q0_reg ^ self.q1_reg ^ self.q2_reg) & 1

        # Compare with the observed value from the DUT
        observed_z = signal_vector['z']

        if expected_z == observed_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed: z={observed_z}")
            return False

    def reset(self):
        # Resets the DUT register values
        self.q0_reg = 0
        self.q1_reg = 0
        self.q2_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

