import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal states of the Golden DUT with '0' or as needed
        self.x_reg = 0
        self.z_reg = 0
        self.state_reg = 'IDLE'  # Initial state can be IDLE

    def load(self, signal_vector):
        # Load input signals and update internal state
        self.x_reg = signal_vector['x']

        if signal_vector['areset']:
            self.state_reg = 'IDLE'
            self.z_reg = 0
        else:
            self.state_reg = 'ACTIVE'
            self.z_reg = self.compute_z(self.x_reg)

    def check(self, signal_vector):
        # Check expected versus observed output
        if 'z' in signal_vector and signal_vector['check_en']:
            expected_z = self.z_reg
            observed_z = signal_vector['z']
            if observed_z != expected_z:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
                return False
        return True

    def compute_z(self, x):
        # Compute output 'z' based on current input and state
        if self.state_reg == 'ACTIVE':
            # Assuming single input bit processing
            complement = 1 - x  # 1's complement
            return (complement + 1) & 1  # 2's Complement limited to 1 bit
        return 0

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

