        # Update the registers based on the input signal vector
        self.x_reg = signal_vector['x']
        self.areset_reg = signal_vector['areset']

        # Handle reset
        if self.areset_reg:
            self.input_bits = []
            self.output_bits = []
            self.z_reg = 0
        else:
            # Add the new input and compute the 2's complement if not reset
            self.input_bits.append(self.x_reg)
            self.output_bits = self.twos_complement(self.input_bits)
            self.z_reg = self.output_bits[-1] if self.output_bits else 0

    def check(self, signal_vector):
        expected_z = self.z_reg
        observed_z = signal_vector['z']
        if expected_z != observed_z:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False
        return True

    def twos_complement(self, input_bits):
        n = len(input_bits)
        if n == 0:
            return []

        # Start with one's complement
        ones_complement = [1 - bit for bit in input_bits]

        # Add 1 to the one's complement to get the two's complement
        complement = ones_complement[:]
        carry = 1
        for i in range(n):
            sum_bit = complement[i] ^ carry  # XOR for addition
            carry = complement[i] & carry  # AND for carry generation
            complement[i] = sum_bit
            if carry == 0:
                # No carry to propagate further
                break
            carry = 1 if carry else 0  # Continue with carry if necessary

        return complement
