class GoldenDUT:
    def __init__(self):
        # Initialize the internal states with default values
        self.x_reg = 0  # Input x register, starting with default 0
        self.z_reg = 0  # Output z register, starting with default 0
        self.state_reg = 0  # State register for Moore state machine

    def load(self, signal_vector):
        # Load the input signals and adjust internal states accordingly
        if signal_vector['areset']:
            self.reset()
        else:
            self.x_reg = signal_vector['x']
            self.update_state()

    def reset(self):
        # Reset the internal states
        self.x_reg = 0
        self.z_reg = 0
        self.state_reg = 0

    def update_state(self):
        # Update the state of the Moore machine based on x_reg
        # State transitions and behavior for 2's complement operation
        if self.state_reg == 0:
            if self.x_reg == 1:
                self.state_reg = 1  # Move to state 1 for starting complement
            else:
                self.state_reg = 0  # Stay in state 0
        elif self.state_reg == 1:
            if self.x_reg == 0:
                self.state_reg = 1  # Stay in the complement state
            else:
                self.state_reg = 0  # Return to the initial non-complement state

    def calculate_2s_complement(self, input_bit):
        # Logic to calculate the single bit 2's complement based on current state
        # This function now consistently calculates 2's complement
        if self.state_reg == 1:
            return 1 - input_bit
        else:
            return input_bit

    def check(self, signal_vector):
        # Determine the expected output and compare with DUT output
        if signal_vector['check_en']:
            expected_z = self.calculate_2s_complement(self.x_reg)
            observed_z = signal_vector['z']
            if expected_z != observed_z:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

