class GoldenDUT:
    def __init__(self):
        self.x_reg = 'x'
        self.z_reg = 'x'
        self.state_reg = 'INIT'
        self.input_bits = []

    def load(self, signal_vector):
        """Load the new input and update the state."""
        if signal_vector['areset']:
            self.reset()
            return

        # Update input register with new signal value
        self.x_reg = signal_vector['x']

        # Only collect input bits if not in reset
        self.input_bits.append(self.x_reg)

    def reset(self):
        """Reset the internal state."""
        self.x_reg = 'x'
        self.z_reg = 'x'
        self.state_reg = 'INIT'
        self.input_bits = []

    def compute_twos_complement(self):
        """Compute the 2's complement of the input bits."""
        # Convert the list of input bits to a binary string
        input_bits_str = ''.join(str(bit) for bit in self.input_bits)

        # Use the given rule to compute 2's complement
        return self.compute_twos_complement_rule(input_bits_str)

    def compute_twos_complement_rule(self, input_bits):
        """Calculate two's complement based on input bits."""
        if not input_bits:
            return 'x'  # Return 'x' if no valid input

        reversed_bits = input_bits[::-1]  # Start with LSB
        num = int(reversed_bits, 2)
        bit_length = len(input_bits)
        max_val = 2 ** bit_length
        twos_complement = (~num + 1) & (max_val - 1)
        twos_complement_bits = format(twos_complement, '0{}b'.format(bit_length))

        # Reverse the result to maintain the original bit order
        return twos_complement_bits[::-1]

    def check(self, signal_vector):
        if signal_vector['check_en']:
            if self.input_bits:  # Ensure comparisons have valid input
                self.z_reg = self.compute_twos_complement()

            z_observed = signal_vector['z']

            # Check if the computed and observed results match
            if not self.input_bits:
                return z_observed == 'x'  # No input -> expected 'x'

            # Fetch last bit from computed two's complement as expected zero, consider LSB
            z_expected = int(self.z_reg[-1])

            if z_expected == z_observed:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={z_expected}, observed z={z_observed}")
                return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
