    def __init__(self):
        # Initialize internal state register to state A (0b01)
        self.state_reg = 0b01
        self.z_reg = 0  # Output register

    def load(self, signal_vector):
        areset = signal_vector['areset']
        x = signal_vector['x']

        if areset == 1:
            # Reset to initial state A
            self.state_reg = 0b01
            self.z_reg = 0
        else:
            # Calculate the expected next state and output based on current input
            self.state_reg, self.z_reg = self.calculate_next_state_and_output(self.state_reg, x)

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        if self.z_reg != z_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
        return True

    def calculate_next_state_and_output(self, state, x):
        # Mealy machine logic for next state and output determination
        z_output = 0
        next_state = state  # default to current state, unless changed

        # State A
        if state == 0b01:
            if x == 0:
                next_state = 0b01  # Stay in A
                z_output = 0
            elif x == 1:
                next_state = 0b10  # Transition to B
                z_output = 1

        # State B
        elif state == 0b10:
            if x == 0:
                next_state = 0b10  # Stay in B
                z_output = 1
            elif x == 1:
                next_state = 0b10  # Stay in B
                z_output = 0

        return next_state, z_output
