class GoldenDUT:
    def __init__(self):
        self.current_state_reg = 0  # 0 for OFF, 1 for ON
        self.out_reg = 0

    def load(self, signal_vector):
        j = signal_vector['j']
        k = signal_vector['k']
        areset = signal_vector['areset']

        # Handle asynchronous reset (areset active-high)
        if areset:
            self.current_state_reg = 0  # OFF state
        else:
            if self.current_state_reg == 0:  # OFF state
                if j == 1:
                    self.current_state_reg = 1  # Transition to ON state
            elif self.current_state_reg == 1:  # ON state
                if k == 1:
                    self.current_state_reg = 0  # Transition to OFF state

        # Update the output based on the current state
        self.out_reg = 0 if self.current_state_reg == 0 else 1

    def check(self, signal_vector):
        observed_out = signal_vector['out']

        if observed_out != self.out_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: out={self.out_reg}, observed out={observed_out}")
            return False
        return True

    def simulate_clock(self, signal_vector):
        # Simulate a clock cycle; useful for repeated state checks or toggles
        self.load(signal_vector)

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

