class GoldenDUT:
    def __init__(self):
        # Define states using one-hot encoding
        self.S0 = 0b0000000001
        self.S1 = 0b0000000010
        self.S2 = 0b0000000100
        self.S3 = 0b0000001000
        self.S4 = 0b0000010000
        self.S5 = 0b0000100000
        self.S6 = 0b0001000000
        self.S7 = 0b0010000000
        self.S8 = 0b0100000000
        self.S9 = 0b1000000000

    def load(self, signal_vector):
        state = signal_vector['state']
        in_signal = signal_vector['in']

        # Initialize default outputs
        out1, out2 = 0, 0
        next_state = self.S0  # Default next_state initialization

        # State transitions and outputs based on current state and input
        if state == self.S0:
            next_state = self.S0 if in_signal == 0 else self.S1
        elif state == self.S1:
            next_state = self.S0 if in_signal == 0 else self.S2
        elif state == self.S2:
            next_state = self.S0 if in_signal == 0 else self.S3
        elif state == self.S3:
            next_state = self.S0 if in_signal == 0 else self.S4
        elif state == self.S4:
            next_state = self.S0 if in_signal == 0 else self.S5
        elif state == self.S5:
            next_state = self.S8 if in_signal == 0 else self.S6
        elif state == self.S6:
            next_state = self.S9 if in_signal == 0 else self.S7
        elif state == self.S7:
            next_state = self.S0 if in_signal == 0 else self.S7
            out2 = 1
        elif state == self.S8:
            next_state = self.S0 if in_signal == 0 else self.S1
            out1 = 1
        elif state == self.S9:
            next_state = self.S0 if in_signal == 0 else self.S1
            out1, out2 = 1, 1

        return {'next_state': next_state, 'out1': out1, 'out2': out2}

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        return (expected_output['next_state'] == signal_vector['next_state'] and
                expected_output['out1'] == signal_vector['out1'] and
                expected_output['out2'] == signal_vector['out2'])

