class GoldenDUT:
    def __init__(self):
        self.IDLE = 0
        self.BYTE_1_RECEIVED = 1
        self.BYTE_2_RECEIVED = 2
        self.BYTE_3_RECEIVED = 3

        self.fsm_state_reg = self.IDLE
        self.done_reg = False
        self.done_signal_latched = False

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.fsm_state_reg = self.IDLE
            self.done_reg = False
            self.done_signal_latched = False
        else:
            if not self.done_signal_latched:
                if self.fsm_state_reg == self.IDLE:
                    if (in_signal & 0b00001000) != 0:
                        self.fsm_state_reg = self.BYTE_1_RECEIVED

                elif self.fsm_state_reg == self.BYTE_1_RECEIVED:
                    self.fsm_state_reg = self.BYTE_2_RECEIVED

                elif self.fsm_state_reg == self.BYTE_2_RECEIVED:
                    self.fsm_state_reg = self.BYTE_3_RECEIVED

                elif self.fsm_state_reg == self.BYTE_3_RECEIVED:
                    # Signal done and latch it for one cycle
                    self.done_reg = True
                    self.done_signal_latched = True
            else:
                # Keep the done signal high for one additional cycle before resetting
                self.done_reg = False
                self.done_signal_latched = False
                self.fsm_state_reg = self.IDLE

    def check(self, signal_vector):
        expected_done = self.done_reg
        observed_done = signal_vector['done']

        if expected_done != observed_done:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={observed_done}")
            return False
        return True

    def reset_fsm(self):
        """Manually reset FSM; useful for additional requirements or functions."""
        self.fsm_state_reg = self.IDLE
        self.done_reg = False
        self.done_signal_latched = False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

