class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.byte_count_reg = 0
        self.done_reg = False

    def load(self, signal_vector):
        in_data = signal_vector['in']
        reset = signal_vector['reset']

        if reset == 1:
            # Reset logic to clear all internal states
            self.state_reg = 'IDLE'
            self.byte_count_reg = 0
            self.done_reg = False
        else:
            in_3 = (in_data >> 3) & 0b1
            self._next_state(in_3)

    def _next_state(self, in_3):
        if self.state_reg == 'IDLE':
            if in_3 == 1:
                self.state_reg = 'BYTE_1'
                self.byte_count_reg = 1
        elif self.state_reg == 'BYTE_1':
            if in_3 == 1:
                # Reset and restart when encountering another start byte in the middle
                self.state_reg = 'BYTE_1'
                self.byte_count_reg = 1
            else:
                self.state_reg = 'BYTE_2'
                self.byte_count_reg += 1
        elif self.state_reg == 'BYTE_2':
            self.byte_count_reg += 1
            if self.byte_count_reg == 3:
                self.done_reg = True
                self.state_reg = 'IDLE'

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            if done_observed != self.done_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed: done={done_observed}")
                return False
            self.done_reg = False  # Reset done after a check
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
