class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # State: Idle = 0, Byte1 = 1, Byte2 = 2, Byte3 = 3
        self.byte1_reg = 0
        self.byte2_reg = 0
        self.byte3_reg = 0
        self.done_reg = 0
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        reset = signal_vector['reset']
        byte_input = signal_vector['in']

        # Handle reset signal
        if reset == 1:  
            self.state_reg = 0
            self.byte1_reg = 0
            self.byte2_reg = 0
            self.byte3_reg = 0
            self.done_reg = 0
            self.out_bytes_reg = 0
            return

        if self.state_reg == 0:
            if byte_input & 0b00001000:  # Check if in[3] is 1
                self.byte1_reg = byte_input
                self.state_reg = 1
        elif self.state_reg == 1:
            self.byte2_reg = byte_input
            self.state_reg = 2
        elif self.state_reg == 2:
            self.byte3_reg = byte_input
            self.state_reg = 3
        elif self.state_reg == 3:
            # Prepare output after processing 3rd byte
            self.out_bytes_reg = ((self.byte1_reg << 16) | 
                                  (self.byte2_reg << 8) | 
                                  self.byte3_reg)
            self.done_reg = 1
            # Check if the current input can immediately start a new message
            if byte_input & 0b00001000:
                self.byte1_reg = byte_input
                self.state_reg = 1
            else:
                # Reset to idle if no new message can start immediately
                self.state_reg = 0
                self.done_reg = 0
        else:
            self.done_reg = 0  # Default case to handle any unexpected conditions

        # Ensure done is reset when not in state 3
        if self.state_reg != 3:
            self.done_reg = 0

    def check(self, signal_vector):
        check_en = signal_vector['check_en']
        expected_done = self.done_reg
        expected_out_bytes = self.out_bytes_reg

        observed_done = signal_vector['done']
        observed_out_bytes = signal_vector['out_bytes']

        if check_en:
            if (expected_done != observed_done) or (expected_out_bytes != observed_out_bytes):
                print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, out_bytes={expected_out_bytes}"
                      f", observed: done={observed_done}, out_bytes={observed_out_bytes}")
                return False
            else:
                return True
        return True
