from collections import deque

class GoldenDUT:
    IDLE, START, DATA, STOP, WAIT_STOP = range(5)

    def __init__(self):
        self.state_reg = self.IDLE
        self.bit_counter_reg = 0
        self.data_bits_reg = deque()
        self.out_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.__init__()  # Reset to initial state
            return

        input_bit = signal_vector['in']

        if self.state_reg == self.IDLE:
            if input_bit == 0:  # Start bit detected
                self.state_reg = self.START
                self.bit_counter_reg = 0
                self.data_bits_reg.clear()
                self.done_reg = 0

        elif self.state_reg == self.START:
            # Collect data bits
            self.data_bits_reg.append(input_bit)
            self.bit_counter_reg += 1

            if self.bit_counter_reg == 8:
                self.state_reg = self.STOP  # Move to stop state after 8 data bits

        elif self.state_reg == self.STOP:
            if input_bit == 1:  # Correct stop bit
                # Convert deque of bits to byte using LSB-first order
                self.out_byte_reg = sum([b << i for i, b in enumerate(self.data_bits_reg)])
                self.done_reg = 1
                self.state_reg = self.IDLE  # Correct sequence, back to idle
            else:
                # Incorrect stop bit, go to wait stop directly
                self.state_reg = self.WAIT_STOP

        elif self.state_reg == self.WAIT_STOP:
            if input_bit == 1:  # Wait for correct stop bit
                self.state_reg = self.IDLE
                # Reset if a stop bit encountered after WAIT_STOP
                self.done_reg = 0
                self.data_bits_reg.clear()
                self.bit_counter_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            out_byte_observed = signal_vector['out_byte']
            done_observed = signal_vector['done']

            if self.out_byte_reg != out_byte_observed or self.done_reg != done_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.out_byte_reg}, done={self.done_reg}, "
                      f"observed out_byte={out_byte_observed}, done={done_observed}")
                return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

