class GoldenDUT:
    def __init__(self):
        # Internal state registers for the state machine
        self.state_reg = 'walk_left'
        self.walk_left_reg = 1
        self.walk_right_reg = 0

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']

        # Handle asynchronous reset
        if areset == 1:
            self.state_reg = 'walk_left'
            self.walk_left_reg = 1
            self.walk_right_reg = 0
        else:
            # State transitions based on current state and bump signals
            if self.state_reg == 'walk_left':
                if bump_left == 1 or (bump_left == 1 and bump_right == 1):
                    self.state_reg = 'walk_right'
                    self.walk_left_reg = 0
                    self.walk_right_reg = 1
            elif self.state_reg == 'walk_right':
                if bump_right == 1 or (bump_left == 1 and bump_right == 1):
                    self.state_reg = 'walk_left'
                    self.walk_left_reg = 1
                    self.walk_right_reg = 0

    def check(self, signal_vector):
        # Extract the scenario and DUT's observed outputs
        scenario = signal_vector['scenario']
        observed_walk_left = signal_vector['walk_left']
        observed_walk_right = signal_vector['walk_right']

        # Compare expected and observed outputs
        if self.walk_left_reg == observed_walk_left and self.walk_right_reg == observed_walk_right:
            return True
        else:
            print(f"Scenario: {scenario}, expected: walk_left={self.walk_left_reg}, walk_right={self.walk_right_reg}, "
                  f"observed: walk_left={observed_walk_left}, walk_right={observed_walk_right}")
            return False

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

