class GoldenDUT:
    WALK_LEFT = 0b0001
    WALK_RIGHT = 0b0010
    FALLING = 0b0100
    DIGGING = 0b1000

    def __init__(self):
        self.state_reg = self.WALK_LEFT
        self.previous_state_reg = self.WALK_LEFT

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        if areset:
            self.state_reg = self.WALK_LEFT
        else:
            if not ground:
                self.state_reg = self.FALLING
            elif self.state_reg == self.DIGGING and not ground:
                self.state_reg = self.FALLING
            elif self.state_reg == self.FALLING and ground:
                self.state_reg = self.previous_state_reg
            elif dig and ground:
                self.state_reg = self.DIGGING
            elif self.state_reg == self.WALK_LEFT:
                if bump_left:
                    self.state_reg = self.WALK_RIGHT
            elif self.state_reg == self.WALK_RIGHT:
                if bump_right:
                    self.state_reg = self.WALK_LEFT

        if self.state_reg != self.FALLING: 
            self.previous_state_reg = self.state_reg

    def check(self, signal_vector):
        walk_left_observed = signal_vector['walk_left']
        walk_right_observed = signal_vector['walk_right']
        aaah_observed = signal_vector['aaah']
        digging_observed = signal_vector['digging']

        walk_left_exp = 0
        walk_right_exp = 0
        aaah_exp = 0
        digging_exp = 0

        if self.state_reg == self.WALK_LEFT:
            walk_left_exp = 1
        elif self.state_reg == self.WALK_RIGHT:
            walk_right_exp = 1
        elif self.state_reg == self.FALLING:
            aaah_exp = 1
        elif self.state_reg == self.DIGGING:
            digging_exp = 1

        if (walk_left_observed != walk_left_exp or
            walk_right_observed != walk_right_exp or
            aaah_observed != aaah_exp or
            digging_observed != digging_exp):
            print(f"Scenario: {signal_vector['scenario']}, expected: walk_left={walk_left_exp}, walk_right={walk_right_exp}, aaah={aaah_exp}, digging={digging_exp}, "
                  f"observed: walk_left={walk_left_observed}, walk_right={walk_right_observed}, aaah={aaah_observed}, digging={digging_observed}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

