class GoldenDUT:
    def __init__(self):
        self.state_reg = 'walk_left'
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0
        self.fall_cycles_reg = 0
        self.initial_direction_reg = 'walk_left'

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        if areset:
            self.reset()
        else:
            self.update_state(bump_left, bump_right, ground, dig)

    def reset(self):
        self.state_reg = 'walk_left'
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0
        self.fall_cycles_reg = 0
        self.initial_direction_reg = 'walk_left'

    def update_state(self, bump_left, bump_right, ground, dig):
        if self.state_reg == 'walk_left':
            self.handle_walk_left(bump_left, bump_right, ground, dig)
        elif self.state_reg == 'walk_right':
            self.handle_walk_right(bump_left, bump_right, ground, dig)
        elif self.state_reg == 'fall':
            self.handle_fall(ground)
        elif self.state_reg == 'dig':
            self.handle_dig(ground)

    def handle_walk_left(self, bump_left, bump_right, ground, dig):
        if not ground:
            self.state_reg = 'fall'
            self.aaah_reg = 1
            self.fall_cycles_reg = 1
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.initial_direction_reg = 'walk_left'
        elif dig and ground:
            self.state_reg = 'dig'
            self.digging_reg = 1
            self.walk_left_reg = 0
        elif bump_left or bump_right:
            self.state_reg = 'walk_right'
            self.walk_left_reg = 0
            self.walk_right_reg = 1

    def handle_walk_right(self, bump_left, bump_right, ground, dig):
        if not ground:
            self.state_reg = 'fall'
            self.aaah_reg = 1
            self.fall_cycles_reg = 1
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.initial_direction_reg = 'walk_right'
        elif dig and ground:
            self.state_reg = 'dig'
            self.digging_reg = 1
            self.walk_right_reg = 0
        elif bump_left or bump_right:
            self.state_reg = 'walk_left'
            self.walk_left_reg = 1
            self.walk_right_reg = 0

    def handle_fall(self, ground):
        if ground:
            if self.fall_cycles_reg > 20:
                self.state_reg = 'splatter'
                self.walk_left_reg = 0
                self.walk_right_reg = 0
                self.aaah_reg = 0
                self.digging_reg = 0
            else:
                self.state_reg = self.initial_direction_reg
                if self.initial_direction_reg == 'walk_left':
                    self.walk_left_reg = 1
                    self.walk_right_reg = 0
                else:
                    self.walk_left_reg = 0
                    self.walk_right_reg = 1
            self.aaah_reg = 0
            self.fall_cycles_reg = 0
        else:
            self.aaah_reg = 1
            self.fall_cycles_reg += 1

    def handle_dig(self, ground):
        if not ground:
            self.state_reg = 'fall'
            self.aaah_reg = 1
            self.digging_reg = 0
            self.fall_cycles_reg = 1
        else:
            self.digging_reg = 1

    def check(self, signal_vector):
        expected_walk_left = self.walk_left_reg
        expected_walk_right = self.walk_right_reg
        expected_aaah = self.aaah_reg
        expected_digging = self.digging_reg

        observed_walk_left = signal_vector['walk_left']
        observed_walk_right = signal_vector['walk_right']
        observed_aaah = signal_vector['aaah']
        observed_digging = signal_vector['digging']

        is_correct = (expected_walk_left == observed_walk_left and
                      expected_walk_right == observed_walk_right and
                      expected_aaah == observed_aaah and
                      expected_digging == observed_digging)

        if not is_correct:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: walk_left={expected_walk_left}, walk_right={expected_walk_right}, aaah={expected_aaah}, digging={expected_digging}, "
                  f"observed: walk_left={observed_walk_left}, walk_right={observed_walk_right}, aaah={observed_aaah}, digging={observed_digging}")

        return is_correct
def check_dut(vectors_in):
