class GoldenDUT:
    def __init__(self):
        # State definitions using one-hot encoding
        self.state_A = 0b000001
        self.state_B = 0b000010
        self.state_C = 0b000100
        self.state_D = 0b001000
        self.state_E = 0b010000
        self.state_F = 0b100000

    def get_next_state(self, y, w):
        # Determine the next state based on the current state and input 'w'
        if y == self.state_A:
            return self.state_B if w == 0 else self.state_A
        elif y == self.state_B:
            return self.state_C if w == 0 else self.state_D
        elif y == self.state_C:
            return self.state_E if w == 0 else self.state_D
        elif y == self.state_D:
            return self.state_F if w == 0 else self.state_A
        elif y == self.state_E:
            return self.state_E if w == 0 else self.state_D
        elif y == self.state_F:
            return self.state_C if w == 0 else self.state_D
        else:
            return self.state_A # Default case: robustness

    def load(self, signal_vector):
        # Load input signals from signal vector
        y = signal_vector['y']
        w = signal_vector['w']

        # Determine the next state
        next_state = self.get_next_state(y, w)

        # Extract Y2 and Y4 from the next state encoding
        Y2 = (next_state & self.state_B) >> 1
        Y4 = (next_state & self.state_D) >> 3

        # Return expected output values
        return Y2, Y4

    def check(self, signal_vector):
        # Load expected output values
        expected_Y2, expected_Y4 = self.load(signal_vector)

        # Compare with DUT's outputs
        actual_Y2 = signal_vector['Y2']
        actual_Y4 = signal_vector['Y4']

        # Return True if outputs match, otherwise False
