class GoldenDUT:
    def __init__(self):
        # Define state constants using one-hot encoding
        self.S = 0b0000000001
        self.S1 = 0b0000000010
        self.S11 = 0b0000000100
        self.S110 = 0b0000001000
        self.B0 = 0b0000010000
        self.B1 = 0b0000100000
        self.B2 = 0b0001000000
        self.B3 = 0b0010000000
        self.Count = 0b0100000000
        self.Wait = 0b1000000000

        # Initial state
        self.current_state = self.S

    def load(self, signal_vector):
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']

        # Initialize expected outputs to zero
        B3_next = 0
        S_next = 0
        S1_next = 0
        Count_next = 0
        Wait_next = 0
        done = 0
        counting = 0
        shift_ena = 0

        # State transitions and output logic based on current state and inputs
        if self.current_state == self.S:
            if d == 0:
                S_next = self.S
            elif d == 1:
                S1_next = self.S1
        elif self.current_state == self.S1:
            if d == 0:
                S_next = self.S
            elif d == 1:
                S1_next = self.S11
        elif self.current_state == self.S11:
            if d == 0:
                S1_next = self.S110  # Corrected from S_next to S1_next
            elif d == 1:
                S1_next = self.S11
        elif self.current_state == self.S110:
            if d == 0:
                S_next = self.S
            elif d == 1:
                B3_next = self.B0
        elif self.current_state == self.B0:
            shift_ena = 1
            B3_next = self.B1
        elif self.current_state == self.B1:
            shift_ena = 1
            B3_next = self.B2
        elif self.current_state == self.B2:
            shift_ena = 1
            B3_next = self.B3
        elif self.current_state == self.B3:
            shift_ena = 1
            Count_next = self.Count
        elif self.current_state == self.Count:
            counting = 1
            if not done_counting:
                Count_next = self.Count
            else:
                Wait_next = self.Wait
        elif self.current_state == self.Wait:
            done = 1
            if ack == 0:
                Wait_next = self.Wait
            elif ack == 1:
                S_next = self.S

        expected_outputs = {
            "B3_next": B3_next,
            "S_next": S_next,
            "S1_next": S1_next,
            "Count_next": Count_next,
            "Wait_next": Wait_next,
            "done": done,
            "counting": counting,
            "shift_ena": shift_ena
        }

        # Update current state based on transitions
        self._update_state(S_next, S1_next, B3_next, Count_next, Wait_next)

        return expected_outputs

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        for key in ['B3_next', 'S_next', 'S1_next', 'Count_next', 'Wait_next', 'done', 'counting', 'shift_ena']:
            if expected_outputs[key] != signal_vector[key]:
                return False
        return True

    def _update_state(self, S_next, S1_next, B3_next, Count_next, Wait_next):
        # Update the current state based on active next state signals
        if S_next != 0:
            self.current_state = S_next
        elif S1_next != 0:
            self.current_state = S1_next
        elif B3_next != 0:
            self.current_state = B3_next
        elif Count_next != 0:
            self.current_state = Count_next
        elif Wait_next != 0:
            self.current_state = Wait_next
