class GoldenDUT:
    def __init__(self):
        # Define one-hot state encoding
        self.S    = 0b0000000001
        self.S1   = 0b0000000010
        self.S11  = 0b0000000100
        self.S110 = 0b0000001000
        self.B0   = 0b0000010000
        self.B1   = 0b0000100000
        self.B2   = 0b0001000000
        self.B3   = 0b0010000000
        self.Count= 0b0100000000
        self.Wait = 0b1000000000

    def load(self, signal_vector):
        # Extract inputs from signal_vector
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']
        state = signal_vector['state']

        # Initialize outputs
        B3_next = 0
        S_next = 0
        S1_next = 0
        S11_next = 0
        S110_next = 0
        B0_next = 0
        B1_next = 0
        B2_next = 0
        Count_next = 0
        Wait_next = 0
        done = 0
        counting = 0
        shift_ena = 0

        # State transitions and output logic
        if state == self.S:
            if d == 1:
                S1_next = 1
            else:
                S_next = 1
        elif state == self.S1:
            if d == 1:
                S11_next = 1
            else:
                S_next = 1
        elif state == self.S11:
            if d == 1:
                S11_next = 1
            else:
                S110_next = 1
        elif state == self.S110:
            if d == 1:
                B0_next = 1
            else:
                S_next = 1
        elif state == self.B0:
            B1_next = 1
            shift_ena = 1
        elif state == self.B1:
            B2_next = 1
            shift_ena = 1
        elif state == self.B2:
            B3_next = 1
            shift_ena = 1
        elif state == self.B3:
            Count_next = 1
            shift_ena = 1
        elif state == self.Count:
            counting = 1
            if done_counting == 0:
                Count_next = 1
            else:
                Wait_next = 1
        elif state == self.Wait:
            done = 1
            if ack == 0:
                Wait_next = 1
            else:
                S_next = 1

        return {
            'B3_next': B3_next,
            'S_next': S_next,
            'S1_next': S1_next,
            'Count_next': Count_next,
            'Wait_next': Wait_next,
            'done': done,
            'counting': counting,
            'shift_ena': shift_ena
        }

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        actual_output = {
            'B3_next': signal_vector['B3_next'],
            'S_next': signal_vector['S_next'],
            'S1_next': signal_vector['S1_next'],
            'Count_next': signal_vector['Count_next'],
            'Wait_next': signal_vector['Wait_next'],
            'done': signal_vector['done'],
            'counting': signal_vector['counting'],
            'shift_ena': signal_vector['shift_ena']
        }
        return expected_output == actual_output

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

