        # Initializing the internal state and counter
        self.current_state_reg = 0b0000
        self.counter_reg = 0
        self.shift_ena_reg = 0

    def load(self, signal_vector):
        reset = signal_vector.get('reset', 0)

        if reset:
            # On reset, set the FSM to enabled state for 4 cycles
            self.current_state_reg = 0b0001
            self.counter_reg = 0
            self.shift_ena_reg = 1
        else:
            if self.current_state_reg == 0b0001:
                self.shift_ena_reg = 1
                self.counter_reg += 1
                if self.counter_reg >= 4:
                    self.shift_ena_reg = 0
                    self.current_state_reg = 0b0000
            else:
                self.shift_ena_reg = 0

    def check(self, signal_vector):
        if not signal_vector['check_en']:
            return True

        expected_shift_ena = self.shift_ena_reg
        observed_shift_ena = signal_vector.get('shift_ena', 0)

        if expected_shift_ena != observed_shift_ena:
            print(f"Scenario: {signal_vector['scenario']}, expected: shift_ena={expected_shift_ena}, observed shift_ena={observed_shift_ena}")
