import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the Golden DUT
        self.q_reg = np.zeros(512, dtype=int)  # Initial state of cells, assuming 'x' is 0

    def load(self, signal_vector):
        # Load the DUT input signals into the internal state
        if signal_vector['load']:
            data = signal_vector['data']
            # Extract each bit from the data and load it into q_reg
            self.q_reg = np.array([int(bit) for bit in format(data, '0512b')], dtype=int)
        else:
            # Update cell states based on Rule 110 if not loading new data
            self.q_reg = self.update_cells(self.q_reg)

    def update_cells(self, current_state):
        # Update 512-cell system using Rule 110
        next_state = np.zeros_like(current_state)
        for i in range(512):
            # Ensure boundary conditions are strictly maintained
            left = current_state[i - 1] if i > 0 else 0  # Boundary condition
