import numpy as np

class GoldenDUT:
    def __init__(self):
        self.q_reg = np.zeros(512, dtype=int)  # Initialize with zeros

    def load(self, signal_vector):
        if signal_vector['load']:
            # Load the input data into q_reg
            data = signal_vector['data']
            for i in range(512):
                bit = (data >> i) & 0x1
                self.q_reg[i] = bit
        else:
            # Compute next state based on Rule 110
            self.q_reg = self.next_state(self.q_reg)

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        q_observed_list = [(q_observed >> i) & 0x1 for i in range(512)]

        if np.array_equal(self.q_reg, q_observed_list):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={self.q_reg}, observed q={q_observed_list}")
            return False

    def next_state(self, cells):
        extended_cells = np.zeros(len(cells) + 2, dtype=int)
        extended_cells[1:-1] = cells
        new_state = np.zeros_like(cells)

        for i in range(len(cells)):
            left = extended_cells[i]
            center = extended_cells[i + 1]
            right = extended_cells[i + 2]
            new_state[i] = self.rule_110_next_state(left, center, right)

        return new_state

    @staticmethod
    def rule_110_next_state(left, center, right):
        # Determine the next state according to Rule 110
        if (left, center, right) == (1, 1, 1):
            return 0
        elif (left, center, right) == (1, 1, 0):
            return 1
        elif (left, center, right) == (1, 0, 1):
            return 1
        elif (left, center, right) == (1, 0, 0):
            return 0
        elif (left, center, right) == (0, 1, 1):
            return 1
        elif (left, center, right) == (0, 1, 0):
            return 1
        elif (left, center, right) == (0, 0, 1):
            return 1
        elif (left, center, right) == (0, 0, 0):
            return 0

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

