import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the GoldenDUT
        self.q_reg = np.zeros(512, dtype=int)

    def load(self, signal_vector):
        # Load the input signals and update internal state as needed
        if signal_vector['load']:
            data = signal_vector['data']
            for i in range(512):
                self.q_reg[i] = (data >> i) & 1

    def check(self, signal_vector):
        # Check the output values against the expected values
        if not signal_vector['check_en']:
            return True

        expected_q = self.apply_rule_110(self.q_reg)

        q_observed = signal_vector['q']
        for i in range(512):
            if expected_q[i] != ((q_observed >> i) & 1):
                print(f"Scenario: {signal_vector['scenario']}, expected: q[{i}]={expected_q[i]}, observed q[{i}]={(q_observed >> i) & 1}")
                return False

        return True

    def apply_rule_110(self, data):
        # Apply Rule 110 to the data for one time step
        padded_data = np.pad(data, (1, 1), mode='constant', constant_values=(0, 0))
        next_data = np.zeros_like(data)

        for i in range(len(data)):
            left = padded_data[i]
            center = padded_data[i + 1]
            right = padded_data[i + 2]
            next_data[i] = self.rule_110_transition(left, center, right)

        return next_data

    @staticmethod
    def rule_110_transition(left, center, right):
        # Determine the next state based on Rule 110 transitions
        if (left, center, right) == (1, 1, 1):
            return 0
        elif (left, center, right) == (1, 1, 0):
            return 1
        elif (left, center, right) == (1, 0, 1):
            return 1
        elif (left, center, right) == (1, 0, 0):
            return 0
        elif (left, center, right) == (0, 1, 1):
            return 1
        elif (left, center, right) == (0, 1, 0):
            return 1
        elif (left, center, right) == (0, 0, 1):
            return 1
        elif (left, center, right) == (0, 0, 0):
            return 0
        else:
            raise ValueError("Inputs must be binary (0 or 1).")
