        # Initialize the internal state of the Golden DUT
        self.q_reg = 0  # Register to hold the current state of the shift register

    def load(self, signal_vector):
        # Load input signals and update internal state
        if signal_vector['load']:
            self.q_reg = signal_vector['data']  # Load data if load signal is high
        elif signal_vector['ena']:
            self.q_reg = self.apply_shift(self.q_reg, signal_vector['amount'])

    def check(self, signal_vector):
        # Check against expected outputs and return boolean result
        expected_q = self.q_reg
        observed_q = signal_vector['q']

        if expected_q != observed_q:
            print(f"Scenario: {signal_vector['scenario']}, expected q: {expected_q}, observed q: {observed_q}")
            return False
        return True

    def apply_shift(self, data, amount):
        # Apply the shift operation based on the amount
        bit_count = 64

        if amount == 0b00:  # Shift left by 1 bit
            return self.arithmetic_shift_left(data, shift_amount=1)
        elif amount == 0b01:  # Shift left by 8 bits
            return self.arithmetic_shift_left(data, shift_amount=8)
        elif amount == 0b10:  # Shift right by 1 bit (arithmetic shift)
            return self.arithmetic_shift_right(data, bit_count, shift_amount=1)
        elif amount == 0b11:  # Shift right by 8 bits (arithmetic shift)
            return self.arithmetic_shift_right(data, bit_count, shift_amount=8)
        else:
            return data  # No shift if invalid amount

    def arithmetic_shift_left(self, value, shift_amount):
        # Arithmetic shift left operation
        return (value << shift_amount) & ((1 << 64) - 1)

    def arithmetic_shift_right(self, value, bit_count, shift_amount):
        # Arithmetic shift right operation with sign extension
        sign_bit_mask = 1 << (bit_count - 1)  # Mask for the most significant bit

        if value & sign_bit_mask:  # If the sign bit is set
