class GoldenDUT:
    def __init__(self):
        # Initialize the internal counter and tc_register
        self.counter_reg = 0
        self.tc_reg = 0

    def load(self, signal_vector):
        # Update internal states based on load and data signals
        load_signal = signal_vector['load']
        data_input = signal_vector['data']

        if load_signal:
            self.counter_reg = data_input & 0x3FF  # Mask to ensure 10-bit value
        else:
            if self.counter_reg > 0:
                self.counter_reg -= 1  # Decrement the counter

        self.update_tc()

    def update_tc(self):
        # Update the terminal count register
        self.tc_reg = 1 if self.counter_reg == 0 else 0

    def check(self, signal_vector):
        # Compare the expected and observed tc output
        expected_tc = self.tc_reg
        observed_tc = signal_vector['tc']

        if expected_tc != observed_tc:
            print(f"Scenario: {signal_vector['scenario']}, expected: tc={expected_tc}, observed tc={observed_tc}")
            return False
        return True

