class GoldenDUT:
    def __init__(self):
        # Initialize registers and states
        self.state_reg = 'A'
        self.f_reg = 0
        self.g_reg = 0
        self.x_tracking_reg = []
        self.y_monitoring_reg = False
        self.y_monitoring_cycles_reg = 0

    def load(self, signal_vector):
        # Extract input signals
        self.resetn_reg = signal_vector['resetn']
        self.x_reg = signal_vector['x']
        self.y_reg = signal_vector['y']

        # FSM logic based on input signals
        if self.resetn_reg == 0:  # Reset condition active
            self.state_reg = 'A'
            self.f_reg = 0
            self.g_reg = 0
            self.x_tracking_reg = []
            self.y_monitoring_reg = False
            self.y_monitoring_cycles_reg = 0

        elif self.resetn_reg == 1:  # FSM operates if reset is not active
            if self.state_reg == 'A':
                self.f_reg = 1
                self.state_reg = 'B'
                self.x_tracking_reg = []
                self.y_monitoring_reg = False
                self.y_monitoring_cycles_reg = 0

            elif self.state_reg == 'B':
                self.f_reg = 0
                self.x_tracking_reg.append(self.x_reg)
                if len(self.x_tracking_reg) > 3:
                    self.x_tracking_reg.pop(0)

                if self.x_tracking_reg == [1, 0, 1]:
                    self.g_reg = 1
                    self.state_reg = 'C'
                    self.y_monitoring_reg = True
                    self.y_monitoring_cycles_reg = 0

            elif self.state_reg == 'C':
                if self.y_monitoring_reg:
                    if self.y_reg == 1:
                        self.g_reg = 1
                        self.y_monitoring_reg = False
                    else:
                        self.y_monitoring_cycles_reg += 1
                        if self.y_monitoring_cycles_reg >= 2:
                            self.g_reg = 0
                            self.y_monitoring_reg = False
                else:
                    self.g_reg = 1  # Maintain g=1 if already set and y was monitored successfully within limit

    def check(self, signal_vector):
        # Determine expected values
        f_expected = self.f_reg
        g_expected = self.g_reg
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']

        # Compare with observed values and return comparison result
        if f_expected != f_observed or g_expected != g_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={f_expected}, g={g_expected}, observed f={f_observed}, g={g_observed}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

