        self.state_reg = 'A'
        self.f_reg = 0
        self.g_reg = 0
        self.x_seq_reg = []
        self.f_triggered_reg = False
        self.g_set_cycle_reg = -1
        self.cycle_count_reg = 0

    def load(self, signal_vector):
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        if resetn == 0:
            self.state_reg = 'A'
            self.f_reg = 0
            self.g_reg = 0
            self.x_seq_reg = []
            self.f_triggered_reg = False
            self.g_set_cycle_reg = -1
            self.cycle_count_reg = 0
        else:
            if self.state_reg == 'A':
                if not self.f_triggered_reg:
                    self.f_reg = 1
                    self.f_triggered_reg = True
                else:
                    self.f_reg = 0
                    self.x_seq_reg.append(x)
                    if len(self.x_seq_reg) > 3:
                        self.x_seq_reg.pop(0)

                    if self.x_seq_reg == [1, 0, 1]:
                        self.g_reg = 1
                        self.g_set_cycle_reg = self.cycle_count_reg
                        self.state_reg = 'B'

            elif self.state_reg == 'B':
                if self.g_reg == 1:
                    if self.cycle_count_reg <= self.g_set_cycle_reg + 2:
                        if y == 1:
                            self.state_reg = 'C'
                    elif self.cycle_count_reg > self.g_set_cycle_reg + 2:
                        self.g_reg = 0
                        self.state_reg = 'A'

        self.cycle_count_reg += 1

    def check(self, signal_vector):
        f_observed = signal_vector['f']
        g_observed = signal_vector['g']
        scenario = signal_vector['scenario']

        if f_observed != self.f_reg or g_observed != self.g_reg:
            print(f"Scenario: {scenario}, expected: f={self.f_reg}, g={self.g_reg}, "
                  f"observed: f={f_observed}, g={g_observed}")
            return False
        return True

