    def __init__(self):
        # Initialize internal state registers
        self.y_reg = 0b000  # Present state y[2:0]
        self.Y0_reg = 0  # Output Y0
        self.z_reg = 0  # Output z
        self.x_reg = 0  # Initialize x register

    def load(self, signal_vector):
        # Load input signals and update internal state
        self.x_reg = signal_vector['x']
        self.update_state()

    def check(self, signal_vector):
        # Determine expected output values
        expected_Y0, expected_z = self.fsm_outputs(self.y_reg, self.x_reg)

        # Compare expected and observed outputs
        observed_Y0 = signal_vector['Y0']
        observed_z = signal_vector['z']

        if (expected_Y0 != observed_Y0) or (expected_z != observed_z):
            print(f"Scenario: {signal_vector['scenario']}, expected: Y0={expected_Y0}, z={expected_z}, "
                  f"observed Y0={observed_Y0}, z={observed_z}")
            return False
        return True

    def update_state(self):
        # Update state based on current state, input x, and state transition logic
        next_state, self.Y0_reg, self.z_reg = self.fsm_next_state_and_output(self.y_reg, self.x_reg)
        self.y_reg = next_state

    def fsm_next_state_and_output(self, y, x):
        # Dictionary to represent state transition table and outputs
        state_transition = {
            0b000: {0: (0b000, 0b000, 0), 1: (0b001, 0b001, 0)},
            0b001: {0: (0b001, 0b001, 0), 1: (0b100, 0b100, 0)},
            0b010: {0: (0b010, 0b010, 0), 1: (0b001, 0b001, 0)},
            0b011: {0: (0b001, 0b001, 1), 1: (0b010, 0b010, 1)},
            0b100: {0: (0b011, 0b011, 1), 1: (0b100, 0b100, 1)},
        }

        # Retrieve the next state and outputs based on the current state y and input x
        next_state, _, z = state_transition[y][x]

        # Calculate Y0 as the least significant bit of the current state (adjustment made here)
        Y0 = y & 0b001  
        return next_state, Y0, z

    def fsm_outputs(self, y, x):
        # Get output logic separately, using state transitions
        _, Y0, z = self.fsm_next_state_and_output(y, x)
