                  f"expected: q={expected_q}, state={expected_state}, "
                  f"observed: q={self.q_reg}, state={self.state_reg}")
            return False

    def dut_rule(self, clk, a, b, prev_q):
        # Define the next state calculation based on the rules
        if clk == 1:
            # Adjust logic here to properly hold state or change based on a and b
            if a == 0 and b == 1:
                next_q = 1
            elif a == 1 and b == 1:
                next_q = 0
            else:
                next_q = prev_q  # Hold the previous q value unless condition to reset it is fulfilled
