class GoldenDUT:
    def __init__(self):
        # Initialize any necessary internal states
        self.state = {}

    def load(self, signal_vector):
        # Load input signals
        a = signal_vector.get('a', 0)
        b = signal_vector.get('b', 0)
        c = signal_vector.get('c', 0)
        d = signal_vector.get('d', 0)    
        # Compute the expected output q
        expected_q = self._compute_expected_q(a, b, c, d)
        return expected_q

    def check(self, signal_vector):
        # Load and compute expected q
        expected_q = self.load(signal_vector)
        # Retrieve actual q from signal_vector
        actual_q = signal_vector.get('q', 0)
        # Compare expected and actual outputs
        return expected_q == actual_q

    def _compute_expected_q(self, a, b, c, d):
        # Corrected logic based on provided simulation waveforms
        if b == 1 and (c == 1 or d == 1):
            return 1
        elif a == 1 and d == 1:
            return 1
        else:
            return 0

# Example usage
golden_dut = GoldenDUT()
signal_vector = {'scenario': 1, 'a': 0, 'b': 1, 'c': 0, 'd': 1, 'q': 1}
print(golden_dut.check(signal_vector))  # Output: True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

