import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the golden DUT
        self.q_reg = 0  # The 256-bit state of the grid

    def load(self, signal_vector):
        # Update internal state according to signal inputs
        if signal_vector['load']:
            self.q_reg = signal_vector['data'] & ((1 << 256) - 1)  # Load data with bit mask for 256 bits
        else:
            self.q_reg = self.next_state()

    def check(self, signal_vector):
        # Calculate expected output and compare with DUT's output
        expected_q = self.q_reg
        observed_q = signal_vector['q']

        if expected_q != observed_q:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={bin(expected_q)}, observed: q={bin(observed_q)}")
            return False
        return True

    def next_state(self):
        # Convert current q_reg to 16x16 grid
        size = 16
        grid = np.array([(self.q_reg >> i) & 1 for i in range(256)]).reshape(size, size)
        next_grid = np.zeros((size, size), dtype=int)

        for row in range(size):
            for col in range(size):
                alive_neighbours = self.toroidal_neighbour_count(grid, row, col)
                current_cell_state = grid[row][col]

                # Apply game rules
                if alive_neighbours < 2 or alive_neighbours > 3:
                    next_grid[row][col] = 0
                elif alive_neighbours == 3:
                    next_grid[row][col] = 1
                else:  # alive_neighbours == 2
                    next_grid[row][col] = current_cell_state

        # Convert grid back to 256-bit state
        new_state = sum(next_grid[row][col] << (row * size + col) for row in range(size) for col in range(size))
        return new_state

    def toroidal_neighbour_count(self, grid, row, col, size=16):
        # Calculate number of alive neighbours
        neighbour_positions = [
            ((row - 1) % size, (col - 1) % size),
            ((row - 1) % size, col),
            ((row - 1) % size, (col + 1) % size),
            (row, (col - 1) % size),
            (row, (col + 1) % size),
            ((row + 1) % size, (col - 1) % size),
            ((row + 1) % size, col),
            ((row + 1) % size, (col + 1) % size)
        ]

        return sum(grid[r][c] for r, c in neighbour_positions)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
