class GoldenDUT:
    def __init__(self):
        # Initialize internal state registers with default values (12:00:00 AM)
        self.hh_reg = 0x12
        self.mm_reg = 0x00
        self.ss_reg = 0x00
        self.pm_reg = 0

    def load(self, signal_vector):
        reset = signal_vector['reset']
        ena = signal_vector['ena']

        if reset:
            # Reset condition: Clock should reset to 12:00:00 AM
            self.hh_reg = 0x12
            self.mm_reg = 0x00
            self.ss_reg = 0x00
            self.pm_reg = 0
        elif ena:
            # Increment seconds
            if self.ss_reg == 0x59:
                self.ss_reg = 0x00
                # Increment minutes
                if self.mm_reg == 0x59:
                    self.mm_reg = 0x00
                    # Increment hours
                    if self.hh_reg == 0x11:
                        self.hh_reg = 0x12
                        self.pm_reg = not self.pm_reg  # Toggle PM/AM at 11:59:59 to 12:00:00
                    elif self.hh_reg == 0x12:
                        self.hh_reg = 0x01
                    else:
                        self.hh_reg += 0x01
                else:
                    self.mm_reg += 0x01
            else:
                self.ss_reg += 0x01

    def check(self, signal_vector):
        a_observed_hh = signal_vector['hh']
        a_observed_mm = signal_vector['mm']
        a_observed_ss = signal_vector['ss']
        a_observed_pm = signal_vector['pm']

        scenario = signal_vector['scenario']

        # Compare the expected and observed values
        if (self.hh_reg == a_observed_hh and
            self.mm_reg == a_observed_mm and
            self.ss_reg == a_observed_ss and
            self.pm_reg == a_observed_pm):
            return True
        else:
            print(f"Scenario: {scenario}, expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, "
                  f"observed: hh={a_observed_hh}, mm={a_observed_mm}, ss={a_observed_ss}, pm={a_observed_pm}")
            return False
