import numpy as np

def bcd_to_int(bcd_value):
    tens = (bcd_value >> 4) & 0b1111
    ones = bcd_value & 0b1111
    return tens * 10 + ones

def int_to_bcd(number):
    tens = (number // 10) & 0b1111
    ones = number % 10
    return (tens << 4) | ones

def clock_increment(hh, mm, ss, pm):
    hours = bcd_to_int(hh)
    minutes = bcd_to_int(mm)
    seconds = bcd_to_int(ss)

    # Increment seconds
    seconds += 1
    if seconds == 60:
        seconds = 0
        minutes += 1
        if minutes == 60:
            minutes = 0
            hours += 1
            if hours == 12:
                # Toggle PM when reaching 12
                pm = not pm
            elif hours > 12:
                # Adjust hours back to 1, since 12-hour cycle is used
                hours = 1

    hh_new = int_to_bcd(hours)
    mm_new = int_to_bcd(minutes)
    ss_new = int_to_bcd(seconds)

    return hh_new, mm_new, ss_new, pm

def reset_clock():
    return int_to_bcd(12), int_to_bcd(0), int_to_bcd(0), False

class GoldenDUT:
    def __init__(self):
        self.hh_reg = 0x0
        self.mm_reg = 0x0
        self.ss_reg = 0x0
        self.pm_reg = False

    def load(self, signal_vector):
        if signal_vector['reset']:
            self.hh_reg, self.mm_reg, self.ss_reg, self.pm_reg = reset_clock()
        elif signal_vector['ena']:
            self.hh_reg, self.mm_reg, self.ss_reg, self.pm_reg = clock_increment(
                self.hh_reg, self.mm_reg, self.ss_reg, self.pm_reg)

    def check(self, signal_vector):
        hh_observed = signal_vector['hh']
        mm_observed = signal_vector['mm']
        ss_observed = signal_vector['ss']
        pm_observed = signal_vector['pm']

        if (self.hh_reg == hh_observed and self.mm_reg == mm_observed and 
            self.ss_reg == ss_observed and self.pm_reg == pm_observed):
            return True

        # Printing error message if failure
        print(f"Scenario: {signal_vector['scenario']}, expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, "
              f"observed: hh={hh_observed}, mm={mm_observed}, ss={ss_observed}, pm={pm_observed}")
        return False
