class GoldenDUT:
    def __init__(self):
        self.x_reg = 0  # Current input bit
        self.z_reg = 0  # Current output bit
        self.state_reg = 0  # State of the machine (0: initial/reset, 1: normal operation)
        self.compliment_carry = 1  # Carry for the 2's complement operation

    def load(self, signal_vector):
        # Load the input signal into the register
        self.x_reg = signal_vector['x']

        # Handle asynchronous reset
        if signal_vector['areset'] == 1:
            # Ensure complete reset of all relevant states
            self.state_reg = 0
            self.z_reg = 0
            self.compliment_carry = 1
        else:
            # In normal operation state
            if self.state_reg == 0:
                # Move to normal operation if not in reset
                self.state_reg = 1
                self.compliment_carry = 1  # Ensure carry is reset to 1 at the start of operation

            # Perform the inversion on the input bit
            inverted_bit = 1 - self.x_reg

            # Add the carry to get the 2's complement bit
            total = inverted_bit + self.compliment_carry
            self.z_reg = total % 2
            self.compliment_carry = total // 2

    def check(self, signal_vector):
        # Check if 'check_en' is true, which indicates that checking should occur
        if signal_vector['check_en']:
            expected_z = self.z_reg
            observed_z = signal_vector['z']

            if expected_z == observed_z:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

