class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.output_reg = 0
        self.bit_sequence = []

    def load(self, signal_vector):
        areset = signal_vector['areset']
        x = signal_vector['x']

        if areset:
            # Reset the state and outputs
            self.state_reg = 'IDLE'
            self.output_reg = 0
            self.bit_sequence = []
        else:
            # Transition to ACTIVE state if IDLE
            if self.state_reg == 'IDLE':
                self.state_reg = 'ACTIVE'

            if self.state_reg == 'ACTIVE':
                # Append bits during ACTIVE state and ensure correct sequence handling
                self.bit_sequence.append(x)
                self.output_reg = self.calculate_twos_complement(self.bit_sequence)

    def calculate_twos_complement(self, bit_sequence):
        n = len(bit_sequence)
        if n == 0:
            return 0

        # Calculate 1's complement (invert bits)
        ones_complement = [1 - bit for bit in bit_sequence]

        # Add 1 to get 2's complement
        twos_complement = self.add_binary(ones_complement, [1] + [0]*(n-1))

        # Convert list to integer (handling LSB-first order)
        return int(''.join(map(str, reversed(twos_complement))), 2)

    def add_binary(self, a, b):
        """ Adds two binary numbers represented as lists of bits. """
        n = len(a)
        c = [0] * n
        carry = 0
        for i in range(n):
            c[i] = a[i] + b[i] + carry
            if c[i] > 1:
                c[i] -= 2
                carry = 1
            else:
                carry = 0
        return c

    def check(self, signal_vector):
        expected_z = self.output_reg
        observed_z = signal_vector['z']

        if observed_z == expected_z:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False
