class GoldenDUT:
    def __init__(self):
        # Initialize the state registers; starting with NORMAL_STATE
        self.NORMAL_STATE = 0
        self.COMPLEMENT_STATE = 1

        self.current_state_reg = self.NORMAL_STATE
        self.z_reg = 0
        self.areset_reg = 0
        self.x_reg = 0

    def load(self, signal_vector):
        # Capture input signals
        self.areset_reg = signal_vector['areset']
        self.x_reg = signal_vector['x']

        # Process reset behavior
        if self.areset_reg == 1:
            # Ensure async reset goes back to initial state
            self.current_state_reg = self.NORMAL_STATE
            self.z_reg = 0 
        else:
            # Handle state transitions correctly
            if self.current_state_reg == self.NORMAL_STATE:
                self.z_reg = ~self.x_reg & 0b1  # Output is the inverted input bit
                if self.x_reg == 1:
                    # Transition to COMPLEMENT_STATE only once, on receiving a '1'
                    self.current_state_reg = self.COMPLEMENT_STATE
            elif self.current_state_reg == self.COMPLEMENT_STATE:
                # In COMPLEMENT_STATE, the output should remain the inverted input bit
                self.z_reg = ~self.x_reg & 0b1

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        # Check if the computed z matches the observed z
        if z_observed != self.z_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
            return False
        return True

    def reset_state(self):
        # Reset the internal state; useful for explicitly resetting outside of load
        self.current_state_reg = self.NORMAL_STATE
        self.z_reg = 0
