        in_byte = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.message_byte_count_reg = 0
            self.done_reg = False
        else:
            if self.message_byte_count_reg == 0:
                if (in_byte & 0b00001000):
                    # Start of new message
                    self.message_byte_count_reg = 1
            elif self.message_byte_count_reg > 0 and self.message_byte_count_reg < 3:
                # Increment the byte count within the message
                self.message_byte_count_reg += 1
            elif self.message_byte_count_reg == 3:
                # Message completion
                self.done_reg = True
                # Reset byte count immediately after message completion
                self.message_byte_count_reg = 0
            else:
                self.done_reg = False

    def check(self, signal_vector):
        observed_done = signal_vector['done']
        expected_done = self.done_reg

        if observed_done != expected_done:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={observed_done}")
            return False

        # After checking, prepare for the next cycle
        if self.done_reg:
            # Reset done_reg to False immediately after checking
            self.done_reg = False

        return True
