class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.byte_count_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            self.state_reg = 'IDLE'
            self.byte_count_reg = 0
            self.message_reg = [0, 0, 0]
            self.done_reg = 0
            self.out_bytes_reg = 0  # Clear out_bytes_reg when resetting
        else:
            self.process_byte(signal_vector['in'])
            self.finalize_done_transition()

    def process_byte(self, byte):
        bits = [(byte >> i) & 1 for i in range(8)]

        if self.state_reg == 'IDLE':
            if bits[3] == 1:
                self.state_reg = 'RECEIVING'
                self.byte_count_reg = 1
                self.message_reg[0] = byte

        elif self.state_reg == 'RECEIVING':
            self.message_reg[self.byte_count_reg] = byte
            self.byte_count_reg += 1

            if self.byte_count_reg == 3:
                self.state_reg = 'DONE'
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                self.done_reg = 1

        elif self.state_reg == 'DONE':
            pass

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            out_bytes_observed = signal_vector['out_bytes']

            if done_observed != self.done_reg or out_bytes_observed != self.out_bytes_reg:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: done={self.done_reg}, out_bytes={hex(self.out_bytes_reg)}, "
                      f"observed: done={done_observed}, out_bytes={hex(out_bytes_observed)}")
                return False
        return True

    def finalize_done_transition(self):
        # Reset the done signal after it is used, i.e., once checked for condition
        if self.state_reg == 'DONE':
            self.state_reg = 'IDLE'  # Go back to IDLE to start looking for new message
            self.done_reg = 0  # Clear done_reg for next message detection
def check_dut(vectors_in):
