import numpy as np

class GoldenDUT:
    def __init__(self):
        self.pht = np.zeros(128, dtype=np.uint8)  # 128-entry table of 2-bit saturating counters
        self.global_history_reg = 0b0000000  # 7-bit global history register
        self.predict_taken_reg = 'x'
        self.predict_history_reg = 'x'

    def load(self, signal_vector):
        if signal_vector['areset']:  # Asynchronous reset
            self.global_history_reg = 0b0000000
            self.pht = np.zeros(128, dtype=np.uint8)
            self.predict_taken_reg = 'x'
            self.predict_history_reg = 'x'

        if signal_vector['train_valid']:
            self.train(signal_vector)

        if signal_vector['predict_valid']:
            self.predict(signal_vector)

    def predict(self, signal_vector):
        pc = signal_vector['predict_pc']
        index = (pc ^ self.global_history_reg) & 0b1111111  # XOR to generate index, ensuring it's within bounds
        self.predict_taken_reg = self.pht[index] >= 2
        self.predict_history_reg = self.global_history_reg

        # Ensure the history is updated only if training does not occur
        if not (signal_vector['train_mispredicted'] and signal_vector['train_valid']):
            self.update_history_register(self.predict_taken_reg)

    def train(self, signal_vector):
        pc = signal_vector['train_pc']
        actual_taken = signal_vector['train_taken']
        mispredicted = signal_vector['train_mispredicted']
        index = (pc ^ signal_vector['train_history']) & 0b1111111

        # If mispredicted, restore history to after the mispredicted branch
        if mispredicted:
            self.global_history_reg = signal_vector['train_history']

        # Update the corresponding PHT entry
        self.pht[index] = self.saturating_counter_update(self.pht[index], actual_taken)

    def check(self, signal_vector):
        if not signal_vector.get('check_en', False):
            return True

        expected_taken = self.predict_taken_reg
        expected_history = self.predict_history_reg
        observed_taken = signal_vector['predict_taken']
        observed_history = signal_vector['predict_history']

        if (expected_taken != observed_taken or
                expected_history != observed_history):
            print(f"Scenario: {signal_vector['scenario']}, expected: taken={expected_taken}, history={expected_history} | "
                  f"observed: taken={observed_taken}, history={observed_history}")
            return False
        return True

    def saturating_counter_update(self, value, taken):
        # Two-bit saturating counter: value ranges from 0 to 3
        if taken:
            if value < 3:
                return value + 1
        else:
            if value > 0:
                return value - 1
        return value

    def update_history_register(self, taken):
        # Ensure 7-bit shift for the global history register
        self.global_history_reg = ((self.global_history_reg << 1) | int(taken)) & 0b1111111
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

