class GoldenDUT:
    def __init__(self):
        # Initialize internal state with 'walk_left' active
        self.walk_left_reg = 1
        self.walk_right_reg = 0

    def load(self, signal_vector):
        # Extract signals
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']

        # Asynchronous reset
        if areset:
            self.walk_left_reg = 1
            self.walk_right_reg = 0
        else:
            # State transition logic
            if self.walk_left_reg and (bump_left or (bump_left and bump_right)):
                # Transition to walking right
                self.walk_left_reg = 0
                self.walk_right_reg = 1
            elif self.walk_right_reg and (bump_right or (bump_left and bump_right)):
                # Transition to walking left
                self.walk_left_reg = 1
                self.walk_right_reg = 0

    def check(self, signal_vector):
        # Check whether it's the time to validate the outputs
        if signal_vector['check_en']:
            # Expected outputs from DUT
            walk_left_observed = signal_vector['walk_left']
            walk_right_observed = signal_vector['walk_right']

            # Compare expected values with observed values
            if (self.walk_left_reg == walk_left_observed) and (self.walk_right_reg == walk_right_observed):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected: walk_left={self.walk_left_reg}, "
                      f"walk_right={self.walk_right_reg}, observed: walk_left={walk_left_observed}, "
                      f"walk_right={walk_right_observed}")
                return False

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

