class GoldenDUT:
    def __init__(self):
        # Initialize internal state with registered suffix _reg
        self.state_reg = 'walking_left'
        self.walk_left_reg = 1
        self.walk_right_reg = 0

    def load(self, signal_vector):
        # Load inputs from the signal vector and update internal states
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']

        # Update state on a new clock cycle
        if areset:
            self.state_reg = 'walking_left'
            self.walk_left_reg = 1
            self.walk_right_reg = 0
        else:
            if self.state_reg == 'walking_left':
                if bump_left:
                    self.state_reg = 'walking_right'
                    self.walk_left_reg = 0
                    self.walk_right_reg = 1
            elif self.state_reg == 'walking_right':
                if bump_right:
                    self.state_reg = 'walking_left'
                    self.walk_left_reg = 1
                    self.walk_right_reg = 0

    def check(self, signal_vector):
        # Compare DUT output with expected values from the GoldenDUT
        if signal_vector['check_en']:
            walk_left_observed = signal_vector['walk_left']
            walk_right_observed = signal_vector['walk_right']

            expected_walk_left = self.walk_left_reg
            expected_walk_right = self.walk_right_reg

            if (walk_left_observed == expected_walk_left and
                    walk_right_observed == expected_walk_right):
                return True
            else:
                # Print error message if there is a mismatch
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: walk_left={expected_walk_left}, walk_right={expected_walk_right}, "
                      f"observed: walk_left={walk_left_observed}, walk_right={walk_right_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

