    def __init__(self):
        # Setting initial inner state and outputs of the Golden DUT
        self.state_reg = 'WALK_LEFT'  # Initial state is WALK_LEFT
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.previous_state_reg = self.state_reg

    def load(self, signal_vector):
        # Load the input signals and determine the next state
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']

        if areset:
            self.state_reg = 'WALK_LEFT'
            self.walk_left_reg = 1
            self.walk_right_reg = 0
            self.aaah_reg = 0
