class GoldenDUT:
    def __init__(self):
        # Define initial state
        self.state_reg = 'WALK_LEFT'
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def load(self, signal_vector):
        # Unpack input signals from the signal vector
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        # Reset condition
        if areset:
            self._reset()
        else:
            self._update_state(bump_left, bump_right, ground, dig)

    def check(self, signal_vector):
        expected_walk_left = self.walk_left_reg
        expected_walk_right = self.walk_right_reg
        expected_aaah = self.aaah_reg
        expected_digging = self.digging_reg

        observed_walk_left = signal_vector['walk_left']
        observed_walk_right = signal_vector['walk_right']
        observed_aaah = signal_vector['aaah']
        observed_digging = signal_vector['digging']

        # Compare expected and observed outputs
        if (
            expected_walk_left == observed_walk_left and
            expected_walk_right == observed_walk_right and
            expected_aaah == observed_aaah and
            expected_digging == observed_digging
        ):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, "
                  f"expected: walk_left={expected_walk_left}, observed walk_left={observed_walk_left}, "
                  f"expected: walk_right={expected_walk_right}, observed walk_right={observed_walk_right}, "
                  f"expected: aaah={expected_aaah}, observed aaah={observed_aaah}, "
                  f"expected: digging={expected_digging}, observed digging={observed_digging}")
            return False

    def _reset(self):
        # Reset the Lemming to initial state (walking left)
        self.state_reg = 'WALK_LEFT'
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def _update_state(self, bump_left, bump_right, ground, dig):
        if self.state_reg in ['FALL_LEFT', 'FALL_RIGHT']:
            # Handle falling state
            if ground == 1:
                # Resume walking in original direction after falling
                if self.state_reg == 'FALL_LEFT':
                    self._set_state('WALK_LEFT')
                else:
                    self._set_state('WALK_RIGHT')
            else:
                # Continue falling
                self._set_state(self.state_reg)
        elif ground == 1 and dig == 1:
            # Handle digging
            if self.state_reg == 'WALK_LEFT':
                self._set_state('DIG_LEFT')
            elif self.state_reg == 'WALK_RIGHT':
                self._set_state('DIG_RIGHT')
        elif self.state_reg in ['DIG_LEFT', 'DIG_RIGHT']:
            # Continue digging until ground disappears
            if ground == 0:
                if self.state_reg == 'DIG_LEFT':
                    self._set_state('FALL_LEFT')
                else:
                    self._set_state('FALL_RIGHT')
        elif self.state_reg == 'WALK_LEFT' and bump_left == 1:
            self._set_state('WALK_RIGHT')
        elif self.state_reg == 'WALK_RIGHT' and bump_right == 1:
            self._set_state('WALK_LEFT')
        elif bump_left == 1 and bump_right == 1:
            # Switch direction on simultaneous bumps
            if self.state_reg == 'WALK_LEFT':
                self._set_state('WALK_RIGHT')
            else:
                self._set_state('WALK_LEFT')
        elif ground == 0:
            # Transition to falling if no ground
            if self.state_reg == 'WALK_LEFT':
                self._set_state('FALL_LEFT')
            elif self.state_reg == 'WALK_RIGHT':
                self._set_state('FALL_RIGHT')

    def _set_state(self, state):
        self.state_reg = state
        if state == 'WALK_LEFT':
            self.walk_left_reg = 1
            self.walk_right_reg = 0
            self.aaah_reg = 0
            self.digging_reg = 0
        elif state == 'WALK_RIGHT':
            self.walk_left_reg = 0
            self.walk_right_reg = 1
            self.aaah_reg = 0
            self.digging_reg = 0
        elif state == 'FALL_LEFT':
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.aaah_reg = 1
            self.digging_reg = 0
        elif state == 'FALL_RIGHT':
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.aaah_reg = 1
            self.digging_reg = 0
        elif state == 'DIG_LEFT':
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.aaah_reg = 0
            self.digging_reg = 1
        elif state == 'DIG_RIGHT':
            self.walk_left_reg = 0
            self.walk_right_reg = 0
            self.aaah_reg = 0
            self.digging_reg = 1

