class GoldenDUT:
    # State representation
    WALK_LEFT = 0
    WALK_RIGHT = 1
    FALL_LEFT = 2
    FALL_RIGHT = 3
    DIG_LEFT = 4
    DIG_RIGHT = 5

    def __init__(self):
        # Initialize the state
        self.current_state_reg = GoldenDUT.WALK_LEFT
        # Initialize registers
        self.areset_reg = 0
        self.bump_left_reg = 0
        self.bump_right_reg = 0
        self.ground_reg = 1
        self.dig_reg = 0

    def load(self, signal_vector):
        # Load input signals
        self.areset_reg = signal_vector['areset']
        self.bump_left_reg = signal_vector['bump_left']
        self.bump_right_reg = signal_vector['bump_right']
        self.ground_reg = signal_vector['ground']
        self.dig_reg = signal_vector['dig']

        self.state_transition()

    def state_transition(self):
        if self.areset_reg:
            self.current_state_reg = GoldenDUT.WALK_LEFT
        else:
            if self.current_state_reg in [GoldenDUT.WALK_LEFT, GoldenDUT.WALK_RIGHT]:
                # Falling takes highest precedence
                if not self.ground_reg:
                    self.current_state_reg = GoldenDUT.FALL_LEFT if self.current_state_reg == GoldenDUT.WALK_LEFT else GoldenDUT.FALL_RIGHT
                # Digging takes precedence over direction switch
                elif self.dig_reg and self.ground_reg:
                    self.current_state_reg = GoldenDUT.DIG_LEFT if self.current_state_reg == GoldenDUT.WALK_LEFT else GoldenDUT.DIG_RIGHT
                # Switch direction if bumped left or right
                elif (self.bump_left_reg or self.bump_right_reg) and self.ground_reg:
                    self.current_state_reg = GoldenDUT.WALK_RIGHT if self.current_state_reg == GoldenDUT.WALK_LEFT else GoldenDUT.WALK_LEFT

            elif self.current_state_reg == GoldenDUT.FALL_LEFT:
                if self.ground_reg:
                    # Resume walking original direction
                    self.current_state_reg = GoldenDUT.WALK_LEFT

            elif self.current_state_reg == GoldenDUT.FALL_RIGHT:
                if self.ground_reg:
                    self.current_state_reg = GoldenDUT.WALK_RIGHT

            elif self.current_state_reg == GoldenDUT.DIG_LEFT:
                if not self.ground_reg:
                    self.current_state_reg = GoldenDUT.FALL_LEFT

            elif self.current_state_reg == GoldenDUT.DIG_RIGHT:
                if not self.ground_reg:
                    self.current_state_reg = GoldenDUT.FALL_RIGHT

    def compute_outputs(self):
        if self.current_state_reg == GoldenDUT.WALK_LEFT:
            return (1, 0, 0, 0)
        elif self.current_state_reg == GoldenDUT.WALK_RIGHT:
            return (0, 1, 0, 0)
        elif self.current_state_reg in [GoldenDUT.FALL_LEFT, GoldenDUT.FALL_RIGHT]:
            return (0, 0, 1, 0)
        elif self.current_state_reg in [GoldenDUT.DIG_LEFT, GoldenDUT.DIG_RIGHT]:
            return (0, 0, 0, 1)
        else:
            return (0, 0, 0, 0)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            walk_left_observed = signal_vector['walk_left']
            walk_right_observed = signal_vector['walk_right']
            aaah_observed = signal_vector['aaah']
            digging_observed = signal_vector['digging']

            walk_left_exp, walk_right_exp, aaah_exp, digging_exp = self.compute_outputs()

            if (walk_left_observed == walk_left_exp and
                walk_right_observed == walk_right_exp and
                aaah_observed == aaah_exp and
                digging_observed == digging_exp):
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: walk_left={walk_left_exp}, walk_right={walk_right_exp}, "
                      f"aaah={aaah_exp}, digging={digging_exp}, "
                      f"observed: walk_left={walk_left_observed}, walk_right={walk_right_observed}, "
                      f"aaah={aaah_observed}, digging={digging_observed}")
                return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

