class GoldenDUT:
    def __init__(self):
        self.state_reg = 'walk_left'
        self.fall_count_reg = 0
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0
        self.previous_direction = 'walk_left'  # Track the previous direction

    def load(self, signal_vector):
        if signal_vector['areset']:
            self._reset()
        elif signal_vector['ground'] == 0 and self.state_reg != 'aaah':
            self._start_falling()
        elif self.state_reg == 'aaah':
            self._continue_falling(signal_vector['ground'])
        elif self.state_reg.startswith('walk') and signal_vector['dig'] == 1 and signal_vector['ground'] == 1:
            self._start_digging()
        elif self.state_reg == 'digging' and signal_vector['ground'] == 0:
            self._start_falling()
        elif self.state_reg.startswith('walk'):
            self._handle_walking(signal_vector['bump_left'], signal_vector['bump_right'])

    def check(self, signal_vector):
        observed = {
            'walk_left': signal_vector['walk_left'],
            'walk_right': signal_vector['walk_right'],
            'aaah': signal_vector['aaah'],
            'digging': signal_vector['digging']
        }
        expected = {
            'walk_left': self.walk_left_reg,
            'walk_right': self.walk_right_reg,
            'aaah': self.aaah_reg,
            'digging': self.digging_reg
        }
        if signal_vector['check_en'] and observed != expected:
            print(f"Scenario: {signal_vector['scenario']}, expected: {expected}, observed: {observed}")
            return False
        return True

    def _reset(self):
        self.state_reg = 'walk_left'
        self.previous_direction = 'walk_left'
        self.fall_count_reg = 0
        self.walk_left_reg = 1
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def _start_falling(self):
        self.previous_direction = self.state_reg
        self.state_reg = 'aaah'
        self.fall_count_reg = 1
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 1
        self.digging_reg = 0

    def _continue_falling(self, ground):
        if ground == 1:
            if self.fall_count_reg > 20:
                self._splatter()
            else:
                self._resume_walking()
        else:
            self.fall_count_reg += 1

    def _resume_walking(self):
        # Correctly resume the previous walking direction
        self.state_reg = self.previous_direction
        self.walk_left_reg = 1 if self.previous_direction == 'walk_left' else 0
        self.walk_right_reg = 1 if self.previous_direction == 'walk_right' else 0
        self.aaah_reg = 0
        self.fall_count_reg = 0

    def _start_digging(self):
        self.previous_direction = self.state_reg
        self.state_reg = 'digging'
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 1

    def _handle_walking(self, bump_left, bump_right):
        if (bump_left and self.state_reg == 'walk_left') or (bump_right and self.state_reg == 'walk_right'):
            self._switch_directions()

    def _switch_directions(self):
        if self.state_reg == 'walk_left':
            self.state_reg = 'walk_right'
            self.walk_left_reg = 0
            self.walk_right_reg = 1
        else:
            self.state_reg = 'walk_left'
            self.walk_left_reg = 1
            self.walk_right_reg = 0
        # Ensure that 'previous_direction' is updated to reflect the switch correctly
        self.previous_direction = self.state_reg

    def _splatter(self):
        # Ensure all outputs become 0 and stop the Lemming
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

