class GoldenDUT:
    def __init__(self):
        self.state_reg = "WALK_LEFT"
        self.fall_count_reg = 0
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        if areset:
            self.reset()
            return

        if ground == 0:  # Falling state has the highest precedence
            self.fall_count_reg += 1
            if self.fall_count_reg > 20:
                self.stop_all()  # Splatter state; all outputs become 0
                return  # Ensure we stop further state changes
            else:
                self.set_state("FALL")
        else:
            if self.fall_count_reg > 20:
                self.stop_all()
                return

            self.fall_count_reg = 0  # Reset fall count after successful ground contact

            if self.state_reg == "FALL":
                # Resume walking in previous direction
                if self.walk_left_reg:
                    self.set_state("WALK_LEFT")
                else:
                    self.set_state("WALK_RIGHT")
            elif dig == 1 and ground == 1:
                self.set_state("DIGGING")
            else:
                # Handle bump logic
                if bump_left and bump_right:
                    self.state_reg = {'WALK_LEFT': 'WALK_RIGHT', 'WALK_RIGHT': 'WALK_LEFT'}[self.state_reg]
                elif bump_left:
                    self.state_reg = "WALK_RIGHT"
                elif bump_right:
                    self.state_reg = "WALK_LEFT"

                self.set_state(self.state_reg)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_outputs = self.get_expected_outputs()
            observed_outputs = (
                signal_vector['walk_left'],
                signal_vector['walk_right'],
                signal_vector['aaah'],
                signal_vector['digging']
            )
            if expected_outputs != observed_outputs:
                print(f"Scenario: {signal_vector['scenario']}, expected: {expected_outputs}, observed: {observed_outputs}")
                return False
        return True

    def reset(self):
        self.state_reg = "WALK_LEFT"
        self.fall_count_reg = 0
        self.walk_left_reg = 1
        self.stop_all()
        self.walk_left_reg = 1  # After reset, walk left

    def stop_all(self):
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def set_state(self, state):
        self.stop_all()  # Clear previous states first
        if state == "FALL":
            self.aaah_reg = 1
        elif state == "DIGGING":
            self.digging_reg = 1
        elif state == "WALK_LEFT":
            self.walk_left_reg = 1
        elif state == "WALK_RIGHT":
            self.walk_right_reg = 1

    def get_expected_outputs(self):
        return (
            self.walk_left_reg,
            self.walk_right_reg,
            self.aaah_reg,
            self.digging_reg
        )
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

