class GoldenDUT:
    def __init__(self):
        # Initialize the internal state of the D Flip-Flop with '0' indicating the unknown state has been resolved
        self.out_reg = 0

    def load(self, signal_vector):
        # Read the input signal
        input_signal = signal_vector['in']

        # Calculate the XOR of the current input and the last output
        xor_output = input_signal ^ self.out_reg

        # Update the D Flip-Flop output (register it)
        self.out_reg = xor_output

    def check(self, signal_vector):
        # Expected output is the current state of out_reg
        expected_out = self.out_reg
        # Observed output from DUT
        observed_out = signal_vector['out']

        # Check if we need to validate the output
        if signal_vector['check_en']:
            # Compare expected output with observed output
            if expected_out != observed_out:
                # If not matching, print an error and return False
                print(f"Scenario: {signal_vector['scenario']}, expected: out={expected_out}, observed out={observed_out}")
                return False
        # If outputs match or no check was needed, return True
        return True
