        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000
        }
        # Reverse mapping for convenience
        self.states_reverse = {v: k for k, v in self.states.items()}

    def next_state(self, current_state, w):
        if current_state == self.states['A']:
            return self.states['B'] if w == 0 else self.states['A']
        elif current_state == self.states['B']:
            return self.states['C'] if w == 0 else self.states['D']
        elif current_state == self.states['C']:
            return self.states['E'] if w == 0 else self.states['D']
        elif current_state == self.states['D']:
            return self.states['F'] if w == 0 else self.states['A']
        elif current_state == self.states['E']:
            return self.states['E'] if w == 0 else self.states['D']
        elif current_state == self.states['F']:
            return self.states['C'] if w == 0 else self.states['D']
        else:
            raise ValueError("Invalid current state")

    def load(self, signal_vector):
        current_state = signal_vector['y']
        w = signal_vector['w']

