class GoldenDUT:
    def __init__(self):
        self.state_reg = "SEARCH"
        self.pattern_reg = [1, 1, 0, 1]
        self.data_buffer_reg = []
        self.delay_reg = 0
        self.counter_reg = 0
        self.count_reg = 0
        self.counting_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        reset = signal_vector['reset']
        data = signal_vector['data']
        ack = signal_vector['ack']

        if reset:
            self.reset_state()
        else:
            if self.state_reg == "SEARCH":
                self.data_buffer_reg.append(data)
                if len(self.data_buffer_reg) > 4:
                    self.data_buffer_reg.pop(0)

                if self.data_buffer_reg == self.pattern_reg:
                    self.state_reg = "DELAY_CAPTURE"
                    self.data_buffer_reg.clear()
            elif self.state_reg == "DELAY_CAPTURE":
                self.data_buffer_reg.append(data)
                if len(self.data_buffer_reg) == 4:
                    self.delay_reg = int(''.join(map(str, self.data_buffer_reg)), 2)
                    self.state_reg = "COUNTING"
                    self.counter_reg = (self.delay_reg + 1) * 1000
                    self.counting_reg = 1
                    self.data_buffer_reg.clear()  # Clear buffer after capturing delay value
            elif self.state_reg == "COUNTING":
                if self.counter_reg > 0:
                    self.counter_reg -= 1
                    # Accurate calculation of count_reg
                    self.count_reg = (self.counter_reg + 999) // 1000  # Ceiling-like effect without math.ceil
                else:
                    self.state_reg = "DONE"
                    self.counting_reg = 0
                    self.done_reg = 1
            elif self.state_reg == "DONE":
                if ack:
                    self.reset_state()

    def check(self, signal_vector):
        count_observed = signal_vector['count']
        counting_observed = signal_vector['counting']
        done_observed = signal_vector['done']

        correct = True

        if count_observed != self.count_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: count={self.count_reg}, observed count={count_observed}")
            correct = False
        if counting_observed != self.counting_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: counting={self.counting_reg}, observed counting={counting_observed}")
            correct = False
        if done_observed != self.done_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={self.done_reg}, observed done={done_observed}")
            correct = False

        return correct

    def reset_state(self):
        self.state_reg = "SEARCH"
        self.data_buffer_reg.clear()
        self.delay_reg = 0
        self.counter_reg = 0
        self.count_reg = 0
        self.counting_reg = 0
        self.done_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

