class GoldenDUT:
    def __init__(self):
        self.current_state = 0
        self.start_shifting_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            self.current_state = 0
            self.start_shifting_reg = 0
        else:
            data = signal_vector['data']
            if self.start_shifting_reg == 1:
                return

            # FSM Transitions
            if self.current_state == 0:
                self.current_state = 1 if data == 1 else 0
            elif self.current_state == 1:
                if data == 1:
                    self.current_state = 2
                else:
                    self.current_state = 0
            elif self.current_state == 2:
                if data == 0:
                    self.current_state = 3
                else:
                    self.current_state = 2
            elif self.current_state == 3:
                if data == 1:
                    self.current_state = 0
                    self.start_shifting_reg = 1
                else:
                    self.current_state = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            a_observed = signal_vector['start_shifting']
            if a_observed != self.start_shifting_reg:
                print(f"Scenario: {signal_vector['scenario']}, expected: start_shifting={self.start_shifting_reg}, observed start_shifting={a_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

