        count_ena = signal_vector['count_ena']
        data = signal_vector.get('data', 0)  # Default to 0 if not provided

        # Execute logic based on shift and count enable signals
        if shift_ena and not count_ena:
            # Ensure data input is only the least significant bit
            data_bit = data & 0b1
            self.q_reg = self._shift_msb_first(self.q_reg, data_bit)
        elif count_ena and not shift_ena:
            self.q_reg = self._decrement(self.q_reg)
        # No change is needed for the undefined behavior if both are 1,
        # but ensure consistent internal state updating is handled appropriately

    def check(self, signal_vector):
        q_observed = signal_vector['q']  # Observed output from the DUT
        scenario = signal_vector['scenario']
