            print(f"Scenario: {scenario}, expected: q={self.q_reg}, observed q={q_observed}")
            return False
        return True

    def _shift_msb_first(self, register, data_in):
        # Shift MSB first logic with register bit mask (4 bits)
        return ((register << 1) & 0b1111) | data_in

