        shift_ena = signal_vector['shift_ena']
        count_ena = signal_vector['count_ena']
        data = signal_vector.get('data', 0)

        # handle simultaneous enable case explicitly
        if shift_ena == 1 and count_ena == 1:
            # Define behavior if necessary, or leave as no-operation per problem context
            pass  # Simultaneous enable does nothing explicit
        elif shift_ena == 1:  # Shift operation
            self.shift(data)
        elif count_ena == 1:  # Decrement operation
            self.decrement()

    def shift(self, data):
        # Perform the shift operation: shift left and input the new bit
        # Ensuring we only maintain a 4-bit register
        self.q_reg = ((self.q_reg << 1) & 0b1111) | (data & 0b0001)

    def decrement(self):
        # Decrement if greater than 0, ensure it does not go negative
        if self.q_reg > 0:
            self.q_reg -= 1
        else:
            self.q_reg = 0

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        if self.q_reg == q_observed:
            return True
        else:
