import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal state with 512 bits, all set to 0 initially
        self.q_reg = np.zeros(512, dtype=int)

    def load(self, signal_vector):
        # If the load signal is high, load the data into the internal state
        if signal_vector['load']:
            data = signal_vector['data']
            for i in range(512):
                # Update internal state based on input vector 'data'; assume data is an int representing 512 bits
                self.q_reg[i] = (data >> (511 - i)) & 1
        else:
            # If not loading, compute the next state based on Rule 110
            self.q_reg = self.compute_next_state(self.q_reg)

    def check(self, signal_vector):
        # Compare the internal state with the DUT output
        q_observed = signal_vector['q']
        q_expected = int(''.join(str(bit) for bit in self.q_reg), 2)  # Convert q_reg array back to integer
        if q_expected == q_observed:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={q_expected}, observed: q={q_observed}")
            return False

    def compute_next_state(self, current_state):
        next_state = np.zeros(512, dtype=int)
        for i in range(512):
            left = current_state[i - 1] if i > 0 else 0  # Boundary condition: left ghost cell
            center = current_state[i]
            right = current_state[i + 1] if i < 511 else 0  # Boundary condition: right ghost cell
            next_state[i] = self.rule_110(left, center, right)
        return next_state

    @staticmethod
    def rule_110(left, center, right):
        # Implementation of Rule 110 logic
        return (left and center and not right) or (left and not center and right) or (not left and center)

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
