        # Initialize internal state
        self.q_reg = 0x0  # 64-bit register, initially set to 0

    def load(self, signal_vector):
        # Read important signals from the signal vector
        load = signal_vector['load']
        ena = signal_vector['ena']
        amount = signal_vector['amount']
        data = signal_vector['data']

        # Perform operations based on signals
        if load:
            # Load data into register
            self.q_reg = data
        elif ena:
            # Perform shift operation based on 'amount'
            self.q_reg = self.shift(self.q_reg, amount)

    def shift(self, value, amount):
        # Perform the shift operation according to the 'amount' control signal
        if amount == 0b00:
            # Shift left by 1 bit
            return (value << 1) & 0xFFFFFFFFFFFFFFFF
        elif amount == 0b01:
            # Shift left by 8 bits
            return (value << 8) & 0xFFFFFFFFFFFFFFFF
        elif amount == 0b10:
            # Shift right by 1 bit (arithmetic)
            msb = (value & 0x8000000000000000)
            return (value >> 1) | msb
        elif amount == 0b11:
            # Corrected logic for shifting right by 8 bits (arithmetic)
            if value & 0x8000000000000000:
                # If the sign bit (MSB) is set, replicate it
                return (value >> 8) | (0xFF00000000000000)
            else:
                # If the sign bit isn't set, perform normal right shift with 0s
                return value >> 8

    def check(self, signal_vector):
        # Compare the expected output (q_reg) with the actual output from DUT
        expected_q = self.q_reg
        observed_q = signal_vector['q']

        if expected_q != observed_q:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed: q={observed_q}")
            return False
        return True
