        # Initialize state encoding
        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000
        }

    def get_expected_next_state(self, current_state, w):
        # Define state transitions based on current state and input w
        if current_state == self.states['A']:
            return self.states['B'] if w == 1 else self.states['A']
        elif current_state == self.states['B']:
            return self.states['C'] if w == 1 else self.states['D']
        elif current_state == self.states['C']:
            return self.states['E'] if w == 1 else self.states['D']
        elif current_state == self.states['D']:
            return self.states['F'] if w == 1 else self.states['A']
        elif current_state == self.states['E']:
            return self.states['E'] if w == 1 else self.states['D']
        elif current_state == self.states['F']:
            return self.states['C'] if w == 1 else self.states['D']
        else:
            raise ValueError("Invalid current state")

    def load(self, signal_vector):
        # Load input signals
        current_state = signal_vector['y']
        w = signal_vector['w']

        # Get expected next state
        expected_next_state = self.get_expected_next_state(current_state, w)
        expected_Y1 = (expected_next_state >> 1) & 0b1
        expected_Y3 = (expected_next_state >> 3) & 0b1

