class GoldenDUT:
    def __init__(self):
        # Define the state encoding using one-hot encoding
        self.STATE_A = 0b000001
        self.STATE_B = 0b000010
        self.STATE_C = 0b000100
        self.STATE_D = 0b001000
        self.STATE_E = 0b010000
        self.STATE_F = 0b100000

    def load(self, signal_vector):
        # Extract the input signals from the signal vector
        y = signal_vector.get('y', 0)
        w = signal_vector.get('w', 0)

        # Initialize the expected outputs Y1 and Y3
        Y1, Y3 = 0, 0

        # State transition logic to determine expected output values
        if y == self.STATE_A:
            if w == 1:
                Y1 = 1

        elif y == self.STATE_B:
            if w == 0:
                Y3 = 1

        elif y == self.STATE_C:
            if w == 0:
                Y3 = 1

        elif y == self.STATE_D:
            if w == 0:
                pass  # No change to Y1 or Y3

        elif y == self.STATE_E:
            if w == 0:
                Y3 = 1

        elif y == self.STATE_F:
            if w == 0:
                Y3 = 1

        return {'Y1': Y1, 'Y3': Y3}

    def check(self, signal_vector):
        # Calculate the expected output using load method
        expected_output = self.load(signal_vector)

        # Compare the expected output with the DUT's actual output
        return all(signal_vector[signal] == expected_output[signal] for signal in expected_output)

