    def __init__(self):
        # Initialize the internal state register and output q register
        self.state_reg = 0
        self.q_reg = 0

    def load(self, signal_vector):
        # Retrieve the input signals a and b
        a = signal_vector['a']
        b = signal_vector['b']

        # Logic to determine the next state and q based on inputs a and b
        if a == 0:
            if b == 1:
                # Maintain the state and q as 1 if b is 1
                self.state_reg = 1
                self.q_reg = 1
            else:
                # If both a and b are 0, reset state and q
                self.state_reg = 0
                self.q_reg = 0
        elif a == 1:
            if b == 0:
                # If b is 0, maintain q as 1 and potentially toggle state
