class GoldenDUT:
    def __init__(self):
        # Initialize any internal state if necessary
        pass

    def load(self, signal_vector):
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']

        # Compute the expected output using the corrected logical expression
        expected_q = self.ideal_dut_rule(a, b, c, d)
        return expected_q

    def check(self, signal_vector):
        expected_q = self.load(signal_vector)
        actual_q = signal_vector['q']

        # Compare the expected output with the actual DUT output
        return expected_q == actual_q

    def ideal_dut_rule(self, a, b, c, d):
        # Corrected logic: Implementing the correct logic for expected_q
        if a == 1:
            return (c | d)
        else:
            return ((b & c) | (b & d))

