        # Initialize internal state values
        self.a_reg = 0
        self.p_reg = 0
        self.q_reg = 0
        self.previous_a_reg = 0

    def load(self, signal_vector):
        # Update internal state with new input signal 'a'
        self.a_reg = signal_vector['a'] & 0b1  # Assuming 'a' is a 1-bit signal

    def check(self, signal_vector):
        # Determine expected outputs
        expected_p, expected_q = self.calculate_expected_output()

        # Retrieve actual outputs from signal vector
        p_observed = signal_vector['p']
        q_observed = signal_vector['q']

        # Compare expected and observed outputs
        if expected_p == p_observed and expected_q == q_observed:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: (p={expected_p}, q={expected_q}), "
                  f"observed: (p={p_observed}, q={q_observed})")
            return False

    def calculate_expected_output(self):
        # Logic for p_reg: Set high on rising edge (0 to 1), reset on falling edge (1 to 0)
        if self.previous_a_reg == 0 and self.a_reg == 1:
            self.p_reg = 1
        elif self.previous_a_reg == 1 and self.a_reg == 0:
            self.p_reg = 0

        # Logic for q_reg: Toggle with rising edge (0 to 1), maintain state otherwise
        if self.previous_a_reg == 0 and self.a_reg == 1:
            self.q_reg = 1 if self.q_reg == 0 else 0

        # Update previous_a_reg for the next cycle
        self.previous_a_reg = self.a_reg

        return self.p_reg, self.q_reg
