import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal register to hold the state of the 16x16 grid.
        self.q_reg = 0

    def load(self, signal_vector):
        # Update the internal state based on the load signal.
        if signal_vector['load']:
            self.q_reg = signal_vector['data']
        else:
            # Update the state for the game of life rule if not loading.
            self.q_reg = self.game_of_life_rule(self.q_reg)

    def check(self, signal_vector):
        # Determine expected output by the current internal state.
        expected_q = self.q_reg

        # Compare expected data with observed data.
        if expected_q == signal_vector['q']:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q:0256b}, observed q={signal_vector['q']:0256b}")
            return False

    def game_of_life_rule(self, current_state_vector):
        grid_size = 16
        # Convert the current state vector to a 2D numpy array.
        grid = np.array([int(bit) for bit in format(current_state_vector, '0256b')]).reshape((grid_size, grid_size))

        # Initialize the next state grid.
        next_state_grid = np.zeros((grid_size, grid_size), dtype=int)

        for row in range(grid_size):
            for col in range(grid_size):
                alive_neighbors = self.count_alive_neighbors(grid, row, col)
                # Update the cell state according to the rules of the game.
                next_state_grid[row, col] = self.update_cell_state(grid[row, col], alive_neighbors)

        # Flatten the grid and convert it to an integer for the next state vector.
        next_state_vector = int(''.join(str(bit) for bit in next_state_grid.flatten()), 2)
        return next_state_vector

    def count_alive_neighbors(self, grid, row, col):
        rows, cols = grid.shape
        # Define the position of neighbors considering toroidal wrap-around.
        neighbors = [
            ((row - 1) % rows, (col - 1) % cols), ((row - 1) % rows, col), ((row - 1) % rows, (col + 1) % cols),
            (row, (col - 1) % cols),                                   (row, (col + 1) % cols),
            ((row + 1) % rows, (col - 1) % cols), ((row + 1) % rows, col), ((row + 1) % rows, (col + 1) % cols)
        ]
        # Sum the values of neighbor cells to get the count of alive neighbors.
        return sum(grid[r, c] for r, c in neighbors)

    def update_cell_state(self, current_state, alive_neighbors):
        # Determine the next state of a cell based on its neighbor count.
        if alive_neighbors < 2 or alive_neighbors > 3:
            return 0  # The cell dies
        elif alive_neighbors == 3:
            return 1  # The cell becomes alive
        else:
            return current_state  # The cell stays the same

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

