        next_grid = np.zeros((16, 16), dtype=int)

        for x in range(16):
            for y in range(16):
                alive_neighbors = self.get_neighbors(x, y, grid)

                if alive_neighbors == 2:
                    # Rule (2): Cell state does not change.
                    next_grid[x, y] = grid[x, y]
                elif alive_neighbors == 3:
                    # Rule (3): Cell becomes alive.
                    next_grid[x, y] = 1
                else:
                    # Rule (1) and (4): Cell becomes dead.
                    next_grid[x, y] = 0

        return next_grid

    def get_neighbors(self, x, y, grid):
        """
        Function to compute the number of alive neighbors for a cell at position (x, y) in the grid.
        Handles the toroidal wraparound by using modulo operations.
        """
        size = grid.shape[0]
        neighbor_coords = [
            ((x-1) % size, (y-1) % size),
            ((x-1) % size, y),
            ((x-1) % size, (y+1) % size),
            (x, (y-1) % size),
            (x, (y+1) % size),
            ((x+1) % size, (y-1) % size),
            ((x+1) % size, y),
            ((x+1) % size, (y+1) % size),
        ]
        return sum(grid[nx, ny] for nx, ny in neighbor_coords)

