class GoldenDUT:
    def __init__(self):
        # Set initial register values
        self.hh_reg = 'x'
        self.mm_reg = 'x'
        self.ss_reg = 'x'
        self.pm_reg = 'x'

    def load(self, signal_vector):
        # Handle reset condition
        if signal_vector['reset']:
            self.hh_reg = 0x12  # 12 hours
            self.mm_reg = 0x00  # 0 minutes
            self.ss_reg = 0x00  # 0 seconds
            self.pm_reg = 0     # AM
        else:
            # Increment time if enabled
            if signal_vector['ena']:
                self.increment_time()

    def increment_time(self):
        # Increment seconds
        self.ss_reg += 1
        if self.ss_reg >= 0x60:
            self.ss_reg = 0x00
            self.mm_reg += 1  # Increment minutes if seconds roll over

        # Increment minutes
        if self.mm_reg >= 0x60:
            self.mm_reg = 0x00
            self.increment_hours()  # Increment hours if minutes roll over

    def increment_hours(self):
        # Increment hours
        if self.hh_reg == 0x11:  # Toggle PM when hour goes from 11 to 12
            self.pm_reg = 1 - self.pm_reg

        if self.hh_reg == 0x12:
            self.hh_reg = 0x01
        else:
            self.hh_reg += 1

    def check(self, signal_vector):
        # Extract observed values from signal_vector
        hh_observed = signal_vector['hh']
        mm_observed = signal_vector['mm']
        ss_observed = signal_vector['ss']
        pm_observed = signal_vector['pm']

        # Compare expected vs observed
        if (self.hh_reg != hh_observed or
            self.mm_reg != mm_observed or
            self.ss_reg != ss_observed or
            self.pm_reg != pm_observed):
            print(f"Scenario: {signal_vector['scenario']}, expected: hh={self.hh_reg}, mm={self.mm_reg}, ss={self.ss_reg}, pm={self.pm_reg}, "
                  f"observed: hh={hh_observed}, mm={mm_observed}, ss={ss_observed}, pm={pm_observed}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

