class GoldenDUT:
    def __init__(self):
        self.s_reg = 0b000  # Initial value for sensors, as all unasserted
        self.fr3_reg = 0
        self.fr2_reg = 0
        self.fr1_reg = 0
        self.dfr_reg = 0
        self.previous_sensors_reg = 0b000  # Previous state of sensors

    def load(self, signal_vector):
        if signal_vector['reset']:
            # Reset the system to initial low water level state
            self.s_reg = 0b000
            self.fr3_reg = 1
            self.fr2_reg = 1
            self.fr1_reg = 1
            self.dfr_reg = 1  # dfr should also be 1 in reset state
        else:
            self.previous_sensors_reg = self.s_reg  # Store the previous sensor state
            self.s_reg = signal_vector['s']  # Load new sensor state

            # Update flow rates based on new sensor states
            self.fr3_reg, self.fr2_reg, self.fr1_reg, self.dfr_reg = self.calculate_flow_rate(self.s_reg, self.previous_sensors_reg)

    def calculate_flow_rate(self, sensors, previous_sensors):
        sensor_3 = (sensors & 0b100) >> 2
        sensor_2 = (sensors & 0b010) >> 1
        sensor_1 = (sensors & 0b001)

        fr3, fr2, fr1, dfr = 0, 0, 0, 0

        if sensor_3 and sensor_2 and sensor_1:
            fr3, fr2, fr1, dfr = 0, 0, 0, 0
        elif sensor_2 and sensor_1 and not sensor_3:
            fr3, fr2, fr1, dfr = 0, 0, 1, self.calculate_dfr(sensors, previous_sensors)
        elif sensor_1 and not sensor_2 and not sensor_3:
            fr3, fr2, fr1, dfr = 0, 1, 1, self.calculate_dfr(sensors, previous_sensors)
        elif not sensor_3 and not sensor_2 and not sensor_1:
            fr3, fr2, fr1, dfr = 1, 1, 1, 1

        return (fr3, fr2, fr1, dfr)

    def calculate_dfr(self, sensors, previous_sensors):
        # Updated logic for determining dfr
        return self.is_transition_to_higher_level(sensors, previous_sensors)

    def is_transition_to_higher_level(self, sensors, previous_sensors):
        # Determine if there is a transition to a higher water level
