class GoldenDUT:
    def __init__(self):
        self.dff1_reg = 0
        self.dff2_reg = 0
        self.dff3_reg = 0

    def load(self, signal_vector):
        x = signal_vector['x'] & 0b1  # Ensure x is a single bit

        # Compute gate outputs based on updated flip-flop inputs
        xor_output = self.xor_gate(x, self.dff1_reg)
        and_output = self.and_gate(x, self.not_gate(self.dff2_reg))
        or_output = self.or_gate(x, self.not_gate(self.dff3_reg))

        # Update flip-flop states
        # Ensuring synchronous updates
        self.dff1_reg = xor_output
        self.dff2_reg = and_output
        self.dff3_reg = or_output

    def check(self, signal_vector):
        if signal_vector['check_en']:
            # Calculate the expected z output using current flip-flop states
            expected_z = self.xnor_gate(self.dff1_reg, self.dff2_reg, self.dff3_reg)
            observed_z = signal_vector['z']

            if expected_z == observed_z:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, expected z={expected_z}, observed z={observed_z}")
                return False

    def xor_gate(self, a, b):
        return a ^ b

    def and_gate(self, a, b):
        return a & b

    def or_gate(self, a, b):
        return a | b

    def xnor_gate(self, a, b, c):
        return ~(a ^ b ^ c) & 0b1

    def not_gate(self, a):
        return ~a & 0b1
