class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # Initial state
        self.x_reg = 0      # Input register
        self.z_reg = 0      # Output register (2's complement result)
        self.x_history = [] # To store the input history for 2's complement calculation

    def load(self, signal_vector):
        areset = signal_vector['areset']
        x = signal_vector['x']

        if areset == 1:
            # Reset state and clear history
            self.state_reg = 0
            self.x_history = []
            self.z_reg = 0
        else:
            # Load input x
            self.x_reg = x
            self.x_history.append(x)
            # Calculate the next state and output
            self.calculate_output()

    def calculate_output(self):
        # Moore state machine: output depends on the state only, not the input
        # Always calculate the 2's complement of the current x_history
        self.z_reg = self.compute_twos_complement()

    def compute_twos_complement(self):
        import numpy as np
        # Flip all bits
        flipped_bits = [1 - bit for bit in self.x_history]

        # Initialize carry for the 2's complement generation
        carry = 1

        # Convert to NumPy array for ease of addition
        flipped_bits_np = np.array(flipped_bits)

        # Add one to the flipped bits (2's complement logic)
        for i in range(len(flipped_bits_np)):
            # Add carry
            new_val = flipped_bits_np[i] + carry
            flipped_bits_np[i] = new_val % 2
            carry = new_val // 2
            # If no carry is left, we can break early
            if carry == 0:
                break

        # If there's still a carry left, we need an additional bit at the end
        if carry == 1:
            flipped_bits_np = np.append(flipped_bits_np, 1)

        # The current scenario assumes that the z output must be updated
        # In this Moore machine, we'll take the last computed bit
        if len(flipped_bits_np) > 0:
            return flipped_bits_np[-1]
        else:
            return 0

    def check(self, signal_vector):
        z_observed = signal_vector['z']
        scenario = signal_vector['scenario']
        check_en = signal_vector['check_en']

        if check_en:
            # Perform the check only when enabled
            if self.z_reg != z_observed:
                print(f"Scenario: {scenario}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

