    def load(self, signal_vector):
        if signal_vector['areset'] == 1:
            self.reset_active = True
            self.a_reg = 0
            self.input_sequence = ''
            self.output_reg = ''
        else:
            if self.reset_active:
                # Start conversion when reset is released
                self.reset_active = False
                self.a_reg = signal_vector['x']
            else:
                # Continue to build the input sequence
                self.input_sequence += str(signal_vector['x'])

            # Update the output register after processing the current input
            self.output_reg = self.twos_complement(self.input_sequence)

    def check(self, signal_vector):
        expected_z = 0 if self.reset_active else int(self.output_reg[-1])

        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if expected_z != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={z_observed}")
                return False
        return True

    def twos_complement(self, binary_sequence):
        n = len(binary_sequence)
        result = ['0'] * n
        first_one_found = False

        for i in range(n):
            bit = int(binary_sequence[i])
            if bit == 1:
                first_one_found = True

            if first_one_found:
                result[i] = str(1 - bit)
            else:
                result[i] = str(bit)

        return ''.join(result)

