class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.x_reg = 0
        self.z_reg = 0
        self.input_sequence = []
        self.expected_output = []
        self.areset_reg = 1

    def load(self, signal_vector):
        # Load signals and update internal states
        if signal_vector['areset'] == 0:
            self.x_reg = signal_vector['x']
            self.input_sequence.append(self.x_reg)
            self.z_reg = self.calculate_current_output()
            self.expected_output.append(self.z_reg)
        else:
            self.reset()

    def check(self, signal_vector):
        # Check output when check_en is true
        if signal_vector['check_en']:
            z_observed = signal_vector['z']
            if self.z_reg != z_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: z={self.z_reg}, observed z={z_observed}")
                return False
        return True

    def calculate_current_output(self):
        # Calculate 2's complement of input sequence
        if not self.input_sequence:
            return 0  # Handle case where no input has been loaded

        inverted_bits = [1 - bit for bit in self.input_sequence]
        n = len(inverted_bits)
        carry = 1
        twos_complement_bits = inverted_bits.copy()

        for i in range(n):
            if inverted_bits[i] == 1 and carry == 1:
                twos_complement_bits[i] = 0
                carry = 1
            elif inverted_bits[i] == 0 and carry == 1:
                twos_complement_bits[i] = 1
                carry = 0
            else:
                twos_complement_bits[i] = inverted_bits[i]

        # Ensure return of the correct bit related to current processing state
        return twos_complement_bits[-1]  # Return the most recent bit processed as output

    def reset(self):
        # Reset internal states
        self.x_reg = 0
        self.z_reg = 0
        self.input_sequence = []
        self.expected_output = []
        self.areset_reg = 1
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

