class GoldenDUT:
    def __init__(self):
        # Define state encoding as per one-hot encoding
        self.states = {
            'S0': 0b0000000001,
            'S1': 0b0000000010,
            'S2': 0b0000000100,
            'S3': 0b0000001000,
            'S4': 0b0000010000,
            'S5': 0b0000100000,
            'S6': 0b0001000000,
            'S7': 0b0010000000,
            'S8': 0b0100000000,
            'S9': 0b1000000000
        }

    def load(self, signal_vector):
        # Extract input and current state
        input_signal = signal_vector['in']
        current_state = signal_vector['state']

        # Compute expected next state and outputs
        next_state, out1, out2 = self.get_next_state_and_outputs(current_state, input_signal)

        return {'next_state': next_state, 'out1': out1, 'out2': out2}

    def check(self, signal_vector):
        # Get expected outputs and next state
        expected = self.load(signal_vector)

        # Compare with DUT outputs
        return (expected['next_state'] == signal_vector['next_state'] and
                expected['out1'] == signal_vector['out1'] and
                expected['out2'] == signal_vector['out2'])

    def get_next_state_and_outputs(self, current_state, input_signal):
        out1, out2 = 0, 0

        if current_state == self.states['S0']:
            next_state = self.states['S1'] if input_signal else self.states['S0']
        elif current_state == self.states['S1']:
            next_state = self.states['S2'] if input_signal else self.states['S0']
        elif current_state == self.states['S2']:
            next_state = self.states['S3'] if input_signal else self.states['S0']
        elif current_state == self.states['S3']:
            next_state = self.states['S4'] if input_signal else self.states['S0']
        elif current_state == self.states['S4']:
            next_state = self.states['S5'] if input_signal else self.states['S0']
        elif current_state == self.states['S5']:
            next_state = self.states['S6'] if input_signal else self.states['S8']
        elif current_state == self.states['S6']:
            next_state = self.states['S7'] if input_signal else self.states['S9']
        elif current_state == self.states['S7']:
            out2 = 1
            next_state = self.states['S7'] if input_signal else self.states['S0']
        elif current_state == self.states['S8']:
            out1 = 1
            next_state = self.states['S1'] if input_signal else self.states['S0']
        elif current_state == self.states['S9']:
            out1 = 1
            out2 = 1
            next_state = self.states['S1'] if input_signal else self.states['S0']
        else:
            next_state = self.states['S0']

        return next_state, out1, out2

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

