class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'
        self.byte_count_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0

    def load(self, signal_vector):
        in_value = signal_vector['in'] & 0xFF  # Ensure 8-bit input
        reset = signal_vector['reset']

        if reset:
            self.reset_registers()
            return

        if self.state_reg == 'IDLE':
            if in_value & 0x08:  # Check if in[3] == 1
                self.state_reg = 'RECEIVING'
                self.byte_count_reg = 1
                self.message_reg[0] = in_value
            self.done_reg = 0

        elif self.state_reg == 'RECEIVING':
            if in_value & 0x08 and self.byte_count_reg == 0:  # New valid message start without completing the previous
                # This condition should strictly handle only the start of a new message
                self.state_reg = 'RECEIVING'
                self.byte_count_reg = 1
                self.message_reg = [in_value, 0, 0]
            elif self.byte_count_reg == 1:
                self.message_reg[1] = in_value
                self.byte_count_reg += 1
            elif self.byte_count_reg == 2:
                self.message_reg[2] = in_value
                self.byte_count_reg += 1
                self.done_reg = 1
                self.out_bytes_reg = (self.message_reg[0] << 16) | (self.message_reg[1] << 8) | self.message_reg[2]
                self.state_reg = 'IDLE'  # Correct transition to handle end of message
            else:
                self.done_reg = 0

    def check(self, signal_vector):
        if signal_vector['check_en']:
            done_observed = signal_vector['done']
            out_bytes_observed = signal_vector['out_bytes']

            if self.done_reg != done_observed or self.out_bytes_reg != out_bytes_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected done={self.done_reg}, observed done={done_observed}")
                print(f"Scenario: {signal_vector['scenario']}, expected out_bytes={hex(self.out_bytes_reg)}, observed out_bytes={hex(out_bytes_observed)}")
                return False

        return True

    def reset_registers(self):
        self.state_reg = 'IDLE'
        self.byte_count_reg = 0
        self.message_reg = [0, 0, 0]
        self.done_reg = 0
        self.out_bytes_reg = 0
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

