class GoldenDUT:
    def __init__(self):
        self.state_reg = "IDLE"
        self.data_bits_reg = []
        self.out_byte_reg = 0
        self.done_reg = 0

    def load(self, signal_vector):
        if signal_vector['reset'] == 1:
            # Ensure all registers are properly reset
            self.state_reg = "IDLE"
            self.data_bits_reg = []
            self.out_byte_reg = 0
            self.done_reg = 0
        else:
            # Process the input bit only if reset is not high
            self.process_input(signal_vector['in'])

    def process_input(self, bit):
        if self.state_reg == "IDLE":
            # Transition to START state only on detecting start bit
            if bit == 0:
                self.state_reg = "START"
                self.data_bits_reg = []
        elif self.state_reg == "START":
            self.data_bits_reg.append(bit)
            # Ensure transition only after 8 bits
            if len(self.data_bits_reg) == 8:
                self.state_reg = "DATA"
        elif self.state_reg == "DATA":
            # Expect stop bit (1) to confirm byte reception
            if bit == 1:
                # Convert data bits from LSB-first format
                self.out_byte_reg = int("".join(map(str, self.data_bits_reg[::-1])), 2)
                self.done_reg = 1
                self.state_reg = "IDLE"
            else:
                # Incorrect stop bit handling
                self.state_reg = "WAIT_STOP_BIT"
        elif self.state_reg == "WAIT_STOP_BIT":
            # Wait until a correct stop bit is seen before idling
            if bit == 1:
                self.state_reg = "IDLE"
                self.done_reg = 0

    def check(self, signal_vector):
        # Ensure the check compares the expected and observed output
        if signal_vector['done'] != self.done_reg or signal_vector['out_byte'] != self.out_byte_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.out_byte_reg}, done={self.done_reg}, observed: out_byte={signal_vector['out_byte']}, done={signal_vector['done']}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

