class GoldenDUT:
    def __init__(self):
        # Initialize registers and states
        self.state_reg = 'IDLE'
        self.data_bits_counter_reg = 0
        self.received_byte_reg = 0
        self.out_byte_reg = 0
        self.done_reg = 0
        self.previous_done_reg = 0  # For tracking the previous state of done

    def load(self, signal_vector):
        in_bit = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            # Reset internal states and counters
            self.state_reg = 'IDLE'
            self.data_bits_counter_reg = 0
            self.received_byte_reg = 0
            self.out_byte_reg = 0
            self.done_reg = 0
        else:
            # FSM transitions
            if self.state_reg == 'IDLE':
                if in_bit == 0:
                    self.state_reg = 'START'
                    self.received_byte_reg = 0
                    self.data_bits_counter_reg = 0
            elif self.state_reg == 'START':
                self.state_reg = 'DATA_BITS'
            elif self.state_reg == 'DATA_BITS':
                # Shift in the least significant bit first
                self.received_byte_reg = (self.received_byte_reg >> 1) | (in_bit << 7)
                self.data_bits_counter_reg += 1
                if self.data_bits_counter_reg == 8:
                    self.state_reg = 'STOP'
            elif self.state_reg == 'STOP':
                if in_bit == 1:
                    self.out_byte_reg = self.received_byte_reg
                    self.done_reg = 1  # Set done high once a correct stop bit is detected
                    self.state_reg = 'IDLE'  # Transition to IDLE on correct stop
                else:
                    self.state_reg = 'INVALID'  # Move to INVALID if stop bit is incorrect
            elif self.state_reg == 'INVALID':
                if in_bit == 1:
                    self.state_reg = 'IDLE'  # Return to IDLE upon seeing a valid stop bit

            # Maintain 'done' high for exactly one cycle
            if self.done_reg == 1:
                self.previous_done_reg = 1
                self.done_reg = 0
            else:
                self.previous_done_reg = 0

    def check(self, signal_vector):
        out_byte_observed = signal_vector['out_byte']
        done_observed = signal_vector['done']

        if signal_vector['check_en']:
            if (self.out_byte_reg != out_byte_observed) or (self.previous_done_reg != done_observed):
                print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={self.out_byte_reg}, done={self.previous_done_reg}, observed: out_byte={out_byte_observed}, done={done_observed}")
                return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

