class GoldenDUT:
    def __init__(self):
        self.state_reg = 'IDLE'  # Possible states: 'IDLE', 'RECEIVE', 'CHECK'
        self.data_bits_reg = [0] * 8  # Data bits storage
        self.bit_counter_reg = 0  # Counter for bits received
        self.out_byte_reg = 0  # Storage for the constructed byte
        self.done_reg = 0  # Done signal

    def load(self, signal_vector):
        in_bit = signal_vector['in']
        reset = signal_vector['reset']

        if reset:
            self.__init__()  # Reset to initial conditions
            return

        if self.state_reg == 'IDLE':
            if in_bit == 0:  # Start bit detected
                self.state_reg = 'RECEIVE'
                self.bit_counter_reg = 0
                self.done_reg = 0

        elif self.state_reg == 'RECEIVE':
            if self.bit_counter_reg < 8:
                self.data_bits_reg[self.bit_counter_reg] = in_bit
                self.bit_counter_reg += 1
            else:  # Expecting stop bit
                if in_bit == 1:  # Valid stop bit
                    self.state_reg = 'CHECK'
                else:
                    # Invalid stop bit, reset state to IDLE
                    self.__init__()  # Reset all to initial conditions

        elif self.state_reg == 'CHECK':
            self.out_byte_reg = self.__construct_byte()
            self.done_reg = 1
            self.state_reg = 'IDLE'  # Reset to IDLE to await the next byte

    def check(self, signal_vector):
        if signal_vector['check_en']:
            expected_out_byte = self.out_byte_reg
            expected_done = self.done_reg
            observed_out_byte = signal_vector['out_byte']
            observed_done = signal_vector['done']

            if expected_out_byte == observed_out_byte and expected_done == observed_done:
                return True
            else:
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: out_byte={expected_out_byte}, done={expected_done}, "
                      f"observed: out_byte={observed_out_byte}, done={observed_done}")
                return False
        return True

    def __construct_byte(self):
        received_byte = 0
        for i, bit in enumerate(self.data_bits_reg):
            received_byte |= (bit << i)  # LSB is first, shift left as i increases
        return received_byte
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

