class GoldenDUT:
    def __init__(self):
        # Initialize any states if needed, though for a combinational circuit this is typically minimal
        pass

    def load(self, signal_vector):
        # Extract input signals from the signal vector
        a = int(signal_vector['a'])
        b = int(signal_vector['b'])
        c = int(signal_vector['c'])
        d = int(signal_vector['d'])

        # Compute and return the expected output
        return self._karnaugh_map_output(a, b, c, d)

    def check(self, signal_vector):
        # Handle non-integer 'out' value in signal_vector
        try:
            expected_out = self.load(signal_vector)
            actual_out = int(signal_vector['out'])
        except ValueError:
            return False

        # Compare expected output with actual DUT output
        return expected_out == actual_out

    def _karnaugh_map_output(self, a, b, c, d):
        # Convert inputs to integers for easier indexing
        ab = (a << 1) | b
        cd = (c << 1) | d

        # Corrected Karnaugh map to reflect the problem description
        k_map = [
            [0, 1, 0, 1],  # cd == 00
            [1, 0, 1, 0],  # cd == 01
            [0, 1, 0, 1],  # cd == 11
            [1, 0, 1, 0]   # cd == 10
        ]

        # Return the expected output from the Karnaugh map
        return k_map[cd][ab]
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

