class GoldenDUT:

    WALK_LEFT = 0b001
    WALK_RIGHT = 0b010
    FALLING = 0b100

    def __init__(self):
        self.current_state_reg = self.WALK_LEFT
        self.previous_state_reg = self.WALK_LEFT
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']

        if areset:
            self.current_state_reg = self.WALK_LEFT
            self.walk_left_reg = 1
            self.walk_right_reg = 0
            self.aaah_reg = 0
        else:
            if self.current_state_reg == self.FALLING:
                if ground == 1:
                    # Resume walking in the previous direction
                    self.current_state_reg = self.previous_state_reg
            elif ground == 0:
                # Save the current state as previous before falling
                self.previous_state_reg = self.current_state_reg
                self.current_state_reg = self.FALLING
            elif bump_left == 1 and bump_right == 0:
                self.current_state_reg = self.WALK_RIGHT  # Only bump on the left
            elif bump_right == 1 and bump_left == 0:
                self.current_state_reg = self.WALK_LEFT  # Only bump on the right
            elif bump_left == 1 and bump_right == 1:
                # Change direction when bumped on both sides
                self.current_state_reg = (
                    self.WALK_RIGHT if self.current_state_reg == self.WALK_LEFT else self.WALK_LEFT
                )

        self.walk_left_reg = int(self.current_state_reg == self.WALK_LEFT)
        self.walk_right_reg = int(self.current_state_reg == self.WALK_RIGHT)
        self.aaah_reg = int(self.current_state_reg == self.FALLING)

    def check(self, signal_vector):
        expected_walk_left = self.walk_left_reg
        expected_walk_right = self.walk_right_reg
        expected_aaah = self.aaah_reg

        walk_left_observed = signal_vector['walk_left']
        walk_right_observed = signal_vector['walk_right']
        aaah_observed = signal_vector['aaah']

        if (expected_walk_left == walk_left_observed and
            expected_walk_right == walk_right_observed and
            expected_aaah == aaah_observed):
            return True
        else:
            scenario = signal_vector['scenario']
            print(f"Scenario: {scenario}, expected: walk_left={expected_walk_left}, observed walk_left={walk_left_observed}")
            print(f"Scenario: {scenario}, expected: walk_right={expected_walk_right}, observed walk_right={walk_right_observed}")
            print(f"Scenario: {scenario}, expected: aaah={expected_aaah}, observed aaah={aaah_observed}")
            return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

