class GoldenDUT:
    def __init__(self):
        # State encoding
        self.WALK_LEFT = 0b0001
        self.WALK_RIGHT = 0b0010
        self.FALLING = 0b0100
        self.DIGGING = 0b1000

        # Initial state and previous direction
        self.current_state_reg = self.WALK_LEFT
        self.previous_direction_reg = self.WALK_LEFT
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        # Handle asynchronous reset
        if areset == 1:
            self.current_state_reg = self.WALK_LEFT
            self.previous_direction_reg = self.WALK_LEFT
        else:
            if self.current_state_reg == self.WALK_LEFT:
                if ground == 0:
                    self.current_state_reg = self.FALLING
                elif dig == 1 and ground == 1:
                    self.current_state_reg = self.DIGGING
                elif bump_left == 1 or (bump_left == 1 and bump_right == 1):
                    self.current_state_reg = self.WALK_RIGHT

            elif self.current_state_reg == self.WALK_RIGHT:
                if ground == 0:
                    self.current_state_reg = self.FALLING
                elif dig == 1 and ground == 1:
                    self.current_state_reg = self.DIGGING
                elif bump_right == 1 or (bump_left == 1 and bump_right == 1):
                    self.current_state_reg = self.WALK_LEFT

            elif self.current_state_reg == self.FALLING:
                if ground == 1:
                    self.current_state_reg = self.previous_direction_reg

            elif self.current_state_reg == self.DIGGING:
                if ground == 0:
                    self.current_state_reg = self.FALLING

            if self.current_state_reg == self.WALK_LEFT or self.current_state_reg == self.WALK_RIGHT:
                self.previous_direction_reg = self.current_state_reg

        # Update output registers based on the current state
        self.walk_left_reg = int(self.current_state_reg == self.WALK_LEFT)
        self.walk_right_reg = int(self.current_state_reg == self.WALK_RIGHT)
        self.aaah_reg = int(self.current_state_reg == self.FALLING)
        self.digging_reg = int(self.current_state_reg == self.DIGGING)

    def check(self, signal_vector):
        if signal_vector['check_en']:
            walk_left_observed = signal_vector['walk_left']
            walk_right_observed = signal_vector['walk_right']
            aaah_observed = signal_vector['aaah']
            digging_observed = signal_vector['digging']

            if (walk_left_observed != self.walk_left_reg or
                walk_right_observed != self.walk_right_reg or
                aaah_observed != self.aaah_reg or
                digging_observed != self.digging_reg):
                print(f"Scenario: {signal_vector['scenario']}, "
                      f"expected: walk_left={self.walk_left_reg}, walk_right={self.walk_right_reg}, "
                      f"aaah={self.aaah_reg}, digging={self.digging_reg}; "
                      f"observed: walk_left={walk_left_observed}, walk_right={walk_right_observed}, "
                      f"aaah={aaah_observed}, digging={digging_observed}")
                return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

