class GoldenDUT:
    # Constants for state and actions
    STATE_WALK_LEFT = 0
    STATE_WALK_RIGHT = 1
    STATE_FALL = 2
    STATE_DIG = 3
    STATE_SPLATTER = 4

    def __init__(self):
        self.state_reg = self.STATE_WALK_LEFT  # Initial state
        self.fall_time_reg = 0  # Time spent falling
        self.walk_left_reg = 0
        self.walk_right_reg = 0
        self.aaah_reg = 0
        self.digging_reg = 0

    def load(self, signal_vector):
        areset = signal_vector['areset']
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        if areset:
            self.state_reg = self.STATE_WALK_LEFT
            self.fall_time_reg = 0
            self.update_outputs()
            return

        if self.state_reg == self.STATE_FALL:
            self.fall_time_reg += 1
            if self.fall_time_reg > 20 and ground == 1:
                self.state_reg = self.STATE_SPLATTER
                self.update_outputs()
                return

        if self.state_reg == self.STATE_SPLATTER:
            self.update_outputs()
            return

        if ground == 0:
            self.state_reg = self.STATE_FALL
        elif dig and ground == 1 and self.state_reg != self.STATE_FALL:
            self.state_reg = self.STATE_DIG
        elif bump_left or bump_right:
            if self.state_reg == self.STATE_WALK_LEFT:
                self.state_reg = self.STATE_WALK_RIGHT
            elif self.state_reg == self.STATE_WALK_RIGHT:
                self.state_reg = self.STATE_WALK_LEFT

        self.update_outputs()

    def update_outputs(self):
        if self.state_reg == self.STATE_WALK_LEFT:
            self.walk_left_reg = 1
            self.walk_right_reg = 0
            self.aaah_reg = 0
            self.digging_reg = 0
        elif self.state_reg == self.STATE_WALK_RIGHT:
            self.walk_left_reg = 0
            self.walk_right_reg = 1
            self.aaah_reg = 0
            self.digging_reg = 0
        elif self.state_reg == self.STATE_FALL:
