class GoldenDUT:
    def __init__(self):
        # State encoding using one-hot representation
        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000
        }

    def _next_state(self, current_state, w):
        # Determine next state based on current state and input w
        if current_state == self.states['A']:
            return self.states['B'] if w == 0 else self.states['A']
        elif current_state == self.states['B']:
            return self.states['C'] if w == 0 else self.states['D']
        elif current_state == self.states['C']:
            return self.states['E'] if w == 0 else self.states['D']
        elif current_state == self.states['D']:
            return self.states['F'] if w == 0 else self.states['A']
        elif current_state == self.states['E']:
            return self.states['E'] if w == 0 else self.states['D']
        elif current_state == self.states['F']:
            return self.states['C'] if w == 0 else self.states['D']

        # If no valid condition is met, return None
        return None

    def load(self, signal_vector):
        y = signal_vector['y']
        w = signal_vector['w']

        # Calculate the expected next state using the loaded signal vector
        expected_state = self._next_state(current_state=y, w=w)

        # Return expected next state outputs, Y2 and Y4
        Y2 = (expected_state & 0b000010) >> 1
        Y4 = (expected_state & 0b001000) >> 3
        return {'Y2': Y2, 'Y4': Y4}

    def check(self, signal_vector):
        # Load the expected values
        expected_outputs = self.load(signal_vector)

        # Compare DUT output against the expected outputs using the signal vector
        return (expected_outputs['Y2'] == signal_vector['Y2']) and (expected_outputs['Y4'] == signal_vector['Y4'])

