class GoldenDUT:
    def __init__(self):
        # Define state encodings
        self.STATE_A = 0b000001
        self.STATE_B = 0b000010
        self.STATE_C = 0b000100
        self.STATE_D = 0b001000
        self.STATE_E = 0b010000
        self.STATE_F = 0b100000

    def load(self, signal_vector):
        # Extract input signals from signal vector
        y = signal_vector['y']
        w = signal_vector['w']

        # Calculate expected outputs based on state transition rules
        Y2, Y4 = self.calculate_next_state_outputs(y, w)
        return Y2, Y4

    def check(self, signal_vector):
        # Load the expected output values
        expected_Y2, expected_Y4 = self.load(signal_vector)

        # Compare with actual DUT outputs
        actual_Y2 = signal_vector['Y2']
        actual_Y4 = signal_vector['Y4']

        # Return True if DUT outputs match expected outputs, False otherwise
        return (expected_Y2 == actual_Y2) and (expected_Y4 == actual_Y4)

    def calculate_next_state_outputs(self, y, w):
        # Compute next state based on current state and input w
        if y == self.STATE_A:
            next_y = self.STATE_B if w == 0 else self.STATE_A
        elif y == self.STATE_B:
            next_y = self.STATE_C if w == 0 else self.STATE_D
        elif y == self.STATE_C:
            next_y = self.STATE_E if w == 0 else self.STATE_D
        elif y == self.STATE_D:
            next_y = self.STATE_F if w == 0 else self.STATE_A
        elif y == self.STATE_E:
            next_y = self.STATE_E if w == 0 else self.STATE_D
        elif y == self.STATE_F:
            next_y = self.STATE_C if w == 0 else self.STATE_D
        else:
            raise ValueError("Invalid state encoding: {}".format(y))

        # Determine Y2 and Y4 from next state
        Y2 = bool(next_y & 0b000010)  # Check if Y2 (state B) is set
        Y4 = bool(next_y & 0b001000)  # Check if Y4 (state D) is set

        return Y2, Y4

