class GoldenDUT:
    def __init__(self):
        # Initialize internal state with '0', assuming 3-bit state representations
        self.q_reg = 0b000

    def load(self, signal_vector):
        # Load input signals and update internal state
        L = signal_vector['L']
        r_in = signal_vector['r_in']

        if L:
            # Load r_in into q_reg if L is high
            self.q_reg = r_in & 0b111  # Ensure it's a 3-bit value
        else:
            # Perform cyclic shift and XOR operation if L is low
            q0, q1, q2 = (self.q_reg >> 0) & 1, (self.q_reg >> 1) & 1, (self.q_reg >> 2) & 1
            self.q_reg = ((q1 ^ q2) << 2) | (q0 << 1) | q2
            # Mask to ensure 3-bit width
            self.q_reg &= 0b111

    def expected_output(self):
        # Return q_reg directly since it holds the current expected state 
        return self.q_reg

    def check(self, signal_vector):
        # Get the observed output from the DUT
        Q_observed = signal_vector['Q']

        # Compute expected output based on internal state
        if signal_vector['L']:
            expected_q = signal_vector['r_in'] & 0b111  # Mask to ensure 3-bit width
        else:
            expected_q = self.expected_output()

        # Compare the expected output with the observed output
        if expected_q == Q_observed:
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected Q: {expected_q}, observed Q: {Q_observed}")
            return False
