class GoldenDUT:
    def __init__(self):
        self.state_reg = 'search'
        self.delay_reg = 0
        self.countdown_reg = 0
        self.data_shift_reg = ''
        self.counting_reg = 0
        self.done_reg = 0
        self.count_reg = 0

    def load(self, signal_vector):
        reset = signal_vector['reset']
        data = signal_vector['data']
        ack = signal_vector['ack']

        # Synchronous reset logic
        if reset:
            self.__init__()  # Reset all state variables
            return

        # State machine logic
        if self.state_reg == 'search':
            self.done_reg = 0
            self.counting_reg = 0
            self.data_shift_reg = (self.data_shift_reg + str(data))[-4:]  # Shift data
            if self.data_shift_reg == '1101':
                self.state_reg = 'load_delay'
                self.data_shift_reg = ''  # Reset shift register for reading delay next

        elif self.state_reg == 'load_delay':
            self.data_shift_reg += str(data)
            if len(self.data_shift_reg) == 4:
                self.delay_reg = int(self.data_shift_reg, 2)
                self.countdown_reg = (self.delay_reg + 1) * 1000
                self.state_reg = 'count'
                self.data_shift_reg = ''  # Clean for next use

        elif self.state_reg == 'count':
            self.handle_countdown()

        elif self.state_reg == 'wait_ack':
            if ack:
                self.state_reg = 'search'
                self.done_reg = 0

    def handle_countdown(self):
        # Separate method to manage countdown operations cleanly
        if self.countdown_reg > 0:
            self.counting_reg = 1
            self.count_reg = (self.countdown_reg - 1) // 1000  # Calculate per 1000 cycles
            self.countdown_reg -= 1
        else:
            self.done_reg = 1
            self.counting_reg = 0
            self.state_reg = 'wait_ack'

    def check(self, signal_vector):
        expected_count = self.count_reg
        expected_done = self.done_reg
        observed_count = signal_vector['count']
        observed_done = signal_vector['done']

        if expected_count != observed_count:
            print(f"Scenario: {signal_vector['scenario']}, expected count: {expected_count}, observed count: {observed_count}")
            return False

        if expected_done != observed_done:
            print(f"Scenario: {signal_vector['scenario']}, expected done: {expected_done}, observed done: {observed_done}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

