import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the internal register state with zeros
        self.q_reg = np.zeros(512, dtype=int)

    def load(self, signal_vector):
        if signal_vector['load']:
            data = signal_vector['data']
            # Ensure that data is treated correctly as a 512-bit binary regardless of its integer value
            self.q_reg = np.array(list(map(int, format(data, '0512b'))))
        else:
            # Perform Rule 110 transition if not in load mode
            self.q_reg = self.perform_rule_110(self.q_reg)

    def check(self, signal_vector):
        q_observed = signal_vector['q']
        q_expected = self.q_reg

        # Compare expected and observed outputs
        if np.array_equal(q_expected, q_observed):
            return True
        else:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={q_expected}, observed: q={q_observed}")
            return False

    def rule_110_transition(self, left, center, right):
        # Implement the transition logic for Rule 110
        if (left, center, right) == (1, 1, 1):
            return 0
        elif (left, center, right) == (1, 1, 0):
            return 1
        elif (left, center, right) == (1, 0, 1):
            return 1
        elif (left, center, right) == (1, 0, 0):
            return 0
        elif (left, center, right) == (0, 1, 1):
            return 1
        elif (left, center, right) == (0, 1, 0):
            return 1
        elif (left, center, right) == (0, 0, 1):
            return 1
        elif (left, center, right) == (0, 0, 0):
            return 0

    def perform_rule_110(self, q):
        new_q = np.zeros(512, dtype=int)
        for i in range(512):
            # Boundary treatment: left and right bounds are 0
            left = q[i-1] if i > 0 else 0  # Treat boundary as 0
            center = q[i]
            right = q[i+1] if i < 511 else 0  # Treat boundary as 0
            new_q[i] = self.rule_110_transition(left, center, right)
        return new_q
