    def __init__(self):
        self.resetn_reg = 1  # initial state: resetn is de-asserted
        self.x_reg = 0
        self.y_reg = 0
        self.f_reg = 0
        self.g_reg = 0
        self.clk_cycle = 0
        self.x_sequence = []  # Track x input sequence for g condition

    def load(self, signal_vector):
        self.clk_cycle += 1
        self.resetn_reg = signal_vector['resetn']
        self.x_reg = signal_vector['x']
        self.y_reg = signal_vector['y']

        if self.resetn_reg == 0:
            self.f_reg = 0
            self.g_reg = 0
            self.x_sequence = []  # Reset sequence on reset
            return

        # State behavior after resetn is de-asserted
        if self.clk_cycle == 3:
            self.f_reg = 1

        if self.clk_cycle == 4:
            self.f_reg = 0

        # Monitoring x input for g condition
        if self.clk_cycle in {5, 6, 7}:
            self.x_sequence.append(self.x_reg)
            if len(self.x_sequence) > 3:
                self.x_sequence.pop(0)

            if len(self.x_sequence) == 3 and self.x_sequence == [1, 0, 1]:
                self.g_reg = 1

        # Monitoring y input after g being set to 1
        if self.g_reg == 1:
            if self.clk_cycle >= 9:
                if self.clk_cycle == 9 and self.y_reg == 0:
                    pass  # y is 0
                elif self.clk_cycle == 10 and self.y_reg == 1:
                    self.g_reg = 1  # y becomes 1, g remains 1
                elif self.clk_cycle >= 16:
                    # Allowing 3 clock cycles before allowing g to be set to 0
                    if self.clk_cycle - 16 > 2:
                        self.g_reg = 0

    def check(self, signal_vector):
        expected_f = self.f_reg
        expected_g = self.g_reg
        observed_f = signal_vector['f']
        observed_g = signal_vector['g']

        if expected_f != observed_f:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, observed f={observed_f}")
            return False

        if expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={expected_g}, observed g={observed_g}")
