class GoldenDUT:
    def __init__(self):
        # Initialize internal registers
        self.f_reg = 0
        self.g_reg = 0
        self.x_seq = []
        self.y_seq = []
        self.reset_active = True

    def load(self, signal_vector):
        # Load the input signals
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        # Update the reset status
        if resetn == 0:
            self.reset_active = True
            self.f_reg = 0
            self.g_reg = 0
            self.x_seq.clear()
            self.y_seq.clear()
        else:
            self.reset_active = False

            # Step according to FSM logic
            if not self.reset_active:
                # When the reset is de-asserted
                if self.f_reg == 0:  # First clock cycle after reset
                    self.f_reg = 1
                elif self.f_reg == 1:
                    # Maintain f at 1 for only one clock cycle
                    self.f_reg = 0 

                # Update x sequence
                self.x_seq.append(x)
                if len(self.x_seq) > 3:
                    self.x_seq.pop(0)  # Maintain only last three values

                # Detect sequence 1, 0, 1
                if len(self.x_seq) == 3 and self.x_seq == [1, 0, 1]:
                    self.g_reg = 1  # Set g to 1 after detecting sequence

                # Monitor y signal
                self.y_seq.append(y)
                if len(self.y_seq) > 2:
                    self.y_seq.pop(0)  # Maintain only last two values

                # Check if g should remain high or go low
                if self.g_reg == 1:
                    if 1 in self.y_seq:
                        self.g_reg = 1  # Keep g high if y is detected
                    elif len(self.y_seq) == 2 and self.y_seq[-2:] == [0, 0]:
                        self.g_reg = 0  # Lower g if condition is met
                else:
                    # If g is not yet activated, check if we have seen the valid sequence in x
                    if len(self.x_seq) < 3 or self.x_seq != [1, 0, 1]:
                        self.g_reg = 0  # Ensure g is low until valid sequence is seen

    def check(self, signal_vector):
        expected_f, expected_g = self.calculate_expected_output(signal_vector)
        observed_f = signal_vector['f']
        observed_g = signal_vector['g']

        if expected_f != observed_f or expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, observed f={observed_f}, expected: g={expected_g}, observed g={observed_g}")
            return False
        return True

    def calculate_expected_output(self, signal_vector):
        resetn = signal_vector['resetn']
        f = 0
        g = 0

        if resetn == 0:
            return (0, 0)  # Both outputs are low when reset is asserted

        if self.reset_active == False and self.f_reg == 1:
            f = 1  # f should be high

        # Check the state of the x sequence
        if len(self.x_seq) == 3 and self.x_seq == [1, 0, 1]:
            g = 1  # g should become high after valid sequence

        # Handle the y sequence for the output g
        if g == 1:
            if len(self.y_seq) > 0 and self.y_seq[-1] == 1:
                g = 1  # g remains high if y is detected
            elif len(self.y_seq) == 2 and self.y_seq[-2:] == [0, 0]:
                g = 0  # g goes low if y is not detected in two cycles

        return (f, g)
