    def __init__(self):
        self.input_signal_key = 'in'  # key for input signal
        self.output_signal_key = 'pos'  # key for output signal

    def load(self, signal_vector):
        input_value = signal_vector[self.input_signal_key]
        expected_output = self.priority_encoder(input_value)
        return expected_output

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        # Fetch the DUT output from the signal_vector
        dut_output = signal_vector.get(self.output_signal_key, None)
        return expected_output == dut_output

    def priority_encoder(self, input_vector):
        # Find position of the least significant bit that is high
        if input_vector == 0:
            return 0b000  # return 0b000 if no bits are high

        # Loop through bits to find the first active bit
        for i in range(8):
            if input_vector & (1 << i):
                return i  # return index of the first active bit

        return 0b000  # return 0b000 if no active bits found

