class GoldenDUT:
    def __init__(self):
        self.a_reg = 0  # Represents the input signal 'a'
        self.q_reg = 0  # Represents the output signal 'q'
        self.previous_a = None  # To track the previous value of 'a'
        self.previous_q = 0  # To track the previous value of 'q'
        self.a_count = 0  # Counter for how many consecutive clock cycles 'a' has been 1

    def load(self, signal_vector):
        self.a_reg = signal_vector['a']
        if self.a_reg == 1:
            self.a_count += 1  # Increment the count when 'a' is 1
        else:
            self.a_count = 0  # Reset count when 'a' is 0

    def check(self, signal_vector):
        expected_q = self.ideal_dut_rules(self.a_reg)

        if expected_q != signal_vector['q']:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={signal_vector['q']}")
            return False
        return True

    def ideal_dut_rules(self, a):
        clk = 1  # Simulating positive clock edge

        if clk == 1:
            if a == 0:
                if self.previous_a is None or self.previous_a == 0:
                    self.q_reg = 1  # At the positive edge with a=0, load q with 1
                else:
                    self.q_reg = self.previous_q  # Hold previous value if 'a' was 1 before
            else:  # a == 1
                if self.a_count < 3:  # If 'a' has been high less than 3 cycles
                    self.q_reg = 1  # Maintain output q as 1
                else:
                    self.q_reg = 0  # After sustaining a=1 for 3 cycles, bring q to 0
        else:
            self.q_reg = self.previous_q  # During clock low, hold previous value of q

        self.previous_a = a
        self.previous_q = self.q_reg

        return self.q_reg
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
