        expected_state = self.expected_output(load=False, data=self.data_reg)
        observed_state = signal_vector['q']

        if not np.array_equal(expected_state, observed_state):
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_state}, observed q={observed_state}")
            return False
        return True

    def expected_output(self, load, data):
        grid = np.array([int(bit) for bit in f"{data:0256b}"]).reshape(16, 16)

        def count_alive_neighbors(x, y):
            count = 0
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue
                    nx, ny = (x + dx) % 16, (y + dy) % 16
                    count += grid[nx, ny]
            return count

        if load:
            return grid.flatten().tolist()  

        new_grid = grid.copy()
        for i in range(16):
            for j in range(16):
                alive_neighbors = count_alive_neighbors(i, j)
                if grid[i, j] == 1:
                    if alive_neighbors < 2 or alive_neighbors > 3:
                        new_grid[i, j] = 0
                else:
                    if alive_neighbors == 3:
                        new_grid[i, j] = 1

        return new_grid.flatten().tolist()
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
