class GoldenDUT:
    def __init__(self):
        # Internal registers to hold state
        self.x_reg = 0  # Input register, initializes to 0
        self.z_reg = 0  # Output register, initializes to 0
        self.raw_input = []

    def load(self, signal_vector):
        # Load the input signals and update internal state
        if signal_vector['areset']:
            self.x_reg = 0  # On reset, clear the input register
            self.z_reg = 0  # Clear the output register
            self.raw_input.clear()  # Clear the stored input bits
        else:
            # Only process if 'areset' is not asserted (i.e. machine is active)
            self.raw_input.append(signal_vector['x'])  # Store raw inputs
            self.x_reg = self.create_binary_representation()  # Create a binary representation

            # Calculate the 2's complement
            self.z_reg = self.calculate_two_complement(self.x_reg)

    def create_binary_representation(self):
        value = 0
        for i, bit in enumerate(reversed(self.raw_input)):
            value += bit << i  # Create binary value from bits
        return value

    def calculate_two_complement(self, value):
        bits_length = len(self.raw_input)
        comp = (1 << bits_length) - value  # 2's complement calculation
        return comp & ((1 << bits_length) - 1)  # Mask to keep within bit width

    def check(self, signal_vector):
        a_observed = signal_vector['z']
        scenario = signal_vector['scenario']
        expected_value = self.z_reg

        if a_observed != expected_value:
            print(f"Scenario: {scenario}, expected: z={expected_value}, observed z={a_observed}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
