class GoldenDUT:
    def __init__(self):
        # No inner states needed; logic is stateless
        pass

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        current_state = signal_vector['state']
        next_state, out1, out2 = self.calculate_expected_outputs(in_signal, current_state)
        return {'next_state': next_state, 'out1': out1, 'out2': out2}

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        return (expected_output['next_state'] == signal_vector['next_state'] and
                expected_output['out1'] == signal_vector['out1'] and
                expected_output['out2'] == signal_vector['out2'])

    def calculate_expected_outputs(self, in_signal, current_state):
        out1, out2 = 0, 0

        if current_state == 0b0000000001:  # S0
            if in_signal == 0:
                next_state = 0b0000000001  # S0
            else:
                next_state = 0b0000000010  # S1

        elif current_state == 0b0000000010:  # S1
            if in_signal == 0:
                next_state = 0b0000000001  # S0
            else:
                next_state = 0b0000000100  # S2

        elif current_state == 0b0000000100:  # S2
            if in_signal == 0:
                next_state = 0b0000000001  # S0
            else:
                next_state = 0b0000001000  # S3

        elif current_state == 0b0000001000:  # S3
            if in_signal == 0:
                next_state = 0b0000000001  # S0
            else:
                next_state = 0b0000010000  # S4

        elif current_state == 0b0000010000:  # S4
            if in_signal == 0:
                next_state = 0b0000000001  # S0
            else:
                next_state = 0b0000100000  # S5

        elif current_state == 0b0000100000:  # S5
            if in_signal == 0:
                next_state = 0b0001000000  # S8
                out1, out2 = 1, 0  # Correct output for S5 when in = 0
            else:
                next_state = 0b0000010000  # S6

        elif current_state == 0b0001000000:  # S6
            if in_signal == 0:
                next_state = 0b0010000000  # S9
                out1, out2 = 0, 0  # Outputs remain zero when transitioning to S9
            else:
                next_state = 0b0000000000  # Invalid state, stay in S7

        elif current_state == 0b0010000000:  # S7
            if in_signal == 0:
                next_state = 0b0000000001  # S0
                out1, out2 = 0, 0  # Correct output for S7 when in = 0
            else:
                next_state = 0b0010000000  # Stay in S7, outputs remain (0, 0)

        elif current_state == 0b0100000000:  # S8
            if in_signal == 0:
                next_state = 0b0000000001  # S0
                out1, out2 = 1, 0  # Correct output for S8 when in = 0
            else:
                next_state = 0b0000000010  # S1

        elif current_state == 0b1000000000:  # S9
            if in_signal == 0:
                next_state = 0b0000000001  # S0
                out1, out2 = 1, 1  # Correct output for S9 when in = 0
            else:
                next_state = 0b0000000010  # S1

        return next_state, out1, out2
def check_dut(vectors_in):
