class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # 0: searching, 1: received first byte, 2: received second byte, 3: received third byte
        self.message_count_reg = 0  # Count complete messages
        self.done_reg = 0  # Output signal

    def load(self, signal_vector):
        reset = signal_vector['reset']
        in_signal = signal_vector['in']

        if reset:
            self.state_reg = 0
            self.message_count_reg = 0
            self.done_reg = 0
            return

        if self.state_reg == 0:  # Searching for message start
            if in_signal & 0b1000:  # Check if in[3] = 1
                self.state_reg = 1  # Move to first byte of message
                self.done_reg = 0  # Reset done since we're starting a new message
        elif self.state_reg == 1:
            self.state_reg = 2  # Move to second byte of message
        elif self.state_reg == 2:
            self.state_reg = 3  # Move to third byte of message
        elif self.state_reg == 3:
            self.done_reg = 1  # Message completed
            self.message_count_reg += 1
            self.state_reg = 0  # Reset to searching for the next message
        else:
            self.done_reg = 0  # No message completed

        # Additional check to reset state if we receive an invalid byte after starting
        if self.state_reg > 0 and not (in_signal & 0b1000):  # If in[3] is not 1 after first byte
            self.state_reg = 0  # Reset to searching for message start
            self.done_reg = 0  # Reset done if an invalid byte is received

    def check(self, signal_vector):
        expected_done_signal = self.done_reg

        observed_done_signal = signal_vector['done']

        # Reset done_reg for the next cycle after checking
        if self.state_reg == 3:  # If we just completed a message
            self.done_reg = 0  # Reset done_reg after message is completed

        if expected_done_signal != observed_done_signal:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done_signal}, observed done={observed_done_signal}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

