class GoldenDUT:
    def __init__(self):
        self.in_reg = 0x00  # 8-bit input
        self.done_reg = 0   # Output done signal
        self.message_bytes = 0  # To count the number of bytes received

    def load(self, signal_vector):
        self.in_reg = signal_vector['in'] & 0xFF  # Ensure it is 8-bit
        reset = signal_vector['reset']

        if reset:
            self.done_reg = 0
            self.message_bytes = 0
        else:
            if self.in_reg & 0b1000_0000:  # Check if in[3] (bit 7) is 1
                if self.message_bytes == 0:
                    self.message_bytes = 1  # Start of a new message
                elif self.message_bytes < 3:
                    self.message_bytes += 1  # Continue receiving the message
                if self.message_bytes == 3:
                    self.done_reg = 1  # Message completed
                    self.message_bytes = 0  # Reset message count for next message
            else:
                if self.message_bytes > 0:
                    self.done_reg = 0  # Continue within a message context
                else:
                    self.done_reg = 0  # Not in any message context
                # When the input byte is not a message byte, make sure to reset the message byte count if it's already in a context
                if self.message_bytes > 0 and self.in_reg & 0b1000_0000 == 0:
                    self.message_bytes = 0  # Reset if a non-message byte comes after message start

    def check(self, signal_vector):
        expected_done = self.done_reg
        observed_done = signal_vector['done']

        if expected_done != observed_done:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done}, observed done={observed_done}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

