class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # To track the FSM state
        self.bit_count_reg = 0  # To count received bits
        self.data_reg = 0  # To hold the received data byte
        self.done_reg = 0  # To indicate when a byte has been correctly received

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        # Active-high synchronous reset
        if reset_signal:
            self.state_reg = 0  # Reset state
            self.bit_count_reg = 0
            self.data_reg = 0
            self.done_reg = 0
            return

        # FSM logic for processing the input serial data
        if self.state_reg == 0:  # Idle state, waiting for a start bit
            if in_signal == 0:  # Start bit detected
                self.state_reg = 1  # Move to receiving state
                self.bit_count_reg = 0  # Reset bit count
                self.done_reg = 0  # Ensure done is low
        elif self.state_reg == 1:  # Receiving bits state
            if self.bit_count_reg < 8:  # Receiving data bits
                self.data_reg = (self.data_reg | (in_signal << self.bit_count_reg)) & 0xFF  # Store data
                self.bit_count_reg += 1
            else:  # After receiving 8 bits
                self.state_reg = 2  # Move to stop bit state
        elif self.state_reg == 2:  # Expecting stop bit
            if in_signal == 1:  # Stop bit detected
                self.done_reg = 1  # Indicate that we are done
                self.state_reg = 0  # Move back to idle state

    def check(self, signal_vector):
        expected_output = self.get_expected_output(signal_vector['scenario'])
        observed_out_byte = self.data_reg
        observed_done = self.done_reg

        if (observed_out_byte != expected_output[0]) or (observed_done != expected_output[1]):
            print(f"Scenario: {signal_vector['scenario']}, expected: out_byte={expected_output[0]}, observed out_byte={observed_out_byte}, expected done={expected_output[1]}, observed done={observed_done}")
            return False
        return True

    def get_expected_output(self, scenario):
        if scenario == 1:
            return (0, 0)  # Reset state
        elif scenario == 2:
            return (0, 0)  # After reset, waiting for start bit
        elif scenario == 3:
            return (0b11010010, 0)  # After receiving '11010010'
        elif scenario == 4:
            return (0b11010010, 1)  # After receiving stop bit, done asserted
        elif scenario == 5:
            return (0, 0)  # After another reset, again waiting for start bit
        elif scenario == 6:
            return (0b01100101, 0)  # After receiving '01100101'
        elif scenario == 7:
            return (0, 0)  # Missing stop bit, keep waiting
        elif scenario == 8:
            return (0b01100101, 1)  # After receiving stop bit, done asserted
        elif scenario == 9:
            return (0, 0)  # Waiting for another start bit
        elif scenario == 10:
            return (0b00011111, 0)  # After receiving '00011111'
        return (None, None)  # Default case
