class GoldenDUT:
    def __init__(self):
        # Initial states or parameters can be set here if needed
        pass

    def load(self, signal_vector):
        # Extract the input signal
        input_value = signal_vector['in']

        # Compute expected outputs based on the input
        return self.evaluate_dut_rules(input_value)

    def check(self, signal_vector):
        # Load expected values from signal_vector
        expected_outputs = self.load(signal_vector)

        # Extract actual outputs from DUT results in the signal_vector
        actual_outputs = [
            signal_vector['out_both'], 
            signal_vector['out_any'], 
            signal_vector['out_different']
        ]

        # Compare expected outputs with actual outputs
        return self.compare_outputs(expected_outputs, actual_outputs)

    def evaluate_dut_rules(self, in_vector):
        # Ensure the input is a 4-bit binary vector
        in_bits = [(in_vector >> i) & 1 for i in range(4)]  # Extracting bits in [0, 1, 2, 3]

        # Out_both: Compare current bits with the left neighbors
        out_both = [
            in_bits[1] & in_bits[0],  # Comparing in[1] and in[0]
            in_bits[2] & in_bits[1],  # Comparing in[2] and in[1]
            in_bits[3] & in_bits[2]   # Comparing in[3] and in[2]
        ]

        # Out_any: Compare current bits with the right neighbors
        out_any = [
            in_bits[0] | in_bits[1],  # Comparing in[0] and in[1]
            in_bits[1] | in_bits[2],  # Comparing in[1] and in[2]
            in_bits[2] | in_bits[3]   # Comparing in[2] and in[3]
        ]

        # Out_different: Compare current bits with the left neighbor (wrapping around for in[0])
        out_different = [
            in_bits[0] != in_bits[3],  # Comparing in[0] and in[3]
            in_bits[1] != in_bits[0],  # Comparing in[1] and in[0]
            in_bits[2] != in_bits[1],  # Comparing in[2] and in[1]
            in_bits[3] != in_bits[2]   # Comparing in[3] and in[2]
        ]

        return out_both, out_any, out_different

    def compare_outputs(self, expected_outputs, actual_outputs):
        # Check if expected outputs match the actual outputs
        for expected, actual in zip(expected_outputs, actual_outputs):
            if expected != actual:
                return False
        return True
