class GoldenDUT:
    def __init__(self):
        # Initial values or states of the golden DUT could be defined here if needed
        pass

    def load(self, signal_vector):
        in_value = signal_vector['in']
        expected_outputs = {
            'out_both': self.compute_out_both(in_value),
            'out_any': self.compute_out_any(in_value),
            'out_different': self.compute_out_different(in_value)
        }
        return expected_outputs

    def check(self, signal_vector, dut_output=None):  # Added default value for dut_output
        expected_output = self.load(signal_vector)
        return expected_output == dut_output

    def compute_out_both(self, in_value):
        # Calculate out_both: only out_both[2], out_both[1], out_both[0] are needed
        return [
            (in_value & 0b1000) >> 3 and (in_value & 0b0100) >> 2,  # out_both[2]: in[3] and in[2]
            (in_value & 0b0100) >> 2 and (in_value & 0b0010) >> 1,  # out_both[1]: in[2] and in[1]
            (in_value & 0b0010) >> 1 and (in_value & 0b0001)        # out_both[0]: in[1] and in[0]
        ]

    def compute_out_any(self, in_value):
        # Calculate out_any: only out_any[2], out_any[1], out_any[0] are needed
        return [
            (in_value & 0b0100) >> 2 or (in_value & 0b0010) >> 1,  # out_any[2]: in[2] or in[1]
            (in_value & 0b0010) >> 1 or (in_value & 0b0001),        # out_any[1]: in[1] or in[0]
            (in_value & 0b1000) >> 3 or (in_value & 0b0100) >> 2   # out_any[0]: in[3] or in[2] - FIXED
        ]

    def compute_out_different(self, in_value):
        # Calculate out_different: all four comparisons including wrapping
        return [
            (in_value & 0b1000) >> 3 != (in_value & 0b0100) >> 2,  # out_different[3]: in[3] vs in[2]
            (in_value & 0b0100) >> 2 != (in_value & 0b0010) >> 1,  # out_different[2]: in[2] vs in[1]
            (in_value & 0b0010) >> 1 != (in_value & 0b0001),        # out_different[1]: in[1] vs in[0]
            (in_value & 0b1000) >> 3 != (in_value & 0b0001)         # out_different[0]: in[3] vs in[0] (wrapping)
        ]
