import numpy as np

class GoldenDUT:
    def __init__(self):
        # No specific inner states needed for the golden DUT.
        pass

    def load(self, signal_vector):
        # Load the input signals from the signal_vector dictionary
        in_vector = [0] * 100
        for i in range(100):
            in_vector[i] = signal_vector.get('in', 0) >> i & 1

        return self.compute_expected_outputs(in_vector)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        out_both_expected, out_any_expected, out_different_expected = expected_outputs
        out_both_actual = signal_vector.get('out_both', 0)
        out_any_actual = signal_vector.get('out_any', 0)
        out_different_actual = signal_vector.get('out_different', 0)

        # Compare expected and actual output signals
        return (self.compare_outputs(out_both_expected, out_both_actual, 99) and
                self.compare_outputs(out_any_expected, out_any_actual, 99) and
                self.compare_outputs(out_different_expected, out_different_actual, 100))

    def compute_expected_outputs(self, in_vector):
        # Ensure the input is a 100-bit vector
        assert len(in_vector) == 100, "Input vector must be of length 100."

        out_both = np.zeros(99, dtype=int)  # output for both neighbors
        out_any = np.zeros(99, dtype=int)   # output for any neighbors
        out_different = np.zeros(100, dtype=int)  # output for different neighbors

        # Compute out_both: both current and left neighbor must be 1
        for i in range(99):
            out_both[i] = 1 if (in_vector[i] == 1 and in_vector[i + 1] == 1) else 0

        # Compute out_any: any current and right neighbor must be 1
        for i in range(99):
            out_any[i] = 1 if (in_vector[i] == 1 or in_vector[i + 1] == 1) else 0

        # Compute out_different: current must be different from left neighbor, with wrapping
        for i in range(100):
            out_different[i] = 1 if (in_vector[i] != in_vector[i - 1]) else 0

        # Correct the wrapping condition
        out_different[0] = 1 if (in_vector[0] != in_vector[99]) else 0

        return out_both, out_any, out_different

    def compare_outputs(self, expected, actual_signal, output_length):
        actual = [0] * output_length
        for i in range(output_length):
            actual[i] = actual_signal >> i & 1 if isinstance(actual_signal, int) else 0

        return np.array_equal(expected, actual)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

