import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize any inner states/values if needed
        pass

    def load(self, signal_vector):
        in_bits = self._decode_input(signal_vector['in'])
        expected_outputs = {
            'out_both': self._calculate_out_both(in_bits),
            'out_any': self._calculate_out_any(in_bits),
            'out_different': self._calculate_out_different(in_bits)
        }
        return expected_outputs

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        return (
            np.array_equal(expected_output['out_both'], signal_vector['out_both']) and 
            np.array_equal(expected_output['out_any'], signal_vector['out_any']) and 
            np.array_equal(expected_output['out_different'], signal_vector['out_different'])
        )

    def _decode_input(self, input_value):
        # Convert input value to an array of bits
        return np.array([int(bit) for bit in np.binary_repr(input_value, width=100)], dtype=np.int8)

    def _calculate_out_both(self, in_bits):
        out_both = np.zeros(99, dtype=np.int8)
        out_both = np.where((in_bits[1:100] == 1) & (in_bits[0:99] == 1), 1, 0)  # Check pairs (i, i-1)
        return out_both

    def _calculate_out_any(self, in_bits):
