            out_both[i] = (in_vector[i + 1] & in_vector[i])

        # Correct the calculation for out_any
        for i in range(99):
            out_any[i] = (in_vector[i] | in_vector[i + 1]) if i < 98 else (in_vector[i] | in_vector[i - 1])

