import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.history_register_reg = 0b0000000  # 7-bit history register
        self.PHT = np.zeros(128, dtype=np.uint8)  # 128 entries with 2-bit saturating counters

    def load(self, signal_vector):
        if signal_vector["areset"]:
            self.history_register_reg = 0b0000000  # Reset history register on areset
            self.PHT[:] = 0  # Reset PHT
            return

        # Handle Training and Prediction
        if signal_vector["train_valid"]:
            self.train_branch(
                signal_vector["train_pc"],
                signal_vector["train_history"],
                signal_vector["train_taken"],
                signal_vector["train_mispredicted"]
            )

        if signal_vector["predict_valid"]:
            # We only fetch the prediction after handling the training
            expected_taken, updated_history = self.predict_branch(signal_vector["predict_pc"])
            # If training was valid, the history register must reflect updated state
            if signal_vector["train_valid"]:
                # Update history based on the expected outcome of the training
                updated_history = self.history_register_reg

            return expected_taken, updated_history

    def train_branch(self, pc, history_reg, taken, mispredicted):
        index = (pc ^ history_reg) & 0b1111111  # 7-bit index
        entry = self.PHT[index]

        # Update the PHT based on training rules
        if taken:
            if entry < 3:  # 11 in binary (max count)
                entry += 1
        else:
            if entry > 0:
                entry -= 1
        self.PHT[index] = entry

        # Recover history if misprediction occurs
        if mispredicted:
            self.history_register_reg = history_reg

    def check(self, signal_vector):
        expected_taken, updated_history = self.predict_branch(signal_vector["predict_pc"])

        # Compare with DUT output
        if expected_taken != signal_vector["predict_taken"] or updated_history != self.history_register_reg:
            print(f"Scenario: {signal_vector['scenario']}, expected: taken={expected_taken}, observed taken={signal_vector['predict_taken']}")
            print(f"Scenario: {signal_vector['scenario']}, expected: history={updated_history}, observed history={signal_vector['predict_history']}")
            return False

        return True

    def predict_branch(self, pc):
        index = (pc ^ self.history_register_reg) & 0b1111111  # 7-bit index
        return (self.PHT[index] >> 1) & 0b1, self.history_register_reg  # (predict_taken, history_register)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
