class GoldenDUT:
    def __init__(self):
        # Define the states as one-hot encoded values
        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000
        }

    def load(self, signal_vector):
        current_state = signal_vector['y']
        w = signal_vector['w']
        return self.get_expected_outputs(current_state, w)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        actual_outputs = (signal_vector['Y2'], signal_vector['Y4'])
        return expected_outputs == actual_outputs

    def get_expected_outputs(self, current_state, w):
        Y2 = 0
        Y4 = 0

        # Logic based on state transitions
        if current_state == self.states['A']:
            Y2 = 0  # Remain in A
            Y4 = 0  # Outputs for state A

        elif current_state == self.states['B']:
            Y2 = 1 if w == 1 else 0  # Transition to D if w=1; else to C (Y2 become 0)
            Y4 = 0  # Outputs for state B

        elif current_state == self.states['C']:
            Y2 = 0 if w == 0 else 1  # Y2 becomes 1 if w=1 (transition to D)
            Y4 = 0  # Outputs for state C

        elif current_state == self.states['D']:
            Y2 = 1 if w == 1 else 0  # Transition back to A if w=1; else to F (Y2 becomes 1 if w=1)
            Y4 = 0  # Outputs for state D

        elif current_state == self.states['E']:
            Y2 = 0  # Remain in E (Y2 should always be 0)
            Y4 = 1 if w == 1 else 0  # Y4 is 1 when w=1 (outputs for state E)

        elif current_state == self.states['F']:
            Y2 = 1 if w == 1 else 0  # Transition to D if w=1; else to C
            Y4 = 1  # Outputs Y4=1 for state F, as it's the case.

        return Y2, Y4
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
