class GoldenDUT:
    def __init__(self):
        # Inner states/values of the golden DUT are defined here
        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000,
        }

    def one_hot_state_transition(self, y, w):
        # Logic for Y2 and Y4 based on the current state and input w
        Y2 = 0
        Y4 = 0

        if y == self.states['A']:
            Y2 = self.states['B'] if w == 0 else self.states['A']
        elif y == self.states['B']:
            Y2 = self.states['C'] if w == 0 else self.states['D']
        elif y == self.states['C']:
            Y2 = self.states['E'] if w == 0 else self.states['D']
        elif y == self.states['D']:
            Y2 = self.states['F'] if w == 0 else self.states['A']
        elif y == self.states['E']:
            Y2 = self.states['E'] if w == 0 else self.states['D']
        elif y == self.states['F']:
            Y2 = self.states['C'] if w == 0 else self.states['D']

        # The logic for Y4 must be defined according to the state machine details
        Y4 = 1 if (y == self.states['E'] and w == 1) or (y == self.states['F'] and w == 1) else 0

        # Correct expected transitions for Y2 according to the state machine design
        if y == self.states['A']:
            Y2 = self.states['B'] if w == 0 else self.states['A']
        elif y == self.states['B']:
            Y2 = self.states['C'] if w == 0 else self.states['D']
        elif y == self.states['C']:
            Y2 = self.states['E'] if w == 0 else self.states['D']
        elif y == self.states['D']:
            Y2 = self.states['F'] if w == 0 else self.states['A']
        elif y == self.states['E']:
            Y2 = self.states['E'] if w == 0 else self.states['D']
        elif y == self.states['F']:
            Y2 = self.states['C'] if w == 0 else self.states['D']

        return Y2, Y4

    def load(self, signal_vector):
        y = signal_vector['y']
        w = signal_vector['w']
        expected_y2, expected_y4 = self.one_hot_state_transition(y, w)
        return {'Y2': expected_y2, 'Y4': expected_y4}

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        return (expected_outputs['Y2'] == signal_vector['Y2']) and (expected_outputs['Y4'] == signal_vector['Y4'])
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
