            "S11": 0b0000000100,
            "S110": 0b0000001000,
            "B0": 0b0000010000,
            "B1": 0b0000100000,
            "B2": 0b0001000000,
            "B3": 0b0010000000,
            "Count": 0b0100000000,
            "Wait": 0b1000000000,
        }

