                next_state = self.states["S1"]
        elif current_state == self.states["S1"]:
            if d == 1:
                next_state = self.states["S11"]
            elif d == 0:
                next_state = self.states["S"]
        elif current_state == self.states["S11"]:
            if d == 1:
                next_state = self.states["S11"]
            elif d == 0:
                next_state = self.states["S110"]
        elif current_state == self.states["S110"]:
            if d == 1:
                next_state = self.states["B0"]
            elif d == 0:
                next_state = self.states["S"]
        elif current_state == self.states["B0"]:
            outputs['shift_ena'] = 1
            next_state = self.states["B1"]
        elif current_state == self.states["B1"]:
            outputs['shift_ena'] = 1
            next_state = self.states["B2"]
        elif current_state == self.states["B2"]:
            outputs['shift_ena'] = 1
            next_state = self.states["B3"]
        elif current_state == self.states["B3"]:
            outputs['shift_ena'] = 1
            if done_counting == 1:
                next_state = self.states["Count"]
        elif current_state == self.states["Count"]:
            outputs['counting'] = 1
            if done_counting == 0:
                next_state = self.states["Count"]
            elif done_counting == 1:
                next_state = self.states["Wait"]
        elif current_state == self.states["Wait"]:
            if ack == 1:
                next_state = self.states["S"]

