class GoldenDUT:
    def __init__(self):
        # Initialize inner states
        self.S = 0b0000000001
        self.S1 = 0b0000000010
        self.S11 = 0b0000000100
        self.S110 = 0b0000001000
        self.B0 = 0b0000010000
        self.B1 = 0b0000100000
        self.B2 = 0b0001000000
        self.B3 = 0b0010000000
        self.Count = 0b0100000000
        self.Wait = 0b1000000000

    def load(self, signal_vector):
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']
        state = signal_vector['state']

        B3_next = S_next = S1_next = Count_next = Wait_next = 0
        done = counting = shift_ena = 0

        # State transitions based on input 'd'
        if state == self.S:
            if d == 1:
                S1_next = 1  # Transition to S1
            else:
                S_next = 1  # Stay in S
        elif state == self.S1:
            if d == 0:
                S_next = 1  # Transition back to S
            else:
                S1_next = 1  # Transition to S11
        elif state == self.S11:
            if d == 0:
                S110_next = 1  # Transition to S110
            else:
                S1_next = 1  # Stay in S11
        elif state == self.S110:
            if d == 0:
                S_next = 1  # Transition back to S
            else:
                B3_next = 1  # Transition to B0
        elif state == self.B0:
            shift_ena = 1  # Transition to B1
            B1_next = 1
        elif state == self.B1:
            shift_ena = 1  # Transition to B2
            B2_next = 1
        elif state == self.B2:
            shift_ena = 1  # Transition to B3
            B3_next = 1
        elif state == self.B3:
            shift_ena = 1  # Stay in B3
            Count_next = 1  # Transition to Count
        elif state == self.Count:
            counting = 1  # Stay in Count
            if done_counting == 1:
                Wait_next = 1  # Transition to Wait
        elif state == self.Wait:
            done = 1
            if ack == 1:
                S_next = 1  # Transition back to S

        return (B3_next, S_next, S1_next, Count_next, Wait_next, done, counting, shift_ena)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        outputs = (
            signal_vector.get('B3_next', 0),
            signal_vector.get('S_next', 0),
            signal_vector.get('S1_next', 0),
            signal_vector.get('Count_next', 0),
            signal_vector.get('Wait_next', 0),
            signal_vector.get('done', 0),
            signal_vector.get('counting', 0),
            signal_vector.get('shift_ena', 0)
        )
        return expected_outputs == outputs
