class GoldenDUT:
    def __init__(self):
        # Inner state initialization
        self.states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000
        }

    def load(self, signal_vector):
        # Load inputs
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']
        state = signal_vector['state']

        # Compute expected outputs
        return self.moore_state_machine_rules(d, done_counting, ack, state)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        # Compare expected outputs with actual DUT outputs
        return (expected_outputs == (
            signal_vector['B3_next'],
            signal_vector['S_next'],
            signal_vector['S1_next'],
            signal_vector['Count_next'],
            signal_vector['Wait_next'],
            signal_vector['done'],
            signal_vector['counting'],
            signal_vector['shift_ena']
        ))

    def moore_state_machine_rules(self, d, done_counting, ack, state):
        # Initialize outputs
        B3_next = 0
        S_next = 0
        S1_next = 0
        Count_next = 0
        Wait_next = 0
        done = 0
        counting = 0
        shift_ena = 0

        # State transitions and output logic
        if state == self.states['S']:
            if d == 0:
                S_next = 1
            elif d == 1:
                S1_next = 1

        elif state == self.states['S1']:
            if d == 0:
                S_next = 1
            elif d == 1:
                S1_next = 1

        elif state == self.states['S11']:
            if d == 0:
                S_next = 1
            elif d == 1:
                S1_next = 1  # Correcting logic to properly handle input d = 1

        elif state == self.states['S110']:
            if d == 0:
                S_next = 1
            elif d == 1:
                B0_next = 1

        elif state == self.states['B0']:
            shift_ena = 1

        elif state == self.states['B1']:
            shift_ena = 1

        elif state == self.states['B2']:
            shift_ena = 1

        elif state == self.states['B3']:
            shift_ena = 1
            Count_next = 1

        elif state == self.states['Count']:
            counting = 1
            if done_counting == 1:
                Wait_next = 1

        elif state == self.states['Wait']:
            if done == 1:
                if ack == 0:
                    Wait_next = 1
                elif ack == 1:
                    S_next = 1

        # The done signal is high when in the Wait state and ack is high (transition to S)
        done = 1 if state == self.states['Wait'] and ack == 1 else 0

        return (B3_next, S_next, S1_next, Count_next, Wait_next, done, counting, shift_ena)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

