    def __init__(self):
        # Inner states for the golden DUT
        self.states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000,
        }
        self.current_state = self.states['S']

    def load(self, signal_vector):
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']

        # Compute the next state based on current state and input d
        next_state = self.transition(self.current_state, d, done_counting, ack)
        # Update the current state for next call
        self.current_state = next_state
        outputs = self.compute_outputs(next_state, done_counting, ack)

        return outputs

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        # Compare with actual outputs from DUT
