import numpy as np

class GoldenDUT:
    def __init__(self):
        self.state_reg = 0  # Initial state of the FSM
        self.start_shifting_reg = 0  # Output signal

    def load(self, signal_vector):
        reset = signal_vector['reset']
        data = signal_vector['data']

        if reset:  # If reset is active
            self.state_reg = 0  # Reset the state
            self.start_shifting_reg = 0  # start_shifting should be 0
        else:
            # State transition logic based on the current data
            if self.state_reg == 0:  # Initial state
                if data == 1:
                    self.state_reg = 1
            elif self.state_reg == 1:  # Received first 1
                if data == 1:
                    self.state_reg = 2
                else:
                    self.state_reg = 0
            elif self.state_reg == 2:  # Received 11
                if data == 0:
                    self.state_reg = 3
            elif self.state_reg == 3:  # Received 110
                if data == 1:
                    self.state_reg = 4  # Sequence 1101 detected
            elif self.state_reg == 4:  # Sequence detected
                self.state_reg = 4  # Stay in this state as we already detected

            # Determine the output based on the state
            if self.state_reg == 4:
                self.start_shifting_reg = 1  # Activate output
            else:
                self.start_shifting_reg = 0  # Deactivate output

    def check(self, signal_vector):
        expected_start_shifting = self.start_shifting_reg
        observed_start_shifting = signal_vector['start_shifting']

        if expected_start_shifting != observed_start_shifting:
            print(f"Scenario: {signal_vector['scenario']}, expected: start_shifting={expected_start_shifting}, observed start_shifting={observed_start_shifting}")
            return False
        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

