        ena = signal_vector['ena']
        amount = signal_vector['amount']
        data = signal_vector['data']

        if load:  # Load the data into the register
            self.q_reg = data & 0xFFFFFFFFFFFFFFFF  # Ensure it's a 64-bit value
            self.is_loaded = True  # Mark that the register has been loaded
        elif ena:  # Perform shifting operation only if enable is high
            if amount == 0b00 and self.is_loaded:  # Shift left by 1 bit
                self.q_reg = (self.q_reg << 1) & 0xFFFFFFFFFFFFFFFF
            elif amount == 0b01 and self.is_loaded:  # Shift left by 8 bits
                self.q_reg = (self.q_reg << 8) & 0xFFFFFFFFFFFFFFFF
            elif amount == 0b10 and self.is_loaded:  # Arithmetic right shift by 1 bit
                self.q_reg = (self.q_reg >> 1) | (0x8000000000000000 if self.q_reg & 0x8000000000000000 else 0)
            elif amount == 0b11 and self.is_loaded:  # Arithmetic right shift by 8 bits
                self.q_reg = (self.q_reg >> 8) | (0x8000000000000000 if self.q_reg & 0x8000000000000000 else 0)

