    def __init__(self):
        self.count_reg = 0  # Internal counter initialized to 0
        self.tc_reg = 0     # Terminal count signal initialized to 0

    def load(self, signal_vector):
        load = signal_vector['load']
        data = signal_vector['data']

        if load == 1:
            # Load the internal counter with data and reset tc_reg
            self.count_reg = data & 0x3FF  # Mask to ensure it's 10 bits
            self.tc_reg = 0  # Reset terminal count signal
        elif load == 0:
            # Decrement the counter if it's greater than 0
            if self.count_reg > 0:
                self.count_reg -= 1

        # Update tc_reg
        if self.count_reg == 0:
            self.tc_reg = 1
        else:
            self.tc_reg = 0

    def check(self, signal_vector):
        expected_tc = self.tc_reg
        observed_tc = signal_vector['tc']

        if expected_tc != observed_tc:
            print(f"Scenario: {signal_vector['scenario']}, expected: tc={expected_tc}, observed tc={observed_tc}")
