class GoldenDUT:
    def __init__(self):
        self.bit_length = 100  # Define the bit length of the input/output vectors

    def load(self, signal_vector):
        input_vector = self.convert_to_vector(signal_vector['in'])
        expected_output = self.expected_output(input_vector)
        return expected_output

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        output_vector = self.convert_to_vector(signal_vector['out'])
        return expected_output == output_vector

    def expected_output(self, input_vector):
        assert len(input_vector) == self.bit_length, "Input vector must be 100 bits."
        return input_vector[::-1]  # Reverse the vector

    def convert_to_vector(self, value):
        # Convert the decimal value to a list representing the bit vector
        if isinstance(value, int):
            # Ensure the value is converted to the corresponding 100-bit binary representation
            return [(value >> i) & 1 for i in reversed(range(self.bit_length))]
        else:
            # Assume the value is a binary string
            if isinstance(value, str):
                # Convert binary string to an integer
                value = int(value, 2)
                bit_vector = [(value >> i) & 1 for i in reversed(range(self.bit_length))]
                return self.ensure_bit_length(bit_vector)
            raise ValueError("Input value must be an integer or a binary string.")

    def ensure_bit_length(self, bit_vector):
        # Ensure the bit vector has the correct length of 100 bits, padding with zeros if necessary
        if len(bit_vector) < self.bit_length:
            return [0] * (self.bit_length - len(bit_vector)) + bit_vector
        return bit_vector

