        # Get the expected output
        expected_output = self.load(signal_vector)

        # Extract DUT output from the signal vector
        dut_output = signal_vector.get('out', 0)

        # Compare and return the result
        return expected_output == dut_output

    def to_binary_vector(self, in_signal):
        # Convert the input decimal number to a 100-bit binary vector
        binary_representation = np.zeros(100, dtype=np.uint8)
        for i in range(100):
            binary_representation[99 - i] = (in_signal >> i) & 1  # Store bits in reverse order
