        # Reverse the bits in the input vector
        return in_vector[::-1]  # Directly reverse the array

    def to_decimal_output(self, out_vector):
        # Convert the output binary vector back to a decimal number
        return sum((bit << i) for i, bit in enumerate(out_vector))

