class GoldenDUT:
    def __init__(self):
        # Internal states of the FSM
        self.state_reg = 'A'   # Initial state
        self.f_reg = 0         # Output f, initially 0
        self.g_reg = 0         # Output g, initially 0
        self.x_sequence = []    # To track the sequence of x inputs
        self.clock_cycle = 0   # To track the clock cycles

    def load(self, signal_vector):
        # Load inputs from the signal_vector
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        # Increase the clock cycle count
        self.clock_cycle += 1

        # State machine behavior as per DUT description
        if resetn == 0:
            self.state_reg = 'A'
            self.g_reg = 0
            self.f_reg = 0
            self.x_sequence = []  # Reset the sequence on reset
            return
        elif self.clock_cycle == 1:
            # Starting after reset
            self.state_reg = 'post_reset'
        elif self.clock_cycle == 2:
            if self.state_reg == 'post_reset':
                self.f_reg = 1  # Assert f for one cycle
                self.state_reg = 'monitor_x'
                self.x_sequence.append(x)  # Start tracking the first x
        elif self.clock_cycle >= 3:
            if self.state_reg == 'monitor_x':
                self.x_sequence.append(x)  # Track the sequences of x inputs
                if len(self.x_sequence) >= 3:
                    # Check for the sequence 1, 0, 1
                    if self.x_sequence[-3:] == [1, 0, 1]:
                        self.g_reg = 1  # Set g to 1
                        self.state_reg = 'monitor_y'
        # Monitoring y input when g is set to 1
        if self.g_reg == 1 and self.state_reg == 'monitor_y':
            if self.clock_cycle in [3, 4] and y == 1:
                self.g_reg = 1  # Maintain g at 1
            elif self.clock_cycle == 5:
                if y == 0:
                    # Maintain g = 1 while checking y
                    self.g_reg = 0  # Reset g if y is not asserted within 2 cycles
                    self.state_reg = 'monitor_y_after_g'  # Transition state

    def check(self, signal_vector):
        # Determine the expected output values
        expected_f = self.f_reg
        expected_g = self.g_reg

        # Output signals from DUT
        observed_f = signal_vector['f']
        observed_g = signal_vector['g']

        # Compare expected vs observed outputs
        if expected_f != observed_f:
            print(f"Scenario: {signal_vector['scenario']}, expected: f={expected_f}, observed f={observed_f}")
            return False
        if expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={expected_g}, observed g={observed_g}")
            return False

        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

