        return expected_output_value

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        actual_output = signal_vector['pos']
        return expected_output == actual_output

    def calculate_expected_output(self, input_vector):
        # Use bitwise operation to find the position of the first high bit
        position = 0
        if input_vector == 0:
            return position  # returns 0 if no bits are high

