class GoldenDUT:
    def __init__(self):
        self.a_reg = 1  # Starting value for 'a'
        self.q_reg = 4  # Initial output value for 'q' (from simulation at 5ns)

    def load(self, signal_vector):
        # Load input signals
        self.a_reg = signal_vector['a']
        # Here we handle the internal state as per behavior
        if self.a_reg == 0:
            # If 'a' is 0, increment 'q' (handling rollover)
            self.q_reg = (self.q_reg + 1) % 8  # q is 3 bits, so we mod by 8

    def check(self, signal_vector):
        # Check expected output against observed output
        observed_q = signal_vector['q']
        expected_q = self.q_reg

        if observed_q != expected_q:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={observed_q}")
            return False

        return True

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

