import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize the inner states of the Golden DUT
        self.q_reg = np.zeros(256, dtype=int)  # 16x16 grid represented as 1D vector
        self.load_signal = 0

    def load(self, signal_vector):
        # Load data into q at the next clock edge
        if signal_vector['load']:
            self.q_reg = np.array([(signal_vector['data'] >> i) & 1 for i in range(256)], dtype=int)

    def count_neighbors(self, r, c):
        # Count living neighbors for a toroidal grid
        neighbors = [
            self.q_reg[((r - 1) % 16) * 16 + (c - 1) % 16],
            self.q_reg[((r - 1) % 16) * 16 + c % 16],
            self.q_reg[((r - 1) % 16) * 16 + (c + 1) % 16],
            self.q_reg[(r % 16) * 16 + (c - 1) % 16],
            self.q_reg[(r % 16) * 16 + (c + 1) % 16],
            self.q_reg[((r + 1) % 16) * 16 + (c - 1) % 16],
            self.q_reg[((r + 1) % 16) * 16 + c % 16],
            self.q_reg[((r + 1) % 16) * 16 + (c + 1) % 16]
        ]
        return sum(neighbors)

    def advance_game_state(self):
        new_state = np.zeros(256, dtype=int)
        for r in range(16):
            for c in range(16):
                alive = self.q_reg[r * 16 + c] == 1
                neighbors_count = self.count_neighbors(r, c)

                if alive:
                    if neighbors_count < 2 or neighbors_count > 3:
                        new_state[r * 16 + c] = 0  # Cell dies
                    else:
                        new_state[r * 16 + c] = 1  # Cell stays alive
                else:
                    if neighbors_count == 3:
                        new_state[r * 16 + c] = 1  # Cell becomes alive

        self.q_reg = new_state

    def check(self, signal_vector):
        # Save the initial state before loading
        initial_state = self.q_reg.copy()

        # Load state based on signal_vector to replicate DUT behavior
        self.load(signal_vector)

        # Advance the state of the Golden DUT only if the load signal was 0 before
        if not initial_state.any() == self.q_reg.any():  # Indicating a change due to load
            self.advance_game_state()

        expected_output = self.q_reg.copy()
        observed_output = np.array([(signal_vector['q'] >> i) & 1 for i in range(256)], dtype=int)

        # Check against output
        if not np.array_equal(expected_output, observed_output):
            print(f"Scenario: {signal_vector['scenario']}, expected:\n{expected_output}, observed:\n{observed_output}")
            return False
        return True    
def check_dut(vectors_in):
