class GoldenDUT:
    def __init__(self):
        self.state_outputs = {
            0b0000000001: (0, 0),  # S0
            0b0000000010: (0, 0),  # S1
            0b0000000100: (0, 0),  # S2
            0b0000001000: (0, 0),  # S3
            0b0000010000: (0, 0),  # S4
            0b0000100000: (0, 0),  # S5
            0b0001000000: (0, 0),  # S6
            0b0010000000: (0, 1),  # S7
            0b0100000000: (1, 0),  # S8
            0b1000000000: (1, 1),  # S9
        }

    def load(self, signal_vector):
        current_state = signal_vector['state']
        input_signal = signal_vector['in']
        return self.compute_expected_outputs(current_state, input_signal)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        actual_outputs = (signal_vector['out1'], signal_vector['out2'])
        return expected_outputs == actual_outputs

    def compute_expected_outputs(self, state, input_signal):
        if state in self.state_outputs:
            out1, out2 = self.state_outputs[state]
            if state == 0b0000000001:  # S0
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0000000010:  # S1
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0000000100:  # S2
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0000001000:  # S3
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0000010000:  # S4
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0000100000:  # S5
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0001000000:  # S6
                return (0, 0) if input_signal == 0 else (0, 0)

            elif state == 0b0010000000:  # S7
                return (0, 1)  # stays in S7 with input 1

            elif state == 0b0100000000:  # S8
                return (1, 0) if input_signal == 0 else (0, 0)  # output corrected for input 1

            elif state == 0b1000000000:  # S9
                return (1, 1) if input_signal == 1 else (0, 0)  # output corrected for input 0

        return (0, 0)
