class GoldenDUT:
    def __init__(self):
        # Initialize inner states/values of GoldenDUT
        self.in_reg = 0x00
        self.out_bytes_reg = 0x000000
        self.done_reg = 0
        self.message_buffer = []
        self.state = 'IDLE'

    def load(self, signal_vector):
        # Load important input signals and change inner states accordingly
        self.reset_signal = signal_vector['reset']
        self.in_reg = signal_vector['in']

        if self.reset_signal:
            self.out_bytes_reg = 0x000000
            self.done_reg = 0
            self.message_buffer.clear()
            self.state = 'IDLE'
        else:
            self.process_input()

    def process_input(self):
        valid_start = 0b00001000  # in[3] is 1

        if self.state == 'IDLE':
            if self.in_reg & valid_start:
                self.message_buffer.append(self.in_reg)
                self.state = 'RECEIVING'

        elif self.state == 'RECEIVING':
            if self.in_reg & valid_start:
                # Add the valid start byte to the buffer
                self.message_buffer.append(self.in_reg)
            else:
                # If it's not a start byte, check if we have 3 bytes
                if len(self.message_buffer) < 3:
                    self.message_buffer.append(self.in_reg)
                if len(self.message_buffer) == 3:
                    self.out_bytes_reg = (self.message_buffer[0] << 16) | (self.message_buffer[1] << 8) | self.message_buffer[2]
                    self.done_reg = 1
                    self.message_buffer.clear()
                    self.state = 'IDLE'
                # If we don't have 3 bytes yet, we continue to receive data
                elif len(self.message_buffer) > 3:
                    self.message_buffer.clear() # Clear the buffer if more than 3 bytes
                    self.state = 'IDLE' # Reset to idle if invalid input

    def check(self, signal_vector):
        # Determine expected output values and compare them with DUT's outputs
        expected_done = signal_vector['done']
        expected_out_bytes = signal_vector['out_bytes']

        if self.done_reg != expected_done or self.out_bytes_reg != expected_out_bytes:
            print(f"Scenario: {signal_vector['scenario']}, expected: out_bytes={hex(self.out_bytes_reg)}, observed={hex(expected_out_bytes)}, expected: done={expected_done}, observed={self.done_reg}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

