class GoldenDUT:
    def __init__(self):
        self.output_both = None
        self.output_any = None
        self.output_different = None

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        out_both, out_any, out_different = self.expected_outputs(in_signal)

        self.output_both = out_both
        self.output_any = out_any
        self.output_different = out_different

        return {
            'out_both': self.output_both,
            'out_any': self.output_any,
            'out_different': self.output_different
        }

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        return (
            expected_outputs['out_both'] == signal_vector['out_both'] and
            expected_outputs['out_any'] == signal_vector['out_any'] and
            expected_outputs['out_different'] == signal_vector['out_different']
        )

    def expected_outputs(self, in_vector):
        in_bits = [int(bit) for bit in format(in_vector, '04b')]

        # Calculate out_both
        out_both = [
            in_bits[i] & in_bits[i + 1] for i in range(3)  # Checking only left neighbors
        ]

        # Calculate out_any
        out_any = [
            in_bits[i] | in_bits[i - 1] for i in range(3, 0, -1)  # Checking only right neighbors
        ]

        # Note: out_any will automatically be in the correct order due to the construction.

        # Calculate out_different
        out_different = [
            (in_bits[i] != in_bits[i - 1]) for i in range(4)
        ]
        out_different[0] = (in_bits[0] != in_bits[3])  # Wrap-around comparison

        return (out_both, out_any, out_different)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
