    def __init__(self):
        # Initialize any inner states if necessary
        pass

    def load(self, signal_vector):
        input_value = signal_vector['in']
        # Convert input decimal to a 4-bit binary representation
        input_vector = [(input_value >> i) & 1 for i in range(4)]

        out_both = self.compute_out_both(input_vector)
        out_any = self.compute_out_any(input_vector)
        out_different = self.compute_out_different(input_vector)

        return {
            'out_both': out_both,
            'out_any': out_any,
            'out_different': out_different
        }

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        DUT_outputs = {
            'out_both': signal_vector['out_both'],
            'out_any': signal_vector['out_any'],
            'out_different': signal_vector['out_different']
        }

        return (expected_outputs['out_both'] == DUT_outputs['out_both'] and
                expected_outputs['out_any'] == DUT_outputs['out_any'] and
                expected_outputs['out_different'] == DUT_outputs['out_different'])

    def compute_out_both(self, input_vector):
        return [
            0,  # out_both[0] is N/A
            input_vector[1] & input_vector[0],  # comparing in[1] with in[0]
            input_vector[2] & input_vector[1],  # comparing in[2] with in[1]
            input_vector[3] & input_vector[2]   # comparing in[3] with in[2]
        ]

    def compute_out_any(self, input_vector):
        return [
            input_vector[0] | input_vector[1],  # comparing in[0] with in[1]
            input_vector[1] | input_vector[2],  # comparing in[1] with in[2]
            input_vector[2] | input_vector[3],  # comparing in[2] with in[3]
            input_vector[3] | input_vector[0]   # comparing in[3] with in[0]
        ]

    def compute_out_different(self, input_vector):
        return [
            input_vector[0] != input_vector[3],  # wrapping around comparison
            input_vector[1] != input_vector[0],
            input_vector[2] != input_vector[1],
            input_vector[3] != input_vector[2]
        ]

