        expected_outputs = self.load(signal_vector)
        return self._compare_outputs(expected_outputs, signal_vector)

    def _compute_outputs(self, in_vector):
        # Convert the input into a binary format of length 100
        in_array = np.array([int(bit) for bit in bin(in_vector)[2:].zfill(100)], dtype=np.uint8)

        out_both = np.zeros(98, dtype=np.uint8)       # out_both[0] to out_both[98]
        out_any = np.zeros(99, dtype=np.uint8)        # out_any[0] to out_any[98]
        out_different = np.zeros(100, dtype=np.uint8) # out_different[0] to out_different[99]

        # Calculate out_both
        for i in range(98):
            out_both[i] = 1 if (in_array[i] == 1 and in_array[i + 1] == 1) else 0

        # Calculate out_any
        for i in range(99):
            if i != 98:  # For out_any[0] to out_any[97]
                out_any[i] = 1 if (in_array[i] == 1 or in_array[i + 1] == 1) else 0
            else:  # For out_any[98]
                out_any[i] = 1 if (in_array[i] == 1) else 0

        # Calculate out_different
        for i in range(100):
            left_neighbor = in_array[i - 1] if i > 0 else in_array[99]  # wrapping behavior
            out_different[i] = 1 if in_array[i] != left_neighbor else 0

        return {
            'out_both': out_both.tolist(),
            'out_any': out_any.tolist(),
            'out_different': out_different.tolist()
        }

    def _compare_outputs(self, expected_outputs, signal_vector):
        actual_out_both = signal_vector['out_both']
        actual_out_any = signal_vector['out_any']
        actual_out_different = signal_vector['out_different']

        # Compare expected outputs with actual outputs
        return (expected_outputs['out_both'] == actual_out_both and
                expected_outputs['out_any'] == actual_out_any and
                expected_outputs['out_different'] == actual_out_different)
