import numpy as np

class GoldenDUT:
    def __init__(self):
        # Initialize inner states or values if needed
        pass

    def load(self, signal_vector):
        in_bits = self.convert_to_bits(signal_vector['in'])
        expected_outputs = {
            "out_both": self.compute_out_both(in_bits),
            "out_any": self.compute_out_any(in_bits),
            "out_different": self.compute_out_different(in_bits)
        }
        return expected_outputs

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        return (np.array_equal(expected_outputs['out_both'], signal_vector['out_both']) and
                np.array_equal(expected_outputs['out_any'], signal_vector['out_any']) and
                np.array_equal(expected_outputs['out_different'], signal_vector['out_different']))

    def compute_out_both(self, in_bits):
        # Check pairs (in[i], in[i + 1]) for i from 0 to 98, wrapping at the end
        return np.array([(in_bits[i] and in_bits[i + 1]) for i in range(99)], dtype=int)

    def compute_out_any(self, in_bits):
        # Check pairs (in[i], in[i + 1]) for i from 0 to 98, with wrapping
        return np.array([(in_bits[i] or in_bits[(i + 1) % 100]) for i in range(99)], dtype=int)

    def compute_out_different(self, in_bits):
        out_different = np.array([0] * 100, dtype=int)
        for i in range(100):
            out_different[i] = 1 if in_bits[i] != in_bits[(i - 1) % 100] else 0
        return out_different

    def convert_to_bits(self, value):
        return np.array([int(bit) for bit in format(value, '0100b')], dtype=int)
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
