import numpy as np

class GoldenDUT:
    def __init__(self):
        self.num_bits = 100
        self.expected_output = {
            'out_both': np.zeros(self.num_bits - 1, dtype=int),
            'out_any': np.zeros(self.num_bits - 1, dtype=int),
            'out_different': np.zeros(self.num_bits, dtype=int)
        }

    def load(self, signal_vector):
        in_vector = [signal_vector['in'] >> i & 1 for i in range(self.num_bits)][::-1]  # Extract bits and reverse order
        self.expected_output['out_both'] = self.calculate_out_both(in_vector)
        self.expected_output['out_any'] = self.calculate_out_any(in_vector)
        self.expected_output['out_different'] = self.calculate_out_different(in_vector)
        return self.expected_output

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        return (
            np.array_equal(expected_outputs['out_both'], signal_vector['out_both']) and
            np.array_equal(expected_outputs['out_any'], signal_vector['out_any']) and
            np.array_equal(expected_outputs['out_different'], signal_vector['out_different'])
        )

    def calculate_out_both(self, in_vector):
        return [(in_vector[i] & in_vector[i - 1]) for i in range(1, self.num_bits)]  # Check both current and left neighbor

    def calculate_out_any(self, in_vector):
        return [(in_vector[i] | in_vector[i + 1]) for i in range(self.num_bits - 1)]  # Check current and right neighbor

    def calculate_out_different(self, in_vector):
        out_different = [(in_vector[i] != in_vector[i - 1]) for i in range(self.num_bits)]
        out_different[0] = (in_vector[0] != in_vector[-1])  # Wrapping case for the first and last bit
        return out_different
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

