class GoldenDUT:
    def __init__(self):
        # Define the states using one-hot encoding
        self.states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000,
        }

    def compute_rules(self, d, done_counting, ack, state):
        # Initialize outputs
        B3_next = False
        S_next = False
        S1_next = False
        Count_next = False
        Wait_next = False
        done = False
        counting = False
        shift_ena = False

        # Determine the next states and outputs based on the current state and inputs
        if state == self.states['S']:
            if d == 1:
                S1_next = True

        elif state == self.states['S1']:
            if d == 0:
                S_next = True
            elif d == 1:
                S11_next = True

        elif state == self.states['S11']:
            if d == 0:
                S110_next = True
            elif d == 1:
                S11_next = True

        elif state == self.states['S110']:
            if d == 0:
                S_next = True
            elif d == 1:
                B0_next = True

        elif state == self.states['B0']:
            shift_ena = True

        elif state == self.states['B1']:
            shift_ena = True

        elif state == self.states['B2']:
            shift_ena = True

        elif state == self.states['B3']:
            shift_ena = True
            B3_next = True

        elif state == self.states['Count']:
            counting = True
            if done_counting:
                Wait_next = True
                done = True  # Set done to true when transitioning to Wait

        elif state == self.states['Wait']:
            if ack == 0:
                Wait_next = True
            elif ack == 1:
                S_next = True

        # Define the expected outputs based on the logic above
        return {
            'B3_next': B3_next,
            'S_next': S_next,
            'S1_next': S1_next,
            'Count_next': Count_next,
