class GoldenDUT:
    def __init__(self):
        # State definitions in one-hot encoding
        self.states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000,
        }

    def load(self, signal_vector):
        state = signal_vector['state']  # current state
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']

        return self.calculate_outputs(state, d, done_counting, ack)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        return (
            expected_outputs[0] == signal_vector['B3_next'] and
            expected_outputs[1] == signal_vector['S_next'] and
            expected_outputs[2] == signal_vector['S1_next'] and
            expected_outputs[3] == signal_vector['Count_next'] and
            expected_outputs[4] == signal_vector['Wait_next'] and
            expected_outputs[5] == signal_vector['done'] and
            expected_outputs[6] == signal_vector['counting'] and
            expected_outputs[7] == signal_vector['shift_ena']
        )

    def calculate_outputs(self, state, d, done_counting, ack):
        outputs = [0] * 8  # B3_next, S_next, S1_next, Count_next, Wait_next, done, counting, shift_ena

        # Process state transitions and output logic
        if state == self.states['S']:
            if d == 1:
                outputs[1] = 1  # S_next = 1
        elif state == self.states['S1']:
            if d == 1:
                outputs[1] = 1  # S_next = 1
            elif d == 0:
                outputs[2] = 1  # S1_next = 1
        elif state == self.states['S11']:
            if d == 0:
                outputs[3] = 1  # Count_next = 1
        elif state == self.states['S110']:
            if d == 1:
                outputs[0] = 1  # B3_next = 1
        elif state == self.states['B0']:
            outputs[7] = 1  # shift_ena = 1
        elif state == self.states['B1']:
            outputs[7] = 1  # shift_ena = 1
        elif state == self.states['B2']:
            outputs[7] = 1  # shift_ena = 1
        elif state == self.states['B3']:
            outputs[6] = 1  # counting = 1
        elif state == self.states['Count']:
            if not done_counting:
                outputs[3] = 1  # Count_next = 1
            else:
                outputs[5] = 1  # done = 1
        elif state == self.states['Wait']:
            if ack == 1:
                outputs[1] = 1  # S_next = 1

        return (outputs[0], outputs[1], outputs[2], outputs[3], outputs[4], outputs[5], outputs[6], outputs[7])
