        return self.get_expected_outputs(d, done_counting, ack, state)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        actual_outputs = (
            signal_vector['B3_next'],
            signal_vector['S_next'],
            signal_vector['S1_next'],
            signal_vector['Count_next'],
            signal_vector['Wait_next'],
            signal_vector['done'],
            signal_vector['counting'],
            signal_vector['shift_ena']
        )

        return expected_outputs == actual_outputs

