        state_dict = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000,
        }

        # Initialize outputs
        B3_next = 0
        S_next = 0
        S1_next = 0
        Count_next = 0
        Wait_next = 0
        done = 0
        counting = 0
        shift_ena = 0

        # Determine the expected outputs based on current state and inputs
        if state == state_dict['S']:
            if d == 1:
                S1_next = 1
            else:
                S_next = 1
        elif state == state_dict['S1']:
            if d == 1:
                S1_next = 1
            else:
                S_next = 1
        elif state == state_dict['S11']:
            if d == 1:
                S1_next = 1
            else:
                Count_next = 1
        elif state == state_dict['S110']:
            if d == 1:
                Count_next = 1
            else:
                S_next = 1
        elif state == state_dict['B0']:
            shift_ena = 1
        elif state == state_dict['B1']:
            shift_ena = 1
        elif state == state_dict['B2']:
            shift_ena = 1
        elif state == state_dict['B3']:
            shift_ena = 1
        elif state == state_dict['Count']:
            counting = 1
            if done_counting == 1:
                Wait_next = 1
        elif state == state_dict['Wait']:
            done = 1
            if ack == 1:
                S_next = 1

        return B3_next, S_next, S1_next, Count_next, Wait_next, done, counting, shift_ena

