class GoldenDUT:
    def __init__(self):
        self.q_reg = 0x0  # Initial value of the shift register
        self.shift_ena = 0
        self.count_ena = 0

    def load(self, signal_vector):
        self.shift_ena = signal_vector['shift_ena']
        self.count_ena = signal_vector['count_ena']
        data = signal_vector['data']

        # Check the status of shift and count enables only if they are not simultaneously active
        if self.shift_ena == 1 and self.count_ena == 1:
            # According to the problem statement, we will only perform the shift
            self.q_reg = ((self.q_reg << 1) | data) & 0xF

        elif self.shift_ena == 1:
            # Shift in data (4-bit register), shift first
            self.q_reg = ((self.q_reg << 1) | data) & 0xF  # Ensuring it's a 4-bit value

        elif self.count_ena == 1:
            # To decrement we must check if we have already shifted before
            self.q_reg = (self.q_reg - 1) & 0xF  # Decrement the register
        # If both are 0, don't change the state of q_reg

    def check(self, signal_vector):
        expected_output = self.q_reg
        observed_output = signal_vector['q']

        if expected_output != observed_output:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_output}, observed q={observed_output}")
            return False
        return True
