class GoldenDUT:
    def __init__(self):
        # Define the state transitions and expected output values
        self.states = {
            'A': 0b000001,
            'B': 0b000010,
            'C': 0b000100,
            'D': 0b001000,
            'E': 0b010000,
            'F': 0b100000
        }

    def load(self, signal_vector):
        y = signal_vector['y']
        w = signal_vector['w']
        return self.expected_outputs(y, w)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        return (expected_outputs[0] == signal_vector['Y1']) and (expected_outputs[1] == signal_vector['Y3'])

    def expected_outputs(self, y, w):
        if y == self.states['A']:
            return (0, 0) if w == 0 else (1, 0)
        elif y == self.states['B']:
            return (0, 1) if w == 0 else (0, 0)
        elif y == self.states['C']:
            return (1, 0) if w == 0 else (0, 0)
        elif y == self.states['D']:
            return (0, 0) if w == 0 else (0, 0)  # remains unchanged
        elif y == self.states['E']:
            return (0, 0) if w == 0 else (0, 0)  # remains unchanged
        elif y == self.states['F']:
            return (0, 0) if w == 0 else (0, 1)  # updated to reflect y3's expected behavior
        else:
            raise ValueError("Invalid state value")
