class GoldenDUT:
    def __init__(self):
        # Initial state register
        self.state_reg = 0  # Starting in state A (0)
        self.g_reg = [0, 0, 0]  # Grants for g1, g2, g3

    def load(self, signal_vector):
        r1 = signal_vector['r'][0] if isinstance(signal_vector['r'], list) else signal_vector['r']  # First bit corresponds to r1
        r2 = signal_vector['r'][1] if isinstance(signal_vector['r'], list) else signal_vector['r']  # Second bit corresponds to r2
        r3 = signal_vector['r'][2] if isinstance(signal_vector['r'], list) else signal_vector['r']  # Third bit corresponds to r3

        if signal_vector['resetn'] == 0:  # Active-low reset
            self.state_reg = 0  # Reset to state A
            self.g_reg = [0, 0, 0]  # Reset grants
            return

        # State transition logic based on current state and inputs
        if self.state_reg == 0:  # State A
            if r1 == 1:
                self.g_reg = [1, 0, 0]  # Grant g1
                self.state_reg = 1  # Go to state B
            elif r2 == 1:
                self.g_reg = [0, 1, 0]  # Grant g2
                self.state_reg = 2  # Go to state C
            elif r3 == 1:
                self.g_reg = [0, 0, 1]  # Grant g3
                self.state_reg = 3  # Go to state D
            else:
                self.g_reg = [0, 0, 0]  # No grant, remain in A

        elif self.state_reg == 1:  # State B
            if r1 == 1:
                self.g_reg = [1, 0, 0]  # Remain in state B
            elif r1 == 0:
                self.g_reg = [0, 0, 0]  # Go back to state A
                self.state_reg = 0

        elif self.state_reg == 2:  # State C
            if r2 == 1:
                self.g_reg = [0, 1, 0]  # Remain in state C
            elif r2 == 0:
                self.g_reg = [0, 0, 0]  # Go back to state A
                self.state_reg = 0

        elif self.state_reg == 3:  # State D
            # In state D, no requests should grant, and reset to A
            self.g_reg = [0, 0, 0]
            self.state_reg = 0

        # Handle multiple requests in state A (scenarios 9 and 10)
        if self.state_reg == 0:
            if r1 == 1 and r3 == 1:
                self.g_reg = [1, 0, 0]  # Grant g1 due to higher priority, stay in A
            elif r2 == 1 and r3 == 1:
                self.g_reg = [0, 1, 0]  # Grant g2 due to higher priority over g3
            elif r1 == 1 and r2 == 1:
                self.g_reg = [1, 0, 0]  # Also grant g1 over g2 due to priority

    def check(self, signal_vector):
        expected_g = self.g_reg
        observed_g = signal_vector['g']

        if expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected: g={expected_g}, observed g={observed_g}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
