class GoldenDUT:
    def __init__(self):
        # Inner states of the FSM
        self.state_reg = 0  # Represents the state of FSM, 0 corresponds to state A
        self.f_reg = 0      # Output signal f
        self.g_reg = 0      # Output signal g
        self.clock_cycle = 0  # Clock cycle counter
        self.sequence_x = []  # To hold x values for g calculation
        self.y_activated = False  # To track if y condition is activated

    def load(self, signal_vector):
        self.clock_cycle += 1  # Increment clock cycle

        # Load input signals
        resetn = signal_vector['resetn']
        x = signal_vector['x']
        y = signal_vector['y']

        # Process resetn signal
        if resetn == 0:  # If reset is active (active low)
            self.state_reg = 0
            self.f_reg = 0
            self.g_reg = 0
            self.sequence_x = []
            self.y_activated = False

        else:
            if self.state_reg == 0:  # If in state A after reset
                self.f_reg = 1  # Output f should be 1 for one cycle after reset

            elif self.state_reg == 1:  # Transitioning to next state based on x
                self.sequence_x.append(x)

                if len(self.sequence_x) > 3:
                    self.sequence_x.pop(0)  # Keep the last three inputs

                if len(self.sequence_x) == 3 and self.sequence_x == [1, 0, 1]:
                    self.g_reg = 1  # Set g to 1 after receiving [1, 0, 1]
                    self.y_activated = True  # Activate y conditions

            # Check y condition when g is set to 1
            if self.g_reg == 1:
                if y == 1:
                    self.y_activated = True  # y has become 1
                else:
                    if self.y_activated:
                        self.y_activated = False  # out of y activation window
                    else:
                        self.g_reg = 0  # Set g = 0 permanently after 2 cycles with y = 0

        # Update state for the next clock cycle
        if self.f_reg == 1:
            self.state_reg = 1  # Move to state to check x and y after f

    def check(self, signal_vector):
        expected_f, expected_g = self.expected_outputs(signal_vector['scenario'], self.clock_cycle, self.sequence_x)

        # Compare with observed outputs
        observed_f = signal_vector['f']
        observed_g = signal_vector['g']

        if expected_f != observed_f:
            print(f"Scenario: {signal_vector['scenario']}, expected f={expected_f}, observed f={observed_f}")
            return False
        if expected_g != observed_g:
            print(f"Scenario: {signal_vector['scenario']}, expected g={expected_g}, observed g={observed_g}")
            return False

        return True

    def expected_outputs(self, scenario, clock_cycles, x_sequence=None, y_sequence=None):
        f = 0
        g = 0

        if scenario == 1:  # Scenario 1: Reset and observe f
            if clock_cycles == 1:
                f = 1  # f should be 1 for one clock cycle after reset
            else:
                f = 0  # f remains 0 for all other clock cycles after reset is given

        if scenario == 2:  # Scenario 2: Apply x sequence to check g
            if x_sequence == [1, 0, 1] and clock_cycles >= 4:  # Three inputs in succession
                g = 1  # g should go high after the sequence

        if scenario == 3:  # Scenario 3: y equals 1 within 2 clock cycles
            if y_sequence is not None and len(y_sequence) <= 2 and 1 in y_sequence:  # y becomes 1 within 2 cycles
                g = 1  # g remains high if y is 1

        if scenario == 5:  # Scenario 5: y does not become 1
            if y_sequence is not None and y_sequence == [0, 0] and clock_cycles >= 3:  # y remains 0 for 2 cycles
                g = 0  # g should go low

        return f, g  # Return expected outputs f and g

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
