class GoldenDUT:
    def __init__(self):
        # No inner states are necessary for this class
        pass

    def load(self, signal_vector):
        input_value = signal_vector['in']
        expected_output = self.calculate_position(input_value)
        return expected_output

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        output_value = signal_vector['pos']
        return expected_output == output_value

    def calculate_position(self, input_value):
        if input_value == 0:
            return 0  # Default to zero if no bits are high
        # Find the least significant bit set to '1'
        pos = (input_value & -input_value).bit_length() - 1
        return pos

