class GoldenDUT:
    def __init__(self):
        # Initialize inner states
        self.a_reg = 0
        self.q_reg = 0

    def load(self, signal_vector):
        # Load input signals and update internal states
        self.a_reg = signal_vector['a']

        # Here we implement the logic according to the DUT described
        if signal_vector['check_en']:
            clock = 1  # This simulates the positive edge of the clock
            if clock == 1:
                if self.a_reg == 0:
                    self.q_reg = 1  # Set q to 1 on specific conditions
                elif self.a_reg == 1:
                    self.q_reg = 0  # On other conditions, set q to 0

    def check(self, signal_vector):
        # Check expected output against DUT output
        q_observed = signal_vector['q']  # From DUT, to be compared
        if signal_vector['check_en']:
            a_expected = self.a_reg
            # Check the output according to the observed q
            if self.a_reg == 0:
                expected_q = 1  # From description
            elif self.a_reg == 1:
                expected_q = 0

            # Validate the output
            if expected_q != q_observed:
                print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_q}, observed q={q_observed}")
                return False
        return True

    def reset(self):
        # Optional reset method to clear internal states
        self.a_reg = 0
        self.q_reg = 0

