            (0b01): 0b0001,  # c=0, d=1 -> mux_in[1]
            (0b10): 0b0001,  # c=1, d=0 -> mux_in[3] (Corrected according to K-map)
            (0b11): 0b0011   # c=1, d=1 -> mux_in[2] (Corrected according to K-map)
        }

