class GoldenDUT:
    def __init__(self):
        # Initialize internal states
        self.state_reg = "A"  # Start in state A
        self.z_reg = 0  # Output z

    def load(self, signal_vector):
        # Load the input signals
        areset = signal_vector['areset']
        x = signal_vector['x']

        # Asynchronous reset
        if areset:
            self.state_reg = "A"
            self.z_reg = 0
        else:
            # State transition based on the current state and input x
            if self.state_reg == "A":
                if x == 0:
                    self.z_reg = 0  # Stay in state A
                elif x == 1:
                    self.state_reg = "B"
                    self.z_reg = 1  # Transition to state B
            elif self.state_reg == "B":
                if x == 0:
                    self.z_reg = 1  # Stay in state B
                elif x == 1:
                    self.z_reg = 0  # Stay in state B

    def check(self, signal_vector):
        # Determine expected output
        expected_z = self.expected_output(self.state_reg, signal_vector['x'])
        observed_z = signal_vector['z']

        if expected_z != observed_z:
            print(f"Scenario: {signal_vector['scenario']}, expected: z={expected_z}, observed z={observed_z}")
            return False
        return True

    def expected_output(self, state: str, x: int) -> int:
        if state == 'A':
            return 0 if x == 0 else 1  # A --x=0 (z=0)--> A, A --x=1 (z=1)--> B
        elif state == 'B':
            return 1 if x == 0 else 0  # B --x=0 (z=1)--> B, B --x=1 (z=0)--> B
        else:
            raise ValueError("Invalid state")

def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

