class GoldenDUT:
    def __init__(self):
        self.bytes_received_reg = 0
        self.done_reg = 0
        self.current_state_reg = 0
        self.expected_done_reg = 0

    def load(self, signal_vector):
        in_signal = signal_vector['in']
        reset_signal = signal_vector['reset']

        if reset_signal:
            self.bytes_received_reg = 0
            self.done_reg = 0
            self.current_state_reg = 0
        else:
            if (in_signal >> 3) & 1:  # Check if in[3] is 1
                if self.current_state_reg == 0:  # Start of new message
                    self.bytes_received_reg = 1  # Reset count because it's valid first byte
                else:
                    self.bytes_received_reg += 1

                self.current_state_reg = 1
            elif self.current_state_reg == 1:  # If in a message and receiving bytes
                self.bytes_received_reg += 1

            if self.bytes_received_reg == 3:  # Three bytes received, signal done
                self.done_reg = 1
            else:
                self.done_reg = 0

            if self.bytes_received_reg > 3:  # Reset if more than 3 bytes are counted
                self.bytes_received_reg = 3

    def check(self, signal_vector):
        expected_done_signal = self.expected_done(signal_vector)
        observed_done_signal = signal_vector['done']

        if expected_done_signal != observed_done_signal:
            print(f"Scenario: {signal_vector['scenario']}, expected: done={expected_done_signal}, observed done={observed_done_signal}")
            return False

        return True

    def expected_done(self, signal_vector):
        scenario = signal_vector['scenario']
        if scenario == 1:
            return False
        elif scenario == 2:
            return self.bytes_received_reg == 3
        elif scenario == 3:
            return False
        elif scenario == 4:
            return self.bytes_received_reg == 3
        elif scenario == 5:
            return False  # Expecting no done signal after reset
        elif scenario == 6:
            return self.bytes_received_reg >= 3 and self.bytes_received_reg % 3 == 0
        elif scenario == 7:
            return self.bytes_received_reg >= 2 and self.bytes_received_reg <= 5

        return False
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

