import numpy as np

class GoldenDUT:
    def __init__(self):
        # Inner state initialization if needed
        pass

    def load(self, signal_vector):
        # Extract the input signal
        in_value = signal_vector['in']
        in_vector = self.decimal_to_binary_array(in_value)

        # Calculate the expected outputs
        out_both = self.calculate_out_both(in_vector)
        out_any = self.calculate_out_any(in_vector)
        out_different = self.calculate_out_different(in_vector)

        return {
            'out_both': out_both,
            'out_any': out_any,
            'out_different': out_different
        }

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        return (
            np.array_equal(expected_outputs['out_both'], signal_vector['out_both']) and
            np.array_equal(expected_outputs['out_any'], signal_vector['out_any']) and
            np.array_equal(expected_outputs['out_different'], signal_vector['out_different'])
        )

    def decimal_to_binary_array(self, decimal_value):
        # Convert the decimal input to a 4-bit binary array
        return np.array([(decimal_value >> i) & 1 for i in range(4)]).astype(int)

    def calculate_out_both(self, in_vector):
        return np.array([
            in_vector[3] & in_vector[2],  # out_both[2] = in[3] AND in[2]
            in_vector[2] & in_vector[1],  # out_both[1] = in[2] AND in[1]
            in_vector[1] & in_vector[0]   # out_both[0] = in[1] AND in[0]
        ])

    def calculate_out_any(self, in_vector):
        return np.array([
            in_vector[0] | in_vector[1],  # out_any[3] = in[0] OR in[1]
            in_vector[1] | in_vector[2],  # out_any[2] = in[1] OR in[2]
            in_vector[2] | in_vector[3]   # out_any[1] = in[2] OR in[3]
        ])

    def calculate_out_different(self, in_vector):
        return np.array([
            in_vector[0] != in_vector[3],  # Compare in[0] with in[3] (wrapping)
            in_vector[1] != in_vector[0],  # Compare in[1] with in[0]
            in_vector[2] != in_vector[1],  # Compare in[2] with in[1]
            in_vector[3] != in_vector[2]   # Compare in[3] with in[2]
        ])
def check_dut(vectors_in):
