        return (expected_outputs['out_both'] == signal_vector['out_both'] and
                expected_outputs['out_any'] == signal_vector['out_any'] and
                expected_outputs['out_different'] == signal_vector['out_different'])

    def compute_outputs(self, in_vector):
        out_both = self.compute_out_both(in_vector)
        out_any = self.compute_out_any(in_vector)
        out_different = self.compute_out_different(in_vector)
        return {
            'out_both': out_both,
            'out_any': out_any,
            'out_different': out_different
        }

    def compute_out_both(self, in_vector):
        # Correctly compute out_both considering the left neighbor including wrapping
        return [(in_vector[i] & in_vector[i + 1]) for i in range(3)] + [0]

    def compute_out_any(self, in_vector):
        # Correctly compute out_any considering the right neighbor including wrapping
        return [in_vector[i] | in_vector[(i + 1) % 4] for i in range(3)] + [0]

    def compute_out_different(self, in_vector):
        # Correctly compute out_different considering wrapping behavior
        return [(in_vector[i] ^ in_vector[(i + 1) % 4]) for i in range(4)]

