class GoldenDUT:
    def __init__(self):
        pass

    def load(self, signal_vector):
        in_val = signal_vector['in']
        return self.expected_outcomes(in_val)

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        return (
            expected_outputs['out_both'] == signal_vector['out_both'] and
            expected_outputs['out_any'] == signal_vector['out_any'] and
            expected_outputs['out_different'] == signal_vector['out_different']
        )

    def expected_outcomes(self, in_vector):
        # Convert the input vector to a binary representation
        in_bits = [int(bit) for bit in format(in_vector, '04b')]

        # Calculate out_both
        out_both = [
            in_bits[0] & in_bits[3],  # out_both[0] for in[0] and in[3]
            in_bits[1] & in_bits[0],  # out_both[1] for in[1] and in[0]
            in_bits[2] & in_bits[1]   # out_both[2] for in[2] and in[1]
        ]

        # Calculate out_any
        out_any = [
            in_bits[1] | in_bits[0],  # out_any[1] for in[1] or in[0]
            in_bits[2] | in_bits[1],  # out_any[2] for in[2] or in[1]
            in_bits[3] | in_bits[2]   # out_any[3] for in[3] or in[2]
        ]

        # Calculate out_different
        out_different = [
            in_bits[0] != in_bits[3],  # out_different[0] for in[0] and in[3]
            in_bits[1] != in_bits[0],  # out_different[1] for in[1] and in[0]
            in_bits[2] != in_bits[1],  # out_different[2] for in[2] and in[1]
            in_bits[3] != in_bits[2]   # out_different[3] for in[3] and in[2]
        ]

        return {
            "out_both": out_both,
            "out_any": out_any,
            "out_different": out_different
        }
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

