class GoldenDUT:
    def __init__(self):
        self.predict_history_reg = 0
        self.ase_reg = 0
        self.valid_reg = 0
        self.taken_reg = 0
        self.train_mispredicted_reg = 0
        self.train_taken_reg = 0
        self.train_history_reg = 0

    def load(self, signal_vector):
        self.ase_reg = signal_vector['areset']
        self.valid_reg = signal_vector['predict_valid']
        self.taken_reg = signal_vector['predict_taken']
        self.train_mispredicted_reg = signal_vector['train_mispredicted']
        self.train_taken_reg = signal_vector['train_taken']
        self.train_history_reg = signal_vector['train_history']

        if self.ase_reg:
            self.predict_history_reg = 0
        else:
            # Prioritize misprediction
            if self.train_mispredicted_reg:
                self.predict_history_reg = ((self.train_history_reg << 1) | self.train_taken_reg) & 0xFFFFFFFF
            elif self.valid_reg:
                # Shift the previous history and insert the taken value 
                self.predict_history_reg = ((self.predict_history_reg << 1) | self.taken_reg) & 0xFFFFFFFF

    def check(self, signal_vector):
        expected_predict_history = self.predict_history_reg

        if expected_predict_history != signal_vector['predict_history']:
            print(f"Scenario: {signal_vector['scenario']}, expected: predict_history={expected_predict_history}, observed={signal_vector['predict_history']}")
            return False
        return True
