class GoldenDUT:
    def __init__(self):
        # Initialize internal states with default values
        self.walk_left_reg = 0  # State to represent walking left
        self.walk_right_reg = 0  # State to represent walking right
        self.aaah_reg = 0  # State to represent falling
        self.digging_reg = 0  # State to represent digging

    def load(self, signal_vector):
        # Load input signals from the signal vector
        bump_left = signal_vector['bump_left']
        bump_right = signal_vector['bump_right']
        ground = signal_vector['ground']
        dig = signal_vector['dig']

        if signal_vector['areset'] == 1:
            self.walk_left_reg = 1
            self.walk_right_reg = 0
            self.aaah_reg = 0
            self.digging_reg = 0
        else:
            # Handle falling first
            if ground == 0:
                self.walk_left_reg = 0
                self.walk_right_reg = 0
                self.aaah_reg = 1
                # Do not dig when falling, keep digging_reg unchanged
            else:
                # If the Lemming is digging, do not change direction
                if self.digging_reg == 1:
                    self.digging_reg = 1
                else:
                    # Process bumps only if NOT digging
                    if bump_left:
                        self.walk_left_reg = 0
                        self.walk_right_reg = 1
                    if bump_right:
                        self.walk_left_reg = 1
                        self.walk_right_reg = 0

                # Process dig command if Lemming is walking (not in digging state)
                if dig and (self.walk_left_reg + self.walk_right_reg == 1) and self.aaah_reg == 0:
                    self.digging_reg = 1

    def check(self, signal_vector):
        # Determine expected outputs
        expected_walk_left = self.walk_left_reg
        expected_walk_right = self.walk_right_reg
        expected_aaah = self.aaah_reg
        expected_digging = self.digging_reg

