class GoldenDUT:
    def __init__(self):
        # Initial inner values of the golden DUT
        self.q_reg = 0b00001  # Initialize LFSR to reset state
        self.reset_reg = 0
        self.check_en_reg = False

    def galois_lfsr_tap(self, current_state):
        # Galois LFSR with taps at positions 5 and 3 (0-based indexing)
        tap_position_5 = (current_state >> 4) & 1  # 5th bit
        tap_position_3 = (current_state >> 2) & 1  # 3rd bit
        feedback_bit = tap_position_5 ^ tap_position_3
        # Shift left and add feedback bit at the LSB
        next_state = ((current_state << 1) & 0b11111) | feedback_bit
        return next_state

    def load(self, signal_vector):
        # Load input signals and change inner values accordingly
        self.reset_reg = signal_vector['reset']
        if self.reset_reg:
            self.q_reg = 0b00001  # Reset state
        else:
            # If not in reset and check_en is true, evolve the state
            if 'q' in signal_vector:
                # Load the state if provided in the signal_vector
                self.q_reg = signal_vector['q']

            # Always evaluate the state for the next clock cycle
            self.q_reg = self.galois_lfsr_tap(self.q_reg)

    def check(self, signal_vector):
        expected_output = self.q_reg
        observed_output = signal_vector['q']

        if expected_output != observed_output:
            print(f"Scenario: {signal_vector['scenario']}, expected: q={expected_output:05b}, observed q={observed_output:05b}")
            return False
        return True
def check_dut(vectors_in):
