class GoldenDUT:
    def __init__(self):
        # Initialize the state machine states
        self.states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0':  0b0000010000,
            'B1':  0b0000100000,
            'B2':  0b0001000000,
            'B3':  0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000,
        }

    def load(self, signal_vector):
        current_state = self.get_current_state(signal_vector)
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']

        return self.ideal_state_machine_rules(current_state, d, done_counting, ack)

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)

        # Compare with output signals from DUT based on given signal vector
        actual_output = {
            'B3_next': signal_vector.get('B3_next', 0),
            'S_next': signal_vector.get('S_next', 0),
            'S1_next': signal_vector.get('S1_next', 0),
            'Count_next': signal_vector.get('Count_next', 0),
            'Wait_next': signal_vector.get('Wait_next', 0),
            'done': signal_vector.get('done', 0),
            'counting': signal_vector.get('counting', 0),
            'shift_ena': signal_vector.get('shift_ena', 0),
        }

        return expected_output == actual_output

    def ideal_state_machine_rules(self, current_state, d, done_counting, ack):
        outputs = {
            'B3_next': 0,
            'S_next': 0,
            'S1_next': 0,
            'Count_next': 0,
            'Wait_next': 0,
            'done': 0,
            'counting': 0,
            'shift_ena': 0,
        }

        if current_state == self.states['S']:
            if d == 0:
                outputs['S_next'] = 1
            elif d == 1:
                outputs['S1_next'] = 1

        elif current_state == self.states['S1']:
            if d == 0:
                outputs['S_next'] = 1  # Handle S1->S correctly
            elif d == 1:
                outputs['S11'] = 1  # Transition S1 to S11

        elif current_state == self.states['S11']:
            if d == 0:
                outputs['S110'] = 1  # Transition S11 to S110
            elif d == 1:
                outputs['S1_next'] = 1  # Stay in S11

        elif current_state == self.states['S110']:
            if d == 0:
                outputs['S_next'] = 1
            elif d == 1:
                outputs['B0'] = 1  # Transition S110 to B0

        elif current_state == self.states['B0']:
            outputs['shift_ena'] = 1
            outputs['B1'] = 1  # B0 always transitions to B1

        elif current_state == self.states['B1']:
            outputs['shift_ena'] = 1
            outputs['B2'] = 1  # B1 always transitions to B2

        elif current_state == self.states['B2']:
            outputs['shift_ena'] = 1
            outputs['B3'] = 1  # B2 always transitions to B3

        elif current_state == self.states['B3']:
            outputs['shift_ena'] = 1
            outputs['Count_next'] = 1  # B3 transitions to Count when shift_ena is active

        elif current_state == self.states['Count']:
            outputs['counting'] = 1
            if not done_counting:
                outputs['Count_next'] = 1
            else:
                outputs['Wait_next'] = 1

        elif current_state == self.states['Wait']:
            outputs['done'] = 1
            if ack == 0:
                outputs['Wait_next'] = 1  # Remain in Wait state
            elif ack == 1:
                outputs['S_next'] = 1  # Transition back to S state

        return outputs

    def get_current_state(self, signal_vector):
        for state_name, state_value in self.states.items():
            if signal_vector['state'] == state_value:
                return state_value
        return None
