class GoldenDUT:
    def __init__(self):
        # Initial state
        self.current_state = 0b0000000001  # State S

    def load(self, signal_vector):
        d = signal_vector['d']
        done_counting = signal_vector['done_counting']
        ack = signal_vector['ack']

        # Compute next state logic
        next_state = self.determine_next_state(self.current_state, d, done_counting, ack)

        # Compute output logic
        outputs = {
            'done': self.compute_done(next_state, done_counting),
            'counting': self.compute_counting(next_state),
            'shift_ena': self.compute_shift_ena(next_state)
        }

        # Update the current state to the next state for future calls
        self.current_state = next_state

        return {'next_state': next_state, **outputs}

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)

        # Compare expected outputs with DUT outputs (assumed to be provided)
        return (
            expected_outputs['done'] == signal_vector['done'] and
            expected_outputs['counting'] == signal_vector['counting'] and
            expected_outputs['shift_ena'] == signal_vector['shift_ena']
        )

    def determine_next_state(self, current_state, d, done_counting, ack):
        # State encoding
        states = {
            'S': 0b0000000001,
            'S1': 0b0000000010,
            'S11': 0b0000000100,
            'S110': 0b0000001000,
            'B0': 0b0000010000,
            'B1': 0b0000100000,
            'B2': 0b0001000000,
            'B3': 0b0010000000,
            'Count': 0b0100000000,
            'Wait': 0b1000000000
        }

        if current_state == states['S']:
            return states['S1'] if d == 1 else states['S']
        elif current_state == states['S1']:
            return states['S11'] if d == 1 else states['S']
        elif current_state == states['S11']:
            return states['S11'] if d == 1 else states['S110']
        elif current_state == states['S110']:
            return states['B0'] if d == 1 else states['S']
        elif current_state == states['B0']:
            return states['B1']
        elif current_state == states['B1']:
            return states['B2']
        elif current_state == states['B2']:
            return states['B3']
        elif current_state == states['B3']:
            return states['Count']
        elif current_state == states['Count']:
            return states['Wait'] if done_counting == 1 else states['Count']
        elif current_state == states['Wait']:
            return states['S'] if ack == 1 else states['Wait']

    def compute_done(self, current_state, done_counting):
        # The 'done' signal should be set when in 'Wait' state and done_counting is 1
        return 1 if current_state == 0b1000000000 and done_counting == 1 else 0  # Wait state with done_counting

    def compute_counting(self, current_state):
        # The 'counting' signal should be set only when in the 'Count' state
        return 1 if current_state == 0b0100000000 else 0  # Count state

    def compute_shift_ena(self, current_state):
        # The 'shift_ena' signal should be set for states B0, B1, B2, and B3
        return 1 if current_state in (0b0000010000, 0b0000100000, 0b0001000000, 0b0010000000) else 0  # B0 to B3 states
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)

