class GoldenDUT:
    def __init__(self):
        # Initial state is S (10'b0000000001)
        self.state = 0b0000000001

    def load(self, signal_vector):
        d = signal_vector.get('d', 0)
        done_counting = signal_vector.get('done_counting', 0)
        ack = signal_vector.get('ack', 0)

        self.state_transition(d, done_counting, ack)

        # Get expected outputs
        expected_outputs = {
            'B3_next': int(self.state == 0b0010000000),  # B3 state
            'S_next': int(self.state == 0b0000000001),   # S state
            'S1_next': int(self.state == 0b0000000010),  # S1 state
            'Count_next': int(self.state == 0b0100000000), # Count state
            'Wait_next': int(self.state == 0b1000000000), # Wait state
            'done': int(self.state == 0b1000000000 and ack == 1),  # Done when in Wait state and ack is 1
            'counting': int(self.state == 0b0100000000),  # Counting when in Count state
            'shift_ena': int(self.state in [0b0000010000, 0b0000100000, 0b0001000000, 0b0010000000]), # Shift enables
        }

        return expected_outputs

    def check(self, signal_vector):
        expected_outputs = self.load(signal_vector)
        # Compare outputs with DUT outputs
        return all([expected_outputs[key] == signal_vector[key] for key in expected_outputs])

    def state_transition(self, d, done_counting, ack):
        # Define the current state
        if self.state == 0b0000000001:  # S
            if d == 0:
                self.state = 0b0000000001  # Stay in S
            elif d == 1:
                self.state = 0b0000000010  # Go to S1

        elif self.state == 0b0000000010:  # S1
            if d == 0:
                self.state = 0b0000000001  # Go to S
            elif d == 1:
                self.state = 0b0000000100  # Go to S11

        elif self.state == 0b0000000100:  # S11
            if d == 0:
                self.state = 0b0000001000  # Go to S110
            elif d == 1:
                self.state = 0b0000000100  # Stay in S11

        elif self.state == 0b0000001000:  # S110
            if d == 0:
                self.state = 0b0000000001  # Go to S
            elif d == 1:
                self.state = 0b0000010000  # Go to B0

        elif self.state in [0b0000010000, 0b0000100000, 0b0001000000]:  # B0 to B3
            # Move to the next B state; move to Count state if at B3
            if self.state < 0b0010000000:
                self.state <<= 1  # Shift left to move to the next B state
            else:
                self.state = 0b0100000000  # Go to Count state

        elif self.state == 0b0100000000:  # Count
            if done_counting == 0:
                self.state = 0b0100000000  # Stay in Count
            elif done_counting == 1:
                self.state = 0b1000000000  # Go to Wait

        elif self.state == 0b1000000000:  # Wait
            if ack == 0:
                self.state = 0b1000000000  # Stay in Wait
            elif ack == 1:
                self.state = 0b0000000001  # Go to S
