class GoldenDUT:
    def __init__(self):
        # Initialize register values
        self.data_reg = 0
        self.state_reg = 0  # State register for FSM
        self.start_shifting_reg = 0  # Output
        self.states = {'S0': 0, 'S1': 1, 'S2': 2, 'S3': 3}

    def load(self, signal_vector):
        # Load input signals
        self.data_reg = signal_vector['data']

        # Implement state transition logic based on the input data
        if signal_vector['reset'] == 1:  # Active high reset
            self.state_reg = self.states['S0']
            self.start_shifting_reg = 0  # Reset output
        else:
            if self.data_reg == 1:  # Input '1'
                if self.state_reg == self.states['S0']:
                    self.state_reg = self.states['S1']
                elif self.state_reg == self.states['S1']:
                    self.state_reg = self.states['S2']
                elif self.state_reg == self.states['S2']:
                    self.state_reg = self.states['S3']
                elif self.state_reg == self.states['S3']:
                    self.start_shifting_reg = 1  # Detected sequence 1101
            else:  # Input '0'
                self.state_reg = self.states['S0']  # Reset to initial state on '0'
                self.start_shifting_reg = 0  # Output is reset

    def check(self, signal_vector):
        # Expected output based on current state
        expected_output = self.start_shifting_reg

        # Check against observed output
        a_observed = signal_vector['start_shifting']

        if expected_output != a_observed:
            print(f"Scenario: {signal_vector['scenario']}, expected: start_shifting={expected_output}, observed start_shifting={a_observed}")
            return False

        return True

