class GoldenDUT:
    def __init__(self):
        self.counter_reg = 0  # Represents the 10-bit internal counter
        self.tc_reg = 1       # Terminal count, 1 means counter has not reached 0

    def load(self, signal_vector):
        load_signal = signal_vector['load']
        data_value = signal_vector['data']

        if load_signal:
            self.counter_reg = data_value & 0x3FF  # Load with 10-bit value, mask to ensure it's 10 bits

            # Set tc based on the loaded value
            self.tc_reg = 1 if self.counter_reg == 0 else 0
        else:
            if self.counter_reg > 0:
                self.counter_reg -= 1  # Decrement the counter

            # Update tc based on the current counter value
            self.tc_reg = 1 if self.counter_reg == 0 else 0

    def check(self, signal_vector):
        observed_tc = signal_vector['tc']
        expected_tc = self.tc_reg

        if observed_tc != expected_tc:
            print(f"Scenario: {signal_vector['scenario']}, expected: tc={expected_tc}, observed tc={observed_tc}")
            return False
        return True
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        if vector["check_en"]:
            check_pass = golden_dut.check(vector)
            if check_pass:
                print(f"Passed; vector: {vector}")
            else:
                print(f"Failed; vector: {vector}")
                failed_scenarios.append(vector["scenario"])
        golden_dut.load(vector)
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    signals = []
    lines = txt.strip().split("\n")
    for line in lines:
        signal = {}
        if line.startswith("[check]"):
            signal["check_en"] = True
            line = line[7:]
        elif line.startswith("scenario"):
            signal["check_en"] = False
        else:
            continue
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1].replace(" ", "")
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if ("x" not in value) and ("X" not in value) and ("z" not in value):
                    signal[key] = int(value)
                else:
                    if ("x" in value) or ("X" in value):
                        signal[key] = 0 # used to be "x"
                    else:
                        signal[key] = 0 # used to be "z"
        signals.append(signal)
    return signals
