class GoldenDUT:
    def __init__(self):
        # Inner states/values of the golden DUT (not actively used here)
        pass

    def load(self, signal_vector):
        a = signal_vector['a']
        b = signal_vector['b']
        c = signal_vector['c']
        d = signal_vector['d']
        e = signal_vector['e']
        return self.compute_expected_output(a, b, c, d, e)

    def check(self, signal_vector):
        expected_output = self.load(signal_vector)
        return expected_output == signal_vector['out']

    def compute_expected_output(self, a, b, c, d, e):
        # Create a 25-bit output vector initialized to 0
        out = [0] * 25

        # List of inputs
        inputs = [a, b, c, d, e]

        # Perform pairwise comparisons
        index = 0
        for i in range(5):
            for j in range(5):
                out[index] = int(inputs[i] == inputs[j])
                index += 1

        # Ensure that the output vector is a length of 25
        return out
def check_dut(vectors_in):
    golden_dut = GoldenDUT()
    failed_scenarios = []
    for vector in vectors_in:
        check_pass = golden_dut.check(vector)
        if check_pass:
            print(f"Passed; vector: {vector}")
        else:
            print(f"Failed; vector: {vector}")
            failed_scenarios.append(vector["scenario"])
    return failed_scenarios

def SignalTxt_to_dictlist(txt:str):
    lines = txt.strip().split("\n")
    signals = []
    for line in lines:
        signal = {}
        line = line.strip().split(", ")
        for item in line:
            if "scenario" in item:
                item = item.split(": ")
                signal["scenario"] = item[1]
            else:
                item = item.split(" = ")
                key = item[0]
                value = item[1]
                if "x" not in value and "z" not in value:
                    signal[key] = int(value)
                else:
                    signal[key] = value 
        signals.append(signal)
    return signals
with open("TBout.txt", "r") as f:
    txt = f.read()
vectors_in = SignalTxt_to_dictlist(txt)
tb_pass = check_dut(vectors_in)
print(tb_pass)
